INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d06ec3f5-8fe8-4089-a2ff-f361f14062ea', '病中初聞復官二首 二', '病中初闻复官二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["又挂朝衣一自驚，始知天意重推誠。","青雲有路通還去，白髮無私健亦生。","曾避暖池將浴鳳，却同寒谷乍遷鶯。","宦途巇嶮終難測，穩泊漁舟隱姓名。"]', '["又挂朝衣一自驚，始知天意重推誠。","青云有路通還去，白髮無私健亦生。","曾避暖池將浴鳳，却同寒谷乍遷鶯。","宦途巇嶮終难測，穩泊漁舟隐姓名。"]', '诗', 'shi', '', NULL, '病中初聞復官二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bc28de6-3e5b-4059-a301-7e60b46c845f', '早起五言三韻', '早起五言三韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["萬樹綠楊垂，千般黃鳥語。","庭花風雨餘，岑寂如村塢。","依依官渡頭，晴陽照行旅。"]', '["万樹綠楊垂，千般黄鸟語。","庭花风雨餘，岑寂如村塢。","依依官渡头，晴陽照行旅。"]', '诗', 'shi', '', NULL, '早起五言三韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b98edf8-48d2-482e-beef-c416b95cdd8e', '家書後批二十八字', '家书後批二十八字', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["四序風光總是愁，鬢毛衰颯涕橫流。","此書未到心先到，想在孤城海岸頭。"]', '["四序风光總是愁，鬢毛衰颯涕橫流。","此书未到心先到，想在孤城海岸头。"]', '诗', 'shi', '', NULL, '家書後批二十八字 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2b820b-c396-4ebb-b93f-489b28c58c26', '湖南梅花一冬再發偶題於花援', '湖南梅花一冬再發偶題於花援', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["湘浦梅花兩度開，直應天意別栽培。","玉爲通體依稀見，香號返魂容易迴。","寒氣與君霜裏退，陽和爲爾臘前來。","夭桃莫倚東風勢，調鼎何曾用不材。"]', '["湘浦梅花兩度开，直應天意別栽培。","玉爲通體依稀见，香號返魂容易迴。","寒氣與君霜裏退，陽和爲爾臘前来。","夭桃莫倚东风勢，調鼎何曾用不材。"]', '诗', 'shi', '', NULL, '湖南梅花一冬再發偶題於花援 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ebac0b9-d39b-4d8c-a323-8e2b42cec505', '即目二首 一', '即目二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["萬古離懷憎物色，幾生愁緒溺風光。","廢城沃土肥春草，野渡空船蕩夕陽。","倚道向人多脈脈，爲情因酒易倀倀。","宦途棄擲須甘分，迴避紅塵是所長。"]', '["万古離懷憎物色，幾生愁緒溺风光。","廢城沃土肥春草，野渡空船蕩夕陽。","倚道向人多脈脈，爲情因酒易倀倀。","宦途棄擲須甘分，迴避紅塵是所长。"]', '诗', 'shi', '', NULL, '即目二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f79b8b5-6f27-4542-98d7-89a2b4b10988', '即目二首 二', '即目二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["動非求進靜非禪，咋舌吞聲過十年。","溪漲浪花如積石，雨晴雲葉似連錢。","干戈歲久諳戎事，枕簟秋涼減夜眠。","攻苦慣來無不可，寸心如水但澄鮮。"]', '["动非求進静非禪，咋舌吞声過十年。","溪漲浪花如積石，雨晴云葉似連錢。","干戈歲久諳戎事，枕簟秋涼減夜眠。","攻苦慣来無不可，寸心如水但澄鲜。"]', '诗', 'shi', '', NULL, '即目二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67dd6f9-fb32-485c-8781-701254fc3631', '淨興寺杜鵑一枝繁豔無比', '淨兴寺杜鵑一枝繁豔無比', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一園紅豔醉坡陀，自地連梢簇蒨羅。","蜀魄未歸長滴血，秪應偏滴此叢多。"]', '["一园紅豔醉坡陀，自地連梢簇蒨羅。","蜀魄未归长滴血，秪應偏滴此叢多。"]', '诗', 'shi', '', NULL, '淨興寺杜鵑一枝繁豔無比 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e38a28c-13e1-4711-86f8-a3860c16e684', '花時與錢尊師同醉因成二十字', '花时與錢尊師同醉因成二十字', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["橋下淺深水，竹間紅白花。","酒仙同避世，何用厭長沙。"]', '["橋下淺深水，竹间紅白花。","酒仙同避世，何用厭长沙。"]', '诗', 'shi', '', NULL, '花時與錢尊師同醉因成二十字 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bf2b470-a30c-49a5-9d75-abf09cd3a42e', '避地', '避地', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["西山爽氣生襟袖，南浦離愁入夢魂。","人泊孤舟青草岸，鳥鳴高樹夕陽村。","偷生亦似符天意，未死深疑負國恩。","白面兒郎猶巧宦，不知誰與正乾坤。"]', '["西山爽氣生襟袖，南浦離愁入梦魂。","人泊孤舟青草岸，鸟鳴高樹夕陽村。","偷生亦似符天意，未死深疑負国恩。","白面兒郎猶巧宦，不知誰與正乾坤。"]', '诗', 'shi', '', NULL, '避地 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f62bd66-5042-4571-9125-22da01330d31', '息兵', '息兵', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["漸覺人心望息兵，老儒希覬見澄清。","正當困辱殊輕死，已過艱危却戀生。","多難始應彰勁節，至公安肯爲虛名。","暫時胯下何須恥，自有蒼蒼鑒赤誠。"]', '["漸覺人心望息兵，老儒希覬见澄清。","正當困辱殊轻死，已過艱危却戀生。","多难始應彰勁節，至公安肯爲虛名。","暫时胯下何須恥，自有蒼蒼鑒赤誠。"]', '诗', 'shi', '', NULL, '息兵 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddfbe663-408b-4b52-9daa-317560436361', '翠碧鳥', '翠碧鸟', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天長水遠網羅稀，保得重重翠碧衣。","挾彈小兒多害物，勸君莫近市朝飛。"]', '["天长水远網羅稀，保得重重翠碧衣。","挾彈小兒多害物，勸君莫近市朝飞。"]', '诗', 'shi', '', NULL, '翠碧鳥 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('260aeaf1-d0e3-47f7-b449-cf1e5057e712', '贈孫仁本尊師', '贈孫仁本尊師', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["齒如冰雪髮如黳，幾百年來醉似泥。","不共世人爭得失，臥牀前有上天梯。"]', '["齒如冰雪髮如黳，幾百年来醉似泥。","不共世人爭得失，臥牀前有上天梯。"]', '诗', 'shi', '', NULL, '贈孫仁本尊師 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('584e5fa8-968e-457a-91e5-80241a8a3508', '乙丑歲九月在蕭灘鎮駐泊兩月忽得商馬楊迢員外書賀余復除戎曹依舊承旨還緘後因書四十字', '乙丑歲九月在蕭灘鎮駐泊兩月忽得商马楊迢員外书賀余复除戎曹依旧承旨還緘後因书四十字', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["旅寓在江郊，秋風正寂寥。","紫泥虛寵獎，白髮已漁樵。","事往淒涼在，時危志氣銷。","若爲將朽質，猶擬杖於朝。"]', '["旅寓在江郊，秋风正寂寥。","紫泥虛寵獎，白髮已漁樵。","事往淒涼在，时危志氣銷。","若爲將朽質，猶擬杖於朝。"]', '诗', 'shi', '', NULL, '乙丑歲九月在蕭灘鎮駐泊兩月忽得商馬楊迢員外書賀余復除戎曹依舊承旨還緘後因書四十字 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('176971cd-5bec-4635-a60e-c892adfa164b', '丙寅二月二十二日撫州如歸館雨中有懷諸朝客', '丙寅二月二十二日撫州如归館雨中有懷諸朝客', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["悽悽惻惻又微嚬，欲話羇愁憶故人。","薄酒旋醒寒徹夜，好花虛謝雨藏春。","萍蓬已恨爲逋客，江嶺那知見侍臣。","未必交情繫貧富，柴門自古少車塵。"]', '["悽悽惻惻又微嚬，欲話羇愁憶故人。","薄酒旋醒寒徹夜，好花虛謝雨藏春。","萍蓬已恨爲逋客，江嶺那知见侍臣。","未必交情繫貧富，柴门自古少车塵。"]', '诗', 'shi', '', NULL, '丙寅二月二十二日撫州如歸館雨中有懷諸朝客 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f18d3ce2-c550-4690-98d9-d784e805cd88', '三月二十七日自撫州往南城縣舟行見拂水薔薇因有是作', '三月二十七日自撫州往南城縣舟行见拂水薔薇因有是作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["江中春雨波浪肥，石上野花枝葉瘦。","枝低波高如有情，浪去枝留如力鬬。","綠刺紅房戰褭時，吳娃越豔醺酣後。","且將濁酒伴清吟，酒逸吟狂輕宇宙。"]', '["江中春雨波浪肥，石上野花枝葉瘦。","枝低波高如有情，浪去枝留如力鬬。","綠刺紅房戰褭时，吳娃越豔醺酣後。","且將濁酒伴清吟，酒逸吟狂轻宇宙。"]', '诗', 'shi', '', NULL, '三月二十七日自撫州往南城縣舟行見拂水薔薇因有是作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f08d4d50-c82e-4dcc-a777-397ff768c1a2', '茘枝三首 一', '茘枝三首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["遐方不許貢珍奇，密詔唯教進茘枝。","漢武碧桃爭比得，枉令方朔號偷兒。"]', '["遐方不許貢珍奇，密詔唯教進茘枝。","漢武碧桃爭比得，枉令方朔號偷兒。"]', '诗', 'shi', '', NULL, '茘枝三首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('713f3f35-1318-4b7e-b18a-8c7b623f387b', '茘枝三首 二', '茘枝三首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["封開玉籠雞冠溼，葉襯金盤鶴頂鮮。","想得佳人微啓齒，翠釵先取一雙懸。"]', '["封开玉籠雞冠溼，葉襯金盤鹤頂鲜。","想得佳人微啓齒，翠釵先取一雙懸。"]', '诗', 'shi', '', NULL, '茘枝三首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346585f9-0ed0-4733-b088-471b183677df', '茘枝三首 三', '茘枝三首 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["巧裁霞片裹神漿，崖蜜天然有異香。","應是仙人金掌露，結成冰入蒨羅囊。"]', '["巧裁霞片裹神漿，崖蜜天然有異香。","應是仙人金掌露，結成冰入蒨羅囊。"]', '诗', 'shi', '', NULL, '茘枝三首 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dabc174-0df3-4f81-9195-6e536e15ddac', '寄上兄長', '寄上兄长', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["兩地支離路八千，襟懷悽愴鬢蒼然。","亂來未必長團會，其奈而今更長年。"]', '["兩地支離路八千，襟懷悽愴鬢蒼然。","亂来未必长團會，其奈而今更长年。"]', '诗', 'shi', '', NULL, '寄上兄長 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9abf25fa-e3e2-4cac-a45b-4c0277783815', '寶劒', '寶劒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["困極還應有甚通，難將糞壤掩神蹤。","斗間紫氣分明後，擘地成川看化龍。"]', '["困極還應有甚通，难將糞壤掩神蹤。","斗间紫氣分明後，擘地成川看化龙。"]', '诗', 'shi', '', NULL, '寶劒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('082be90b-d771-420e-b6bf-dc07121e5bda', '寶劒', '寶劒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["困極還應有日通，難將糞土掩神蹤。","但教出得豐城後，不是延津亦化龍。"]', '["困極還應有日通，难將糞土掩神蹤。","但教出得豐城後，不是延津亦化龙。"]', '诗', 'shi', '', NULL, '寶劒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e576d21d-834d-40ad-aeb7-328d5c7a1f17', '登南神光寺塔院', '登南神光寺塔院', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["無奈離腸日九迴，強攄離抱立高臺。","中華地向城邊盡，外國雲從島上來。","四序有花長見雨，一冬無雪却聞雷。","日宮紫氣生冠冕，試望扶桑病眼開。"]', '["無奈離腸日九迴，強攄離抱立高台。","中华地向城邊尽，外国云從島上来。","四序有花长见雨，一冬無雪却闻雷。","日宮紫氣生冠冕，試望扶桑病眼开。"]', '诗', 'shi', '', NULL, '登南神光寺塔院 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0a417bb-5d92-4c7c-a830-554b1d8cb98d', '兩賢', '兩賢', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["賣卜嚴將賣餅孫，兩賢高趣恐難倫。","而今若有逃名者，應被品流呼差人。"]', '["賣卜嚴將賣餅孫，兩賢高趣恐难倫。","而今若有逃名者，應被品流呼差人。"]', '诗', 'shi', '', NULL, '兩賢 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad82e842-d1cc-443f-a4cf-6bcc7511f00d', '再思', '再思', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["暴殄猶來是片時，無人向此略遲疑。","流金鑠石玉長潤，敗柳凋花松不知。","但保行藏天是證，莫矜纖巧鬼難欺。","近來更得窮經力，好事臨行亦再思。"]', '["暴殄猶来是片时，無人向此略遲疑。","流金鑠石玉长潤，敗柳凋花松不知。","但保行藏天是證，莫矜纖巧鬼难欺。","近来更得窮經力，好事臨行亦再思。"]', '诗', 'shi', '', NULL, '再思 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a80d1ec2-50b5-43b2-95fb-9d792053f79f', '有矚', '有矚', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["晚涼閑步向江亭，默默看書旋旋行。","風轉滯帆狂得勢，潮來諸水寂無聲。","誰將覆轍詢長策，願把棼絲屬老成。","安石本懷經濟意，何妨一起爲蒼生。"]', '["晚涼闲步向江亭，默默看书旋旋行。","风轉滯帆狂得勢，潮来諸水寂無声。","誰將覆轍詢长策，願把棼絲屬老成。","安石本懷經濟意，何妨一起爲蒼生。"]', '诗', 'shi', '', NULL, '有矚 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba8f897-d6dc-4816-ba8f-4897726e4542', '秋深閑興', '秋深闲兴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["此心兼笑野雲忙，甘得貧閑味甚長。","病起乍嘗新橘柚，秋深初換舊衣裳。","晴來喜鵲無窮語，雨後寒花特地香。","把釣覆棊兼舉白，不離名教可顚狂。"]', '["此心兼笑野云忙，甘得貧闲味甚长。","病起乍嘗新橘柚，秋深初換旧衣裳。","晴来喜鵲無窮語，雨後寒花特地香。","把釣覆棊兼舉白，不離名教可顚狂。"]', '诗', 'shi', '', NULL, '秋深閑興 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ae7341e-7d0f-4c6c-9d98-bfe1b2445fe9', '故都', '故都', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["故都遙想草萋萋，上帝深疑亦自迷。","塞雁已侵池籞宿，宮鴉猶戀女牆啼。","天涯烈士空垂涕，地下強魂必噬臍。","掩鼻計成終不覺，馮驩無路斅鳴雞。"]', '["故都遙想草萋萋，上帝深疑亦自迷。","塞雁已侵池籞宿，宮鴉猶戀女牆啼。","天涯烈士空垂涕，地下強魂必噬臍。","掩鼻計成終不覺，馮驩無路斅鳴雞。"]', '诗', 'shi', '', NULL, '故都 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e6fbc93-708e-4149-bd74-99bb56de6b5d', '夢仙', '梦仙', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["紫霄宮闕五雲芝，九級壇前再拜時。","鶴舞鹿眠春草遠，山高水闊夕陽遲。","每嗟阮肇歸何速，深羨張騫去不疑。","澡練純陽功力在，此心唯有玉皇知。"]', '["紫霄宮闕五云芝，九級壇前再拜时。","鹤舞鹿眠春草远，山高水闊夕陽遲。","每嗟阮肇归何速，深羨張騫去不疑。","澡練純陽功力在，此心唯有玉皇知。"]', '诗', 'shi', '', NULL, '夢仙 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7989cbbe-b32c-40ab-b648-da71f78730bd', '贈吳顚尊師', '贈吳顚尊師', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["飲酒經何代，休糧度此生。","跡應常自浼，顚亦強爲名。","道若千釣重，身如一羽輕。","毫釐分象緯，袒跣揖公卿。","狗竇號光逸，漁陽裸禰衡。","笑雷冬蟄震，巖電夜珠明。","月魄侵簪冷，江光逼屐清。","半酣思救世，一手擬扶傾。","擊地嗟衰俗，看天貯不平。","自緣懷氣義，可是計烹亨。","議論通三教，年顏稱五更。","老狂人不厭，密行鬼應驚。","未識心相許，開襟語便誠。","伊余常仗義，願拜十年兄。"]', '["饮酒經何代，休糧度此生。","跡應常自浼，顚亦強爲名。","道若千釣重，身如一羽轻。","毫釐分象緯，袒跣揖公卿。","狗竇號光逸，漁陽裸禰衡。","笑雷冬蟄震，巖電夜珠明。","月魄侵簪冷，江光逼屐清。","半酣思救世，一手擬扶傾。","擊地嗟衰俗，看天貯不平。","自緣懷氣義，可是計烹亨。","議論通三教，年顏稱五更。","老狂人不厭，密行鬼應驚。","未識心相許，开襟語便誠。","伊余常仗義，願拜十年兄。"]', '诗', 'shi', '', NULL, '贈吳顚尊師 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd08aef7-5242-4d04-8bb9-09411a11a8d8', '送人棄官入道', '送人棄官入道', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["仙李濃陰潤，皇枝密葉敷。","俊才輕折桂，捷徑取紆朱。","斷紲三清路，揚鞭五達衢。","側身期破的，縮手待呼盧。","社稷俄如綴，雄豪詎守株。","忸怩非壯志，擺脫是良圖。","塵土留難住，纓緌棄若無。","冥心歸大道，回首笑吾徒。","酒律應難忘，詩魔未肯徂。","他年如拔宅，爲我指清都。"]', '["仙李濃陰潤，皇枝密葉敷。","俊才轻折桂，捷徑取紆朱。","斷紲三清路，揚鞭五達衢。","側身期破的，縮手待呼盧。","社稷俄如綴，雄豪詎守株。","忸怩非壯志，擺脫是良圖。","塵土留难住，纓緌棄若無。","冥心归大道，回首笑吾徒。","酒律應难忘，诗魔未肯徂。","他年如拔宅，爲我指清都。"]', '诗', 'shi', '', NULL, '送人棄官入道 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f774d2c-5478-415d-9522-4ff467e5cd2d', '感事三十四韻', '感事三十四韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["紫殿承恩歲，金鑾入直年。","人歸三島路，日過八花塼。","鴛鷺皆迴席，臯夔亦慕羶。","慶霄舒羽翼，塵世有神仙。","雖遇河清聖，慙非岳降賢。","皇慈容散拙，公議逼陶甄。","江總參文會，陳暄侍狎筵。","腐儒親帝座，太史認星躔。","側弁聆神算，濡毫俟密宣。","宮司持玉研，書省擘香箋。","唯理心無黨，憐才膝屢前。","焦勞皆實錄，宵旰豈虛傳。","始議新堯曆，將期整舜弦。","去梯言必盡，仄席意彌堅。","上相思懲惡，中人詎省愆。","鹿窮唯觝觸，兔急且㺦猭。","本是謀賒死，因之致劫遷。","氛霾言下合，日月暗中懸。","恭顯誠甘罪，韋平亦恃權。","畏聞巢幕險，寧寤積薪然。","諒直尋鉗口，奸纖益比肩。","晉讒終不解，魯瘠竟難痊。","秪擬誅黃皓，何曾識霸先。","嗾獒飜醜正，養虎欲求全。","萬乘煙塵裏，千官劒戟邊。","斗魁當北坼，地軸向西偏。","袁董非徒爾，師昭豈偶然。","中原成劫火，東海遂桑田。","濺血慙嵇紹，遲行笑褚淵。","四夷同效順，一命敢虛捐。","山岳還青聳，穹蒼舊碧鮮。","獨夫長啜泣，多士已忘筌。","鬱鬱空狂叫，微微幾病癲。","丹梯倚寥廓，終去問青天。"]', '["紫殿承恩歲，金鑾入直年。","人归三島路，日過八花塼。","鴛鷺皆迴席，臯夔亦慕羶。","慶霄舒羽翼，塵世有神仙。","雖遇河清聖，慙非岳降賢。","皇慈容散拙，公議逼陶甄。","江總參文會，陳暄侍狎筵。","腐儒親帝座，太史認星躔。","側弁聆神算，濡毫俟密宣。","宮司持玉研，书省擘香箋。","唯理心無黨，怜才膝屢前。","焦勞皆實錄，宵旰豈虛傳。","始議新堯曆，將期整舜弦。","去梯言必尽，仄席意彌堅。","上相思懲惡，中人詎省愆。","鹿窮唯觝觸，兔急且㺦猭。","本是謀賒死，因之致劫遷。","氛霾言下合，日月暗中懸。","恭显誠甘罪，韋平亦恃權。","畏闻巢幕險，寧寤積薪然。","諒直尋鉗口，奸纖益比肩。","晉讒終不解，魯瘠竟难痊。","秪擬誅黄皓，何曾識霸先。","嗾獒飜醜正，養虎欲求全。","万乘煙塵裏，千官劒戟邊。","斗魁當北坼，地軸向西偏。","袁董非徒爾，師昭豈偶然。","中原成劫火，东海遂桑田。","濺血慙嵇紹，遲行笑褚淵。","四夷同效順，一命敢虛捐。","山岳還青聳，穹蒼旧碧鲜。","独夫长啜泣，多士已忘筌。","鬱鬱空狂叫，微微幾病癲。","丹梯倚寥廓，終去问青天。"]', '诗', 'shi', '', NULL, '感事三十四韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('352da044-d964-434b-9a3d-778a9e3f558d', '向隅', '向隅', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["守道得途遲，中兼遇亂離。","剛腸成繞指，玄髮轉垂絲。","客路少安處，病牀無穩時。","弟兄消息絕，獨斂向隅眉。"]', '["守道得途遲，中兼遇亂離。","剛腸成繞指，玄髮轉垂絲。","客路少安处，病牀無穩时。","弟兄消息絕，独斂向隅眉。"]', '诗', 'shi', '', NULL, '向隅 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10f9aacb-79cb-4cb9-b6d2-cc948daaf895', '社後', '社後', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["社後重陽近，雲天澹薄間。","目隨棊客靜，心共睡僧閑。","歸鳥城銜日，殘虹雨在山。","寂寥思晤語，何夕款柴關。"]', '["社後重陽近，云天澹薄间。","目隨棊客静，心共睡僧闲。","归鸟城銜日，殘虹雨在山。","寂寥思晤語，何夕款柴关。"]', '诗', 'shi', '', NULL, '社後 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4e7a6e-344c-44b8-a1fe-3fba8431b4ed', '息慮', '息慮', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["息慮狎羣鷗，行藏合自由。","春寒宜酒病，夜雨入鄉愁。","道向危時見，官因亂世休。","外人相待淺，獨說濟川舟。"]', '["息慮狎羣鷗，行藏合自由。","春寒宜酒病，夜雨入乡愁。","道向危时见，官因亂世休。","外人相待淺，独说濟川舟。"]', '诗', 'shi', '', NULL, '息慮 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4669f9a4-1be4-41f7-abd5-5d96705a5a27', '早起探春', '早起探春', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["句芒一夜長精神，臘後風頭已見春。","煙柳半眠藏利臉，雪梅含笑綻香脣。","漸因閑暇思量酒，必怨顚狂泥摸人。","若箇高情能似我，且應敧枕睡清晨。"]', '["句芒一夜长精神，臘後风头已见春。","煙柳半眠藏利臉，雪梅含笑綻香脣。","漸因闲暇思量酒，必怨顚狂泥摸人。","若箇高情能似我，且應敧枕睡清晨。"]', '诗', 'shi', '', NULL, '早起探春 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f77d39d-9564-4c06-9f4c-b34263fd5680', '味道', '味道', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["如含瓦礫竟何功，癡黠相兼似得中。","心繫是非徒悵望，事須光景旋虛空。","升沈不定都如夢，毀譽無恆却要聾。","弋者甚多應扼腕，任他閑處指冥鴻。"]', '["如含瓦礫竟何功，癡黠相兼似得中。","心繫是非徒悵望，事須光景旋虛空。","升沈不定都如梦，毀譽無恆却要聾。","弋者甚多應扼腕，任他闲处指冥鴻。"]', '诗', 'shi', '', NULL, '味道 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53151f84-9412-4240-afa0-a669514c438a', '秋郊閑望有感', '秋郊闲望有感', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["楓葉微紅近有霜，碧雲秋色滿吳鄉。","魚衝駭浪雪鱗健，鴉閃夕陽金背光。","心爲感恩長慘戚，鬢緣經亂早蒼浪。","可憐廣武山前語，楚漢寧教作戰場。"]', '["楓葉微紅近有霜，碧云秋色满吳乡。","鱼衝駭浪雪鱗健，鴉閃夕陽金背光。","心爲感恩长慘戚，鬢緣經亂早蒼浪。","可怜廣武山前語，楚漢寧教作戰場。"]', '诗', 'shi', '', NULL, '秋郊閑望有感 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b269705-816f-468e-a774-d3e589383568', '李太舍池上玩紅薇醉題', '李太舍池上玩紅薇醉題', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["花低池小水泙泙，花落池心片片輕。","酩酊不能羞白鬢，顚狂猶自睠紅英。","乍爲旅客顏常厚，每見同人眼暫明。","京洛園林歸未得，天涯相顧一含情。"]', '["花低池小水泙泙，花落池心片片轻。","酩酊不能羞白鬢，顚狂猶自睠紅英。","乍爲旅客顏常厚，每见同人眼暫明。","京洛园林归未得，天涯相顧一含情。"]', '诗', 'shi', '', NULL, '李太舍池上玩紅薇醉題 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b2ea62-6639-49e6-a989-af906ace56ef', '余寓汀州沙縣病中聞前鄭左丞璘隨外鎮舉薦赴洛兼云繼有急徵旋見脂轄因作七言四韻戲以贈之或冀其感悟也', '余寓汀州沙縣病中闻前鄭左丞璘隨外鎮舉薦赴洛兼云繼有急徵旋见脂轄因作七言四韻戲以贈之或冀其感悟也', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["莫恨當年入用遲，通材何處不逢知。","桑田變後新舟檝，華表歸來舊路岐。","公干寂寥甘坐廢，子牟歡抃促行期。","移都已改侯王第，惆悵沙堤別築基。"]', '["莫恨當年入用遲，通材何处不逢知。","桑田变後新舟檝，华表归来旧路岐。","公干寂寥甘坐廢，子牟歡抃促行期。","移都已改侯王第，惆悵沙堤別築基。"]', '诗', 'shi', '', NULL, '余寓汀州沙縣病中聞前鄭左丞璘隨外鎮舉薦赴洛兼云繼有急徵旋見脂轄因作七言四韻戲以贈之或冀其感悟也 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2623bbe7-d783-4230-a155-e3bf9aff9624', '又一絕請爲申達京洛親交知余病廢', '又一絕請爲申達京洛親交知余病廢', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鬢惹新霜耳舊聾，眼昏腰曲四肢風。","交親若要知形候，嵐嶂煙中折臂翁。"]', '["鬢惹新霜耳旧聾，眼昏腰曲四肢风。","交親若要知形候，嵐嶂煙中折臂翁。"]', '诗', 'shi', '', NULL, '又一絕請爲申達京洛親交知余病廢 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77881f4e-00fa-4a3f-9074-4437679ac6db', '夢中作', '梦中作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["紫宸初啓列鴛鸞，直向龍墀對揖班。","九曜再新環北極，萬方依舊祝南山。","禮容肅睦纓緌外，和氣熏蒸劒履間。","扇合却循黃道退，廟堂談笑百司閑。"]', '["紫宸初啓列鴛鸾，直向龙墀对揖班。","九曜再新环北極，万方依旧祝南山。","禮容肅睦纓緌外，和氣熏蒸劒履间。","扇合却循黄道退，廟堂談笑百司闲。"]', '诗', 'shi', '', NULL, '夢中作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31a22c1d-950b-4b0b-9dd9-c4611c3ddf23', '己巳年正月十二日自沙縣抵邵武軍將謀撫信之行到纔一夕爲閩相急脚相召却請赴沙縣郊外泊船偶成一篇', '己巳年正月十二日自沙縣抵邵武軍將謀撫信之行到纔一夕爲閩相急脚相召却請赴沙縣郊外泊船偶成一篇', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["訪戴船迴郊外泊，故鄉何處望天涯。","半明半暗山村日，自落自開江廟花。","數醆綠醅桑落酒，一甌香沫火前茶。"]', '["訪戴船迴郊外泊，故乡何处望天涯。","半明半暗山村日，自落自开江廟花。","數醆綠醅桑落酒，一甌香沫火前茶。"]', '诗', 'shi', '', NULL, '己巳年正月十二日自沙縣抵邵武軍將謀撫信之行到纔一夕爲閩相急脚相召却請赴沙縣郊外泊船偶成一篇 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45079a57-8e31-4d91-aed1-f436dbeaf155', '建谿灘波心目驚眩余平生溺奇境今則畏怯不暇因書二十八字', '建谿灘波心目驚眩余平生溺奇境今則畏怯不暇因书二十八字', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["長貪山水羨漁樵，自笑揚鞭趁早朝。","今日建谿驚恐後，李將軍畫也須燒。"]', '["长貪山水羨漁樵，自笑揚鞭趁早朝。","今日建谿驚恐後，李將軍畫也須燒。"]', '诗', 'shi', '', NULL, '建谿灘波心目驚眩余平生溺奇境今則畏怯不暇因書二十八字 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477dee88-46b6-46f9-b688-1da7cfdbde35', '自沙縣抵龍溪縣值泉州軍過後村落皆空因有一絕', '自沙縣抵龙溪縣值泉州軍過後村落皆空因有一絕', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["水自潺湲日自斜，盡無雞犬有鳴鴉。","千村萬落如寒食，不見人煙空見花。"]', '["水自潺湲日自斜，尽無雞犬有鳴鴉。","千村万落如寒食，不见人煙空见花。"]', '诗', 'shi', '', NULL, '自沙縣抵龍溪縣值泉州軍過後村落皆空因有一絕 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfe11ea1-7401-4c48-920e-36c990a4a383', '此翁', '此翁', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["高閣羣公莫忌儂，儂心不在宦名中。","嚴光一唾垂緌紫，何胤三遺大帶紅。","金勁任從千口鑠，玉寒曾試幾爐烘。","唯應鬼眼兼天眼，窺見行藏信此翁。"]', '["高閣羣公莫忌儂，儂心不在宦名中。","嚴光一唾垂緌紫，何胤三遺大带紅。","金勁任從千口鑠，玉寒曾試幾爐烘。","唯應鬼眼兼天眼，窺见行藏信此翁。"]', '诗', 'shi', '', NULL, '此翁 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93771ae9-e5b6-450b-9ff1-c16a90d175cb', '失鶴', '失鹤', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["正憐標格出華亭，況是昂藏入相經。","碧落順風初得志，故巢因雨却聞腥。","幾時翔集來華表，每日沈吟看畫屏。","爲報雞羣虛嫉妒，紅塵向上有青冥。"]', '["正怜標格出华亭，況是昂藏入相經。","碧落順风初得志，故巢因雨却闻腥。","幾时翔集来华表，每日沈吟看畫屏。","爲報雞羣虛嫉妒，紅塵向上有青冥。"]', '诗', 'shi', '', NULL, '失鶴 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8372f298-08f3-439b-9760-9f96dcae1aa0', '卜隱', '卜隐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["屏跡還應減是非，却憂藍玉又光輝。","桑梢出舍蠶初老，柳絮蓋溪魚正肥。","世亂豈容長愜意，景清還覺易忘機。","世間華美無心問，藜藿充腸苧作衣。"]', '["屏跡還應減是非，却憂藍玉又光輝。","桑梢出舍蠶初老，柳絮蓋溪鱼正肥。","世亂豈容长愜意，景清還覺易忘機。","世间华美無心问，藜藿充腸苧作衣。"]', '诗', 'shi', '', NULL, '卜隱 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68050c4-6a0c-49d0-8577-775ef25dd530', '晨興', '晨兴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["曉景山河爽，閑居巷陌清。","已能消滯念，兼得散餘酲。","汲水人初起，迴燈燕暫驚。","放懷殊未足，圓隙已塵生。"]', '["晓景山河爽，闲居巷陌清。","已能消滯念，兼得散餘酲。","汲水人初起，迴灯燕暫驚。","放懷殊未足，圓隙已塵生。"]', '诗', 'shi', '', NULL, '晨興 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea5f3ed1-afa4-4d40-b4b8-216bafecc273', '暴雨', '暴雨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["電尾燒黑雲，雨脚飛銀線。","急點濺池心，微煙昏水面。","氣涼氛祲消，暑退松篁健。","叢蓼亞赬茸，擎荷飜綠扇。","風期誰與同，逸趣余探徧。","欲去更遲留，胸中久交戰。"]', '["電尾燒黑云，雨脚飞銀線。","急点濺池心，微煙昏水面。","氣涼氛祲消，暑退松篁健。","叢蓼亞赬茸，擎荷飜綠扇。","风期誰與同，逸趣余探徧。","欲去更遲留，胸中久交戰。"]', '诗', 'shi', '', NULL, '暴雨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('615974f2-27b6-4e9a-a6ca-aa9d4dbbdbe2', '山院避暑', '山院避暑', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["行樂江郊外，追涼山寺中。","靜陰生晚綠，寂慮延清風。","運塞地維窄，氣蘇天宇空。","何人識幽抱，目送冥冥鴻。"]', '["行乐江郊外，追涼山寺中。","静陰生晚綠，寂慮延清风。","運塞地維窄，氣蘇天宇空。","何人識幽抱，目送冥冥鴻。"]', '诗', 'shi', '', NULL, '山院避暑 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edbb8e1b-c090-4d31-b417-25c9c9b83b24', '閑興', '闲兴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["景寂有玄味，韻高無俗情。","他山冰雪解，此水波瀾生。","影重驗花密，滴稀知酒清。","忙人常擾擾，安得心和平。"]', '["景寂有玄味，韻高無俗情。","他山冰雪解，此水波瀾生。","影重驗花密，滴稀知酒清。","忙人常擾擾，安得心和平。"]', '诗', 'shi', '', NULL, '閑興 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f46cba01-1204-4942-bdbf-8e2ff3760b03', '漫作二首 一', '漫作二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["暑雨灑和氣，香風吹日華。","瞬龍驚汗漫，翥鳳綷雲霞。","懸圃珠爲樹，天池玉作砂。","丹霄能幾級，何必待乘槎。"]', '["暑雨灑和氣，香风吹日华。","瞬龙驚汗漫，翥鳳綷云霞。","懸圃珠爲樹，天池玉作砂。","丹霄能幾級，何必待乘槎。"]', '诗', 'shi', '', NULL, '漫作二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd798cf6-95ca-4be9-bdf1-216a4118e282', '漫作二首 二', '漫作二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["黍谷純陽入，鸞霄瑞彩生。","岳靈分正氣，仙衛借神兵。","汚俗迎風變，虛懷遇物傾。","千鈞將一羽，輕重在平衡。"]', '["黍谷純陽入，鸾霄瑞彩生。","岳靈分正氣，仙衛借神兵。","汚俗迎风变，虛懷遇物傾。","千鈞將一羽，轻重在平衡。"]', '诗', 'shi', '', NULL, '漫作二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe20ba41-3a18-45b7-95cb-3052c834b58c', '騰騰', '腾腾', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["八年流落醉騰騰，點檢行藏喜不勝。","烏帽素餐兼施藥，前生多恐是醫僧。"]', '["八年流落醉腾腾，点檢行藏喜不勝。","烏帽素餐兼施藥，前生多恐是醫僧。"]', '诗', 'shi', '', NULL, '騰騰 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28494d7f-d062-4034-a506-0182cfd2d5f6', '寄隱者', '寄隐者', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["煙郭雲扃路不遙，懷賢猶恨太迢迢。","長松夜落釵千股，小港春添水半腰。","已約病身拋印綬，不嫌門巷似漁樵。","渭濱晦跡南陽臥，若比吾徒更寂寥。"]', '["煙郭云扃路不遙，懷賢猶恨太迢迢。","长松夜落釵千股，小港春添水半腰。","已約病身拋印綬，不嫌门巷似漁樵。","渭濱晦跡南陽臥，若比吾徒更寂寥。"]', '诗', 'shi', '', NULL, '寄隱者 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e4fb5d-b969-4d62-b688-273e8db5b02d', '閑居', '闲居', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["厭聞趨競喜閑居，自種蕪菁亦自鋤。","麋鹿跳梁憂觸撥，鷹鸇搏擊恐麤疎。","拙謀却爲多循理，所短深慙盡信書。","刀尺不虧繩墨在，莫疑張翰戀鱸魚。"]', '["厭闻趨競喜闲居，自種蕪菁亦自鋤。","麋鹿跳梁憂觸撥，鷹鸇搏擊恐麤疎。","拙謀却爲多循理，所短深慙尽信书。","刀尺不虧繩墨在，莫疑張翰戀鱸鱼。"]', '诗', 'shi', '', NULL, '閑居 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a426f3e-4f0c-4a36-a9ae-5cdbd8460286', '僧影', '僧影', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["山色依然僧已亡，竹間疎磬隔殘陽。","智燈已滅餘空燼，猶自光明照十方。"]', '["山色依然僧已亡，竹间疎磬隔殘陽。","智灯已滅餘空燼，猶自光明照十方。"]', '诗', 'shi', '', NULL, '僧影 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27803088-2a65-4ea7-9880-1d30c7ad2376', '洞庭玩月', '洞庭玩月', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["洞庭湖上清秋月，月皎湖寬萬頃霜。","玉椀深沈潭底白，金杯細碎浪頭光。","寒驚烏鵲離巢噪，冷射蛟螭換窟藏。","更憶瑤臺逢此夜，水晶宮殿挹瓊漿。"]', '["洞庭湖上清秋月，月皎湖寬万頃霜。","玉椀深沈潭底白，金杯細碎浪头光。","寒驚烏鵲離巢噪，冷射蛟螭換窟藏。","更憶瑤台逢此夜，水晶宮殿挹瓊漿。"]', '诗', 'shi', '', NULL, '洞庭玩月 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f520fa35-0fd4-4a7b-ac61-aa94d5258fff', '贈隱逸', '贈隐逸', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["靜景須教靜者尋，清狂何必在山陰。","蠭穿窗紙塵侵硯，鳥鬬庭花露滴琴。","莫笑亂離方解印，猶勝顚蹶未抽簪。","築金總得非名士，況是無人解築金。"]', '["静景須教静者尋，清狂何必在山陰。","蠭穿窗紙塵侵硯，鸟鬬庭花露滴琴。","莫笑亂離方解印，猶勝顚蹶未抽簪。","築金總得非名士，況是無人解築金。"]', '诗', 'shi', '', NULL, '贈隱逸 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df6091c7-bfb2-4b21-bdd4-63d2c89bfe9f', '南浦', '南浦', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["月若半環雲若吐，高樓簾卷當南浦。","應是石城艇子來，兩槳咿啞過花塢。","正值連宵酒未醒，不宜此際兼微雨。","直教筆底有文星，亦應難狀分明苦。"]', '["月若半环云若吐，高楼簾卷當南浦。","應是石城艇子来，兩槳咿啞過花塢。","正值連宵酒未醒，不宜此際兼微雨。","直教笔底有文星，亦應难狀分明苦。"]', '诗', 'shi', '', NULL, '南浦 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c29b9b-2650-424f-be87-8b16dde36402', '桃林場客舍之前有池半畝木槿櫛比閼水遮山因命僕夫運斤梳沐豁然清朗復覩太虛因作五言八韻', '桃林場客舍之前有池半畝木槿櫛比閼水遮山因命僕夫運斤梳沐豁然清朗复覩太虛因作五言八韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["插槿作藩籬，叢生覆小池。","爲能妨遠目，因遣去閑枝。","鄰叟偷來賞，棲禽欲下疑。","虛空無障處，蒙閉有開時。","葦鷺憐瀟灑，泥鰌畏日曦。","稍寬春水面，盡見晚山眉。","岸穩人偷釣，階明日上基。","世間多弊事，事事要良醫。"]', '["插槿作藩籬，叢生覆小池。","爲能妨远目，因遣去闲枝。","鄰叟偷来賞，棲禽欲下疑。","虛空無障处，蒙閉有开时。","葦鷺怜瀟灑，泥鰌畏日曦。","稍寬春水面，尽见晚山眉。","岸穩人偷釣，階明日上基。","世间多弊事，事事要良醫。"]', '诗', 'shi', '', NULL, '桃林場客舍之前有池半畝木槿櫛比閼水遮山因命僕夫運斤梳沐豁然清朗復覩太虛因作五言八韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee823576-5f33-4657-99f7-aea841e6e9c0', '中秋寄楊學士', '中秋寄楊学士', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鱗差甲子漸衰遲，依舊年年困亂離。","八月夜長鄉思切，鬢邊添得幾莖絲。"]', '["鱗差甲子漸衰遲，依旧年年困亂離。","八月夜长乡思切，鬢邊添得幾莖絲。"]', '诗', 'shi', '', NULL, '中秋寄楊學士 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe85566d-acb2-4842-aeee-b1bee0e3d9e7', '寄禪師', '寄禪師', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["他心明與此心同，妙用忘言理暗通。","氣運陰陽成世界，水浮天地寄虛空。","劫灰聚散銖錙黑，日御奔馳繭栗紅。","萬物盡遭風鼓動，唯應禪室靜無風。"]', '["他心明與此心同，妙用忘言理暗通。","氣運陰陽成世界，水浮天地寄虛空。","劫灰聚散銖錙黑，日御奔驰繭栗紅。","万物尽遭风鼓动，唯應禪室静無风。"]', '诗', 'shi', '', NULL, '寄禪師 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bebb844-7943-4531-a036-ad0c4b42d80d', '清興', '清兴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["陰沈天氣連翩醉，摘索花枝料峭寒。","擁鼻繞廊吟看雨，不知遺却竹皮冠。"]', '["陰沈天氣連翩醉，摘索花枝料峭寒。","擁鼻繞廊吟看雨，不知遺却竹皮冠。"]', '诗', 'shi', '', NULL, '清興 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6664b9-a90f-4406-9844-d4ab2b5a2b50', '深院', '深院', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鵝兒唼啑梔黃觜，鳳子輕盈膩粉腰。","深院下簾人晝寢，紅薔薇架碧芭蕉。"]', '["鵝兒唼啑梔黄觜，鳳子轻盈膩粉腰。","深院下簾人晝寢，紅薔薇架碧芭蕉。"]', '诗', 'shi', '', NULL, '深院 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bcbad58-8242-4895-be39-c58363d3426f', '淒淒', '淒淒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["深將寵辱齊，往往亦淒淒。","白日知丹抱，青雲有舊蹊。","嗜鹹凌魯濟，惡潔助涇泥。","風雨今如晦，堪憐報曉雞。"]', '["深將寵辱齊，往往亦淒淒。","白日知丹抱，青云有旧蹊。","嗜鹹凌魯濟，惡潔助涇泥。","风雨今如晦，堪怜報晓雞。"]', '诗', 'shi', '', NULL, '淒淒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c236f109-5298-40ab-88da-011e534e3ee8', '火蛾', '火蛾', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["陽光不照臨，積陰生此類。","非無惜死心，奈有滅明意。","妝穿粉燄焦，翅撲蘭膏沸。","爲爾一傷嗟，自棄非天棄。"]', '["陽光不照臨，積陰生此類。","非無惜死心，奈有滅明意。","妝穿粉燄焦，翅撲蘭膏沸。","爲爾一傷嗟，自棄非天棄。"]', '诗', 'shi', '', NULL, '火蛾 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e168bdbb-7eb4-423e-ace3-49f7e61e57ac', '信筆', '信笔', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["春風狂似虎，春浪白於鵝。","柳密藏煙易，松長見日多。","石崖采芝叟，鄉俗摘茶歌。","道在無伊鬱，天將奈爾何。"]', '["春风狂似虎，春浪白於鵝。","柳密藏煙易，松长见日多。","石崖采芝叟，乡俗摘茶歌。","道在無伊鬱，天將奈爾何。"]', '诗', 'shi', '', NULL, '信筆 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2466fb5b-bbaa-4e0d-bc00-f24a733562d3', '雷公', '雷公', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["閑人倚柱笑雷公，又向深山霹怪松。","必若有蘇天下意，何如驚起武侯龍。"]', '["闲人倚柱笑雷公，又向深山霹怪松。","必若有蘇天下意，何如驚起武侯龙。"]', '诗', 'shi', '', NULL, '雷公 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84680ee-aee3-43ed-b120-68c3e6c71f91', '船頭', '船头', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["兩岸綠蕪齊似翦，掩映雲山相向晚。","船頭獨立望長空，日豔波光逼人眼。"]', '["兩岸綠蕪齊似翦，掩映云山相向晚。","船头独立望长空，日豔波光逼人眼。"]', '诗', 'shi', '', NULL, '船頭 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef986d5-c829-4159-b811-d39ad0293858', '喜涼', '喜涼', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["爐炭燒人百疾生，鳳狂龍躁減心情。","四山毒瘴乾坤濁，一簟涼風世界清。","楚調忽驚淒玉柱，漢宮應已溼金莖。","豪強頓息蛙脣吻，爽利重新鶻眼睛。","穩想海槎朝犯斗，健思胡馬夜飜營。","東南亦是中華分，蒸鬱相凌太不平。"]', '["爐炭燒人百疾生，鳳狂龙躁減心情。","四山毒瘴乾坤濁，一簟涼风世界清。","楚調忽驚淒玉柱，漢宮應已溼金莖。","豪強頓息蛙脣吻，爽利重新鶻眼睛。","穩想海槎朝犯斗，健思胡马夜飜營。","东南亦是中华分，蒸鬱相凌太不平。"]', '诗', 'shi', '', NULL, '喜涼 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944d6c59-2ef8-4e05-b5f2-75b254bedff3', '天鑒', '天鑒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["何勞諂笑學趨時，務實清修勝用機。","猛虎十年搖尾立，蒼鷹一旦醒心飛。","神依正道終潛衛，天鑒衷腸競不違。","事歷艱難人始重，九層成後喜從微。"]', '["何勞諂笑学趨时，務實清修勝用機。","猛虎十年搖尾立，蒼鷹一旦醒心飞。","神依正道終潛衛，天鑒衷腸競不違。","事歷艱难人始重，九層成後喜從微。"]', '诗', 'shi', '', NULL, '天鑒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f4209b1-1864-4eae-99e6-55535141af7f', '江岸閑步', '江岸闲步', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一手攜書一杖筇，出門何處覓情通。","立談禪客傳心印，坐睡漁師著背蓬。","青布旗誇千日酒，白頭浪吼半江風。","淮陰市裏人相見，盡道途窮未必窮。"]', '["一手携书一杖筇，出门何处覓情通。","立談禪客傳心印，坐睡漁師著背蓬。","青布旗誇千日酒，白头浪吼半江风。","淮陰市裏人相见，尽道途窮未必窮。"]', '诗', 'shi', '', NULL, '江岸閑步 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5930890b-7bcc-4e26-9216-62ac131bfdc3', '野塘', '野塘', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["侵曉乘涼偶獨來，不因魚躍見萍開。","卷荷忽被微風觸，瀉下清香露一杯。"]', '["侵晓乘涼偶独来，不因鱼躍见萍开。","卷荷忽被微风觸，瀉下清香露一杯。"]', '诗', 'shi', '', NULL, '野塘 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbe361c-0ea8-4564-80cc-aabf45d61fd5', '余臥疾深村聞一二郎官今稱繼使閩越笑余迂古潛於異鄉聞之因成此篇', '余臥疾深村闻一二郎官今稱繼使閩越笑余迂古潛於異乡闻之因成此篇', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["枕流方采北山薇，驛騎交迎市道兒。","霧豹秪憂無石室，泥鰌唯要有洿池。","不羞莽卓黃金印，却笑羲皇白接䍦。","莫負美名書信史，清風埽地更無遺。"]', '["枕流方采北山薇，驛騎交迎市道兒。","霧豹秪憂無石室，泥鰌唯要有洿池。","不羞莽卓黄金印，却笑羲皇白接䍦。","莫負美名书信史，清风埽地更無遺。"]', '诗', 'shi', '', NULL, '余臥疾深村聞一二郎官今稱繼使閩越笑余迂古潛於異鄉聞之因成此篇 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14241332-5e0b-43d4-aac4-722924a897a1', '安貧', '安貧', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["手風慵展一行書，眼暗休尋九局圖。","窗裏日光飛野馬，案頭筠管長蒲廬。","謀身拙爲安蛇足，報國危曾捋虎鬚。","舉世可能無默識，未知誰擬試齊竽。"]', '["手风慵展一行书，眼暗休尋九局圖。","窗裏日光飞野马，案头筠管长蒲廬。","謀身拙爲安蛇足，報国危曾捋虎鬚。","舉世可能無默識，未知誰擬試齊竽。"]', '诗', 'shi', '', NULL, '安貧 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2d92dcc-a89a-4aeb-a60b-53949dd41eba', '殘春旅舍', '殘春旅舍', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["旅舍殘春宿雨晴，恍然心地憶咸京。","樹頭蠭抱花鬚落，池面魚吹柳絮行。","禪伏詩魔歸淨域，酒衝愁陣出奇兵。","兩梁免被塵埃汚，拂拭朝簪待眼明。"]', '["旅舍殘春宿雨晴，恍然心地憶咸京。","樹头蠭抱花鬚落，池面鱼吹柳絮行。","禪伏诗魔归淨域，酒衝愁陣出奇兵。","兩梁免被塵埃汚，拂拭朝簪待眼明。"]', '诗', 'shi', '', NULL, '殘春旅舍 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29e2ffa-aa3f-41d0-8524-c235bc8fa56e', '鵲', '鵲', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["偏承雨露潤毛衣，黑白分明衆所知。","高處營巢親鳳闕，靜時閑語上龍墀。","化爲金印新祥瑞，飛向銀河舊路岐。","莫怪天涯棲不穩，託身須是萬年枝。"]', '["偏承雨露潤毛衣，黑白分明衆所知。","高处營巢親鳳闕，静时闲語上龙墀。","化爲金印新祥瑞，飞向銀河旧路岐。","莫怪天涯棲不穩，託身須是万年枝。"]', '诗', 'shi', '', NULL, '鵲 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c84bcaa-f6d3-4607-b30b-3ef971feed6d', '露', '露', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鶴非千歲飲猶難，鶯舌偷含豈自安。","光溼最宜叢菊亞，蕩搖無奈綠荷乾。","名因霈澤隨天睠，分與濃霜保歲寒。","五色呈祥須得處，戛雲仙掌有金盤。"]', '["鹤非千歲饮猶难，鶯舌偷含豈自安。","光溼最宜叢菊亞，蕩搖無奈綠荷乾。","名因霈澤隨天睠，分與濃霜保歲寒。","五色呈祥須得处，戛云仙掌有金盤。"]', '诗', 'shi', '', NULL, '露 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc43af5d-96db-4b0d-a309-dbd3f33ef970', '贈僧', '贈僧', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["盡說歸山避戰塵，幾人終肯別囂氛。","瓶添澗水盛將月，衲挂松枝惹得雲。","三接舊承前席遇，一靈今用戒香熏。","相逢莫話金鑾事，觸撥傷心不願聞。"]', '["尽说归山避戰塵，幾人終肯別囂氛。","瓶添澗水盛將月，衲挂松枝惹得云。","三接旧承前席遇，一靈今用戒香熏。","相逢莫話金鑾事，觸撥傷心不願闻。"]', '诗', 'shi', '', NULL, '贈僧 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ddae55-30cb-4033-8e9a-f37ceb5622dd', '感舊', '感旧', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["省趨弘閣待貂璫，指座深恩刻寸腸。","秦苑已荒空逝水，楚天無[限]更斜陽。","時昏却笑朱弦直，事過方聞鎖骨香。","入室故寮流落盡，路人惆悵見靈光。"]', '["省趨弘閣待貂璫，指座深恩刻寸腸。","秦苑已荒空逝水，楚天無[限]更斜陽。","时昏却笑朱弦直，事過方闻鎖骨香。","入室故寮流落尽，路人惆悵见靈光。"]', '诗', 'shi', '', NULL, '感舊 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9665eaff-fd9a-4ab3-9df1-9268c00496c7', '八月六日作四首 一', '八月六日作四首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["日離黃道十年昏，敏手重開造化門。","火帝動爐銷劒戟，風師吹雨洗乾坤。","左牽犬馬誠難測，右袒簪纓最負恩。","丹筆不知誰定罪，莫留遺跡怨神孫。"]', '["日離黄道十年昏，敏手重开造化门。","火帝动爐銷劒戟，风師吹雨洗乾坤。","左牽犬马誠难測，右袒簪纓最負恩。","丹笔不知誰定罪，莫留遺跡怨神孫。"]', '诗', 'shi', '', NULL, '八月六日作四首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e092b3ab-9c5f-455c-9040-0827fd236710', '八月六日作四首 二', '八月六日作四首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["金虎挻災不復論，搆成狂猘犯車塵。","御衣空惜侍中血，國璽幾危皇后身。","圖霸未能知盜道，飾非唯欲害仁人。","黃旗紫氣今仍舊，免使老臣攀畫輪。"]', '["金虎挻災不复論，搆成狂猘犯车塵。","御衣空惜侍中血，国璽幾危皇后身。","圖霸未能知盜道，飾非唯欲害仁人。","黄旗紫氣今仍旧，免使老臣攀畫輪。"]', '诗', 'shi', '', NULL, '八月六日作四首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6572231d-88eb-4839-9b65-d5225c277eb6', '八月六日作四首 三', '八月六日作四首 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["簪裾皆是漢公卿，盡作鋒鋩劒血醒。","顯負舊恩歸亂主，難教新國用輕刑。","穴中狡兔終須盡，井上嬰兒豈自寧。","底事亦疑懲未了，更應書罪在泉扃。"]', '["簪裾皆是漢公卿，尽作鋒鋩劒血醒。","显負旧恩归亂主，难教新国用轻刑。","穴中狡兔終須尽，井上嬰兒豈自寧。","底事亦疑懲未了，更應书罪在泉扃。"]', '诗', 'shi', '', NULL, '八月六日作四首 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5f7b80-8443-4ee4-b41b-bac3a8a28c87', '八月六日作四首 四', '八月六日作四首 四', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["坐看包藏負國恩，無才不得預經綸。","袁安墜睫尋憂漢，賈誼濡毫但過秦。","威鳳鬼應遮矢射，靈犀天與隔埃塵。","隄防瓜李能終始，免媿於心負此身。"]', '["坐看包藏負国恩，無才不得預經綸。","袁安墜睫尋憂漢，賈誼濡毫但過秦。","威鳳鬼應遮矢射，靈犀天與隔埃塵。","隄防瓜李能終始，免媿於心負此身。"]', '诗', 'shi', '', NULL, '八月六日作四首 四 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f362f5-bd40-4e71-87d3-2b19e638706d', '驛步', '驛步', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["暫息征車病眼開，況穿松竹入樓臺。","江流燈影向東去，樹遞雨聲從北來。","物近劉輿招垢膩，風經庾亮汚塵埃。","高情自古多惆悵，賴有南華養不材。"]', '["暫息征车病眼开，況穿松竹入楼台。","江流灯影向东去，樹遞雨声從北来。","物近劉輿招垢膩，风經庾亮汚塵埃。","高情自古多惆悵，賴有南华養不材。"]', '诗', 'shi', '', NULL, '驛步 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e27f72-e002-4b98-823d-43112d852046', '訪隱者遇沈醉書其門而歸', '訪隐者遇沈醉书其门而归', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["曉入江村覓釣翁，釣翁沈醉酒缸空。","夜來風起閑花落，狼藉柴門鳥徑中。"]', '["晓入江村覓釣翁，釣翁沈醉酒缸空。","夜来风起闲花落，狼藉柴门鸟徑中。"]', '诗', 'shi', '', NULL, '訪隱者遇沈醉書其門而歸 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2fd705-2cf2-403d-b686-972fd9ef7eff', '疎雨', '疎雨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["疎雨從東送疾雷，小庭涼氣淨莓苔。","卷簾燕子穿人去，洗硯魚兒觸手來。","但欲進賢求上賞，唯將拯溺作良媒。","戎衣一挂清天下，傅野非無濟世才。"]', '["疎雨從东送疾雷，小庭涼氣淨莓苔。","卷簾燕子穿人去，洗硯鱼兒觸手来。","但欲進賢求上賞，唯將拯溺作良媒。","戎衣一挂清天下，傅野非無濟世才。"]', '诗', 'shi', '', NULL, '疎雨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e12b461b-6344-46ea-b3a5-9b27fd7ce8be', '南安寓止', '南安寓止', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["此地三年偶寄家，枳籬茅廠共桑麻。","蝶矜翅暖徐窺草，蠭倚身輕凝看花。","天近函關屯瑞氣，水侵吳甸浸晴霞。","豈知卜肆嚴夫子，潛指星機認海槎。"]', '["此地三年偶寄家，枳籬茅廠共桑麻。","蝶矜翅暖徐窺草，蠭倚身轻凝看花。","天近函关屯瑞氣，水侵吳甸浸晴霞。","豈知卜肆嚴夫子，潛指星機認海槎。"]', '诗', 'shi', '', NULL, '南安寓止 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80df0ff-95cb-4794-9d66-b1db8effa5e9', '十月七日早起作時氣疾初愈', '十月七日早起作时氣疾初愈', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["疾愈身輕覺數通，山無嵐瘴海無風。","陽精欲出陰精落，天地包含紫氣中。"]', '["疾愈身轻覺數通，山無嵐瘴海無风。","陽精欲出陰精落，天地包含紫氣中。"]', '诗', 'shi', '', NULL, '十月七日早起作時氣疾初愈 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a199a7-91b3-4dc4-a215-d7c26126f043', '有感', '有感', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["堅辭羽葆與吹鐃，飜向天涯困繫匏。","故老未曾忘炙背，何人終擬問苞茅。","融風漸暖將迴雁，滫水猶腥近斬蛟。","萬里關山如咫尺，女牀唯待鳳歸巢。"]', '["堅辞羽葆與吹鐃，飜向天涯困繫匏。","故老未曾忘炙背，何人終擬问苞茅。","融风漸暖將迴雁，滫水猶腥近斬蛟。","万里关山如咫尺，女牀唯待鳳归巢。"]', '诗', 'shi', '', NULL, '有感 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c539bbf5-d804-43b7-a3e7-76cabc504914', '觀鬬雞偶作', '观鬬雞偶作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["何曾解報稻粱恩，金距花冠氣遏雲。","白日梟鳴無意問，唯將芥羽害同羣。"]', '["何曾解報稻粱恩，金距花冠氣遏云。","白日梟鳴無意问，唯將芥羽害同羣。"]', '诗', 'shi', '', NULL, '觀鬬雞偶作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2de8d1d-89ea-4d3e-bd38-6fadd29a0ec7', '蜻蜓', '蜻蜓', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["碧玉眼睛雲母翅，輕於粉蝶瘦於蠭。","坐來迎拂波光久，豈是殷勤爲蓼叢。"]', '["碧玉眼睛云母翅，轻於粉蝶瘦於蠭。","坐来迎拂波光久，豈是殷勤爲蓼叢。"]', '诗', 'shi', '', NULL, '蜻蜓 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef6dd4c-945b-4b71-9a6f-59b71aa5def3', '即目', '即目', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["書牆暗記移花日，洗甕先知醞酒期。","須信閑人有忙事，早來衝雨覓漁師。"]', '["书牆暗記移花日，洗甕先知醞酒期。","須信闲人有忙事，早来衝雨覓漁師。"]', '诗', 'shi', '', NULL, '即目 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab90d8b-3022-4df6-a828-606b1db22cef', '寄鄰莊道侶', '寄鄰莊道侶', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["聞說經旬不啓關，藥窗誰伴醉開顏。","夜來雪壓村前竹，賸見溪南幾尺山。"]', '["闻说經旬不啓关，藥窗誰伴醉开顏。","夜来雪壓村前竹，賸见溪南幾尺山。"]', '诗', 'shi', '', NULL, '寄鄰莊道侶 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a20e04bc-aecb-4f81-be02-4bfbaff64fc4', '初赴期集', '初赴期集', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["輕寒著背雨淒淒，九陌無塵未有泥。","還是平時舊滋味，慢垂鞭袖過街西。"]', '["轻寒著背雨淒淒，九陌無塵未有泥。","還是平时旧滋味，慢垂鞭袖過街西。"]', '诗', 'shi', '', NULL, '初赴期集 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60a89be4-fba8-42f7-998b-a89a348f442c', '惜花', '惜花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["皺白離情高處切，膩香愁態靜中深。","眼隨片片沿流去，恨滿枝枝被雨淋。","總得苔遮猶慰意，若教泥汚更傷心。","臨軒一醆悲春酒，明日池塘是綠陰。"]', '["皺白離情高处切，膩香愁態静中深。","眼隨片片沿流去，恨满枝枝被雨淋。","總得苔遮猶慰意，若教泥汚更傷心。","臨軒一醆悲春酒，明日池塘是綠陰。"]', '诗', 'shi', '', NULL, '惜花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48b58c0b-224d-49a5-9dc8-4490dc8fcbcb', '半醉', '半醉', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["水向東流竟不迴，紅顏白髮遞相催。","壯心暗逐高歌盡，往事空因半醉來。","雲護雁霜籠澹月，雨連鶯曉落殘梅。","西樓悵望芳菲節，處處斜陽草似苔。"]', '["水向东流竟不迴，紅顏白髮遞相催。","壯心暗逐高歌尽，往事空因半醉来。","云護雁霜籠澹月，雨連鶯晓落殘梅。","西楼悵望芳菲節，处处斜陽草似苔。"]', '诗', 'shi', '', NULL, '半醉 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4a18e5-e406-4855-a0c0-c180c8f4e69f', '春盡', '春尽', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["惜春連日醉昏昏，醒後衣裳見酒痕。","細水浮花歸別澗，斷雲含雨入孤村。","人閑易有芳時恨，地勝難招自古魂。","慙媿流鶯相厚意，清晨猶爲到西園。"]', '["惜春連日醉昏昏，醒後衣裳见酒痕。","細水浮花归別澗，斷云含雨入孤村。","人闲易有芳时恨，地勝难招自古魂。","慙媿流鶯相厚意，清晨猶爲到西园。"]', '诗', 'shi', '', NULL, '春盡 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5f3dc9-ee39-46b9-90de-423164914b30', '睡起', '睡起', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["睡起牆陰下藥闌，瓦松花白閉柴關。","斷年不出僧嫌癖，逐日無機鶴伴閑。","塵土莫尋行止處，煙波長在夢魂間。","終撐舴艋稱漁叟，賒買湖心一崦山。"]', '["睡起牆陰下藥闌，瓦松花白閉柴关。","斷年不出僧嫌癖，逐日無機鹤伴闲。","塵土莫尋行止处，煙波长在梦魂间。","終撐舴艋稱漁叟，賒買湖心一崦山。"]', '诗', 'shi', '', NULL, '睡起 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9525c7f-4b83-4b6b-b21b-b667b76aec86', '寄友人', '寄友人', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["傷時惜別心交加，搘頤一向千咨嗟。","曠野風吹寒食月，廣庭煙著黃昏花。","長擬醺酣遺世事，若爲局促問生涯。","夫君亦是多情者，幾處將愁殢酒家。"]', '["傷时惜別心交加，搘頤一向千咨嗟。","曠野风吹寒食月，廣庭煙著黄昏花。","长擬醺酣遺世事，若爲局促问生涯。","夫君亦是多情者，幾处將愁殢酒家。"]', '诗', 'shi', '', NULL, '寄友人 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e8cc7d-77bc-4b71-bea9-bb57c174a982', '見別離者因贈之', '见別離者因贈之', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["征人草草盡戎裝，征馬蕭蕭立路傍。","尊酒闌珊將遠別，秋山迤邐更斜陽。","白髭兄弟中年後，瘴海程途萬里長。","曾向天涯懷此恨，見君嗚咽更淒涼。"]', '["征人草草尽戎裝，征马蕭蕭立路傍。","尊酒闌珊將远別，秋山迤邐更斜陽。","白髭兄弟中年後，瘴海程途万里长。","曾向天涯懷此恨，见君嗚咽更淒涼。"]', '诗', 'shi', '', NULL, '見別離者因贈之 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('514c0d63-4676-45c3-9827-d57ffe01f3ef', '傷亂', '傷亂', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["岸上花根總倒垂，水中花影幾千枝。","一枝一影寒山裏，野水野花清露時。","故國幾年猶戰鬬，異鄉終日見旌旗。","交親流落身羸病，誰在誰亡兩不知。"]', '["岸上花根總倒垂，水中花影幾千枝。","一枝一影寒山裏，野水野花清露时。","故国幾年猶戰鬬，異乡終日见旌旗。","交親流落身羸病，誰在誰亡兩不知。"]', '诗', 'shi', '', NULL, '傷亂 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246eaaa9-538f-476a-8681-d970eea0798c', '南亭', '南亭', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["每日在南亭，南亭似僧院。","人語靜先聞，鳥啼深不見。","松瘦石稜稜，山光溪澱澱。","塹蔓墜長茸，島花垂小蒨。","行簪隱士冠，臥讀先賢傳。","更有興來時，取琴彈一徧。"]', '["每日在南亭，南亭似僧院。","人語静先闻，鸟啼深不见。","松瘦石稜稜，山光溪澱澱。","塹蔓墜长茸，島花垂小蒨。","行簪隐士冠，臥读先賢傳。","更有兴来时，取琴彈一徧。"]', '诗', 'shi', '', NULL, '南亭 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc2f675-9de4-41ce-8aa7-d76cbf78e85c', '太平谷中玩水上花', '太平谷中玩水上花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["山頭水從雲外落，水面花自山中來。","一溪紅點我獨惜，幾樹蜜房誰見開。","應有妖魂隨暮雨，豈無香跡在蒼苔。","凝眸不覺斜陽盡，忘逐樵人躡石回。"]', '["山头水從云外落，水面花自山中来。","一溪紅点我独惜，幾樹蜜房誰见开。","應有妖魂隨暮雨，豈無香跡在蒼苔。","凝眸不覺斜陽尽，忘逐樵人躡石回。"]', '诗', 'shi', '', NULL, '太平谷中玩水上花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129534f5-d6db-4d09-be4c-bb409b96dec1', '雨', '雨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["坐來簌簌山風急，山雨隨風暗原隰。","樹帶繁聲出竹聞，溪將大點穿籬入。","餉婦寥翹布領寒，牧童擁腫蓑衣溼。","此時高味共誰論，擁鼻吟詩空佇立。"]', '["坐来簌簌山风急，山雨隨风暗原隰。","樹带繁声出竹闻，溪將大点穿籬入。","餉婦寥翹布領寒，牧童擁腫蓑衣溼。","此时高味共誰論，擁鼻吟诗空佇立。"]', '诗', 'shi', '', NULL, '雨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e7ee44-f029-45c1-b1da-3483701c3994', '幽獨', '幽独', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["幽獨起侵晨，山鶯啼更早。","門巷掩蕭條，落花滿芳草。","煙和魂共遠，春與人同老。","默默又依依，淒然此懷抱。"]', '["幽独起侵晨，山鶯啼更早。","门巷掩蕭條，落花满芳草。","煙和魂共远，春與人同老。","默默又依依，淒然此懷抱。"]', '诗', 'shi', '', NULL, '幽獨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3fa69f4-c337-48a4-b216-e906f33b99ed', '江行', '江行', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["浪蹙青山江北岸，雲含黑雨日西邊。","舟人偶語憂風色，行客無聊罷晝眠。","爭似槐花九衢裏，馬蹄安穩慢垂鞭。"]', '["浪蹙青山江北岸，云含黑雨日西邊。","舟人偶語憂风色，行客無聊罷晝眠。","爭似槐花九衢裏，马蹄安穩慢垂鞭。"]', '诗', 'shi', '', NULL, '江行 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce2667fd-1055-4575-bc3c-a6f8c1f098d6', '漢江行次', '漢江行次', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["村寺雖深已暗知，幡竿殘日迥依依。","沙頭有廟青林合，驛步無人白鳥飛。","牧笛自由隨草遠，漁歌得意扣舷歸。","竹園相接春波暖，痛憶家鄉舊釣磯。"]', '["村寺雖深已暗知，幡竿殘日迥依依。","沙头有廟青林合，驛步無人白鸟飞。","牧笛自由隨草远，漁歌得意扣舷归。","竹园相接春波暖，痛憶家乡旧釣磯。"]', '诗', 'shi', '', NULL, '漢江行次 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('479dc55f-e5c9-49fb-9966-2a90ab8d8574', '偶題', '偶題', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["俟時輕進固相妨，實行丹心仗彼蒼。","蕭艾轉肥蘭蕙瘦，可能天亦妬馨香。"]', '["俟时轻進固相妨，實行丹心仗彼蒼。","蕭艾轉肥蘭蕙瘦，可能天亦妬馨香。"]', '诗', 'shi', '', NULL, '偶題 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e7a30bf-9fd6-4a88-aa59-e05170fe09e6', '湖南絕少含桃偶有人以新摘者見惠感事傷懷因成四韻', '湖南絕少含桃偶有人以新摘者见惠感事傷懷因成四韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["時節雖同氣候殊，不知堪薦寢園無。","合充鳳食留三島，誰許鶯偷過五湖。","苦筍恐難同象匕，酪漿無復瑩蠙珠。","金鑾歲歲長宣賜，忍淚看天憶帝都。"]', '["时節雖同氣候殊，不知堪薦寢园無。","合充鳳食留三島，誰許鶯偷過五湖。","苦筍恐难同象匕，酪漿無复瑩蠙珠。","金鑾歲歲长宣賜，忍泪看天憶帝都。"]', '诗', 'shi', '', NULL, '湖南絕少含桃偶有人以新摘者見惠感事傷懷因成四韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('088f1c54-e5d0-4956-9c05-f9b5720c7e43', '隰州新驛', '隰州新驛', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["盛德已圖形，胡爲忽搆兵。","燎原雖自及，誅亂不無名。","擲鼠須防誤，連雞莫憚驚。","本期將係虜，末策但嬰城。","肘腋人情變，朝廷物論生。","果聞荒谷縊，旋覩藁街烹。","帝怒今方息，時危喜暫清。","始終俱以此，天意甚分明。"]', '["盛德已圖形，胡爲忽搆兵。","燎原雖自及，誅亂不無名。","擲鼠須防誤，連雞莫憚驚。","本期將係虜，末策但嬰城。","肘腋人情变，朝廷物論生。","果闻荒谷縊，旋覩藁街烹。","帝怒今方息，时危喜暫清。","始終俱以此，天意甚分明。"]', '诗', 'shi', '', NULL, '隰州新驛 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86aec3f1-ade0-4b82-8897-a8a95f154abe', '亂後春日途經野塘', '亂後春日途經野塘', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["世亂他鄉見落梅，野塘晴暖獨裴回。","船衝水鳥飛還住，袖拂楊花去却來。","季重舊遊多喪逝，子山新賦極悲哀。","眼看朝市成陵谷，始信昆明是劫灰。"]', '["世亂他乡见落梅，野塘晴暖独裴回。","船衝水鸟飞還住，袖拂楊花去却来。","季重旧游多喪逝，子山新賦極悲哀。","眼看朝市成陵谷，始信昆明是劫灰。"]', '诗', 'shi', '', NULL, '亂後春日途經野塘 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca7cb47-958e-4335-be8b-e6595fbf1ecd', '贈易卜崔江處士', '贈易卜崔江处士', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["白首窮經通祕義，青山養老度危時。","門傳組綬身能退，家學漁樵跡更奇。","四海盡聞龜策妙，九霄堪歎鶴書遲。","壺中日月將何用，借與閑人試一窺。"]', '["白首窮經通祕義，青山養老度危时。","门傳組綬身能退，家学漁樵跡更奇。","四海尽闻龟策妙，九霄堪歎鹤书遲。","壺中日月將何用，借與闲人試一窺。"]', '诗', 'shi', '', NULL, '贈易卜崔江處士 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b81855-29db-4824-a249-fc894f44b443', '過臨淮故里', '過臨淮故里', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["交遊昔歲已凋零，第宅今來亦變更。","舊廟荒涼時饗絕，諸孫飢凍一官成。","五湖竟負他年志，百戰空垂異代名。","榮盛幾何流落久，遣人襟抱薄浮生。"]', '["交游昔歲已凋零，第宅今来亦变更。","旧廟荒涼时饗絕，諸孫飢凍一官成。","五湖竟負他年志，百戰空垂異代名。","榮盛幾何流落久，遣人襟抱薄浮生。"]', '诗', 'shi', '', NULL, '過臨淮故里 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8085273c-5ae5-4a78-9271-b7510d82a188', '贈湖南李思齊處士', '贈湖南李思齊处士', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["兩板船頭濁酒壺，七絲琴畔白髭鬚。","三春日日黃梅雨，孤客年年青草湖。","燕俠冰霜難狎近，楚狂鋒刃觸凡愚。","知余絕粒窺仙事，許到名山看藥鑪。"]', '["兩板船头濁酒壺，七絲琴畔白髭鬚。","三春日日黄梅雨，孤客年年青草湖。","燕俠冰霜难狎近，楚狂鋒刃觸凡愚。","知余絕粒窺仙事，許到名山看藥鑪。"]', '诗', 'shi', '', NULL, '贈湖南李思齊處士 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cff3a83-5bb0-4ea3-9af3-ff0d6e5b4960', '亂後却至近甸有感', '亂後却至近甸有感', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["狂童容易犯金門，比屋齊人作旅魂。","夜戶不扃生茂草，春渠自溢浸荒園。","關中忽見屯邊卒，塞外飜聞有漢村。","堪恨無情清渭水，渺茫依舊繞秦原。"]', '["狂童容易犯金门，比屋齊人作旅魂。","夜戶不扃生茂草，春渠自溢浸荒园。","关中忽见屯邊卒，塞外飜闻有漢村。","堪恨無情清渭水，渺茫依旧繞秦原。"]', '诗', 'shi', '', NULL, '亂後却至近甸有感 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faa7317d-d867-44b7-9a5e-6348bec254fa', '同年前虞部李郎中自長沙赴行在余以紫石硯贈之賦詩代書', '同年前虞部李郎中自长沙赴行在余以紫石硯贈之賦诗代书', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["斧柯新樣勝珠璣，堪贊星郎染翰時。","不向東垣修直疏，即須西掖草妍詞。","紫光稱近丹青筆，聲韻宜裁錦繡詩。","蓬島侍臣今放逐，羨君迴去逼龍墀。"]', '["斧柯新樣勝珠璣，堪贊星郎染翰时。","不向东垣修直疏，即須西掖草妍词。","紫光稱近丹青笔，声韻宜裁錦繡诗。","蓬島侍臣今放逐，羨君迴去逼龙墀。"]', '诗', 'shi', '', NULL, '同年前虞部李郎中自長沙赴行在余以紫石硯贈之賦詩代書 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('043e5d61-b57f-4e03-801f-8f7cfd7e2d2d', '甲子歲夏五月自長沙抵醴陵貴就深僻以便疎慵由道林之南步步勝絕去綠口分東入南小江山水益秀村籬之次忽見紫薇花因思玉堂及西掖廳前皆植是花遂賦詩四韻聊寄知心', '甲子歲夏五月自长沙抵醴陵貴就深僻以便疎慵由道林之南步步勝絕去綠口分东入南小江山水益秀村籬之次忽见紫薇花因思玉堂及西掖廳前皆植是花遂賦诗四韻聊寄知心', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["職在內庭宮闕下，廳前皆種紫薇花。","眼明忽傍漁家見，魂斷方驚魏闕賒。","淺色暈成宮裏錦，濃香染著洞中霞。","此行若遇支機石，又被君平驗海槎。"]', '["職在內庭宮闕下，廳前皆種紫薇花。","眼明忽傍漁家见，魂斷方驚魏闕賒。","淺色暈成宮裏錦，濃香染著洞中霞。","此行若遇支機石，又被君平驗海槎。"]', '诗', 'shi', '', NULL, '甲子歲夏五月自長沙抵醴陵貴就深僻以便疎慵由道林之南步步勝絕去綠口分東入南小江山水益秀村籬之次忽見紫薇花因思玉堂及西掖廳前皆植是花遂賦詩四韻聊寄知心 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ee7153-04ce-43f0-9078-47fa99358049', '和王舍人撫州飲席贈韋司空', '和王舍人撫州饮席贈韋司空', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["樓臺掩映入春寒，絲竹錚鏦向夜闌。","席上弟兄皆杞梓，花前賓客盡鴛鸞。","孫弘莫惜頻開閤，韓信終期別築壇。","削玉風姿官水土，黑頭公自古來難。"]', '["楼台掩映入春寒，絲竹錚鏦向夜闌。","席上弟兄皆杞梓，花前賓客尽鴛鸾。","孫弘莫惜頻开閤，韓信終期別築壇。","削玉风姿官水土，黑头公自古来难。"]', '诗', 'shi', '', NULL, '和王舍人撫州飲席贈韋司空 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118df6cd-cbc0-459f-b155-e7b2c98ed451', '避地寒食', '避地寒食', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["避地淹留已自悲，況逢寒食欲霑衣。","濃春孤館人愁坐，斜日空園花亂飛。","路遠漸憂知己少，時危又與賞心違。","一名所繫無窮事，爭敢當年便息機。"]', '["避地淹留已自悲，況逢寒食欲霑衣。","濃春孤館人愁坐，斜日空园花亂飞。","路远漸憂知己少，时危又與賞心違。","一名所繫無窮事，爭敢當年便息機。"]', '诗', 'shi', '', NULL, '避地寒食 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf42591e-6945-4ed6-a7c2-c98f90c248e8', '山驛', '山驛', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["參差西北數行雁，寥落東方幾片雲。","疊石小松張水部，暗山寒雨李將軍。","秋花粉黛宜無味，獨鳥笙簧稱靜聞。","瀟灑襟懷遺世慮，驛樓紅葉自紛紛。"]', '["參差西北數行雁，寥落东方幾片云。","叠石小松張水部，暗山寒雨李將軍。","秋花粉黛宜無味，独鸟笙簧稱静闻。","瀟灑襟懷遺世慮，驛楼紅葉自紛紛。"]', '诗', 'shi', '', NULL, '山驛 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('568001ac-a5d5-44ef-9eaa-62a8e7a76b40', '早發藍關', '早發藍关', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["關門愁立候雞鳴，搜景馳魂入杳冥。","雲外日隨千里雁，山根霜共一潭星。","路盤暫見樵人火，棧轉時聞驛使鈴。","自問辛勤緣底事，半年驅馬傍長亭。"]', '["关门愁立候雞鳴，搜景驰魂入杳冥。","云外日隨千里雁，山根霜共一潭星。","路盤暫见樵人火，棧轉时闻驛使鈴。","自问辛勤緣底事，半年驱马傍长亭。"]', '诗', 'shi', '', NULL, '早發藍關 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c1ae28a-a279-4207-8c5b-d5dcd5e51fd2', '深村', '深村', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["甘向深村固不材，猶勝摧折傍塵埃。","清宵翫月唯紅葉，永日關門但綠苔。","幽院菊荒同寂寞，野橋僧去獨裴回。","隔籬農叟遙相賀，□□□□膏雨來。"]', '["甘向深村固不材，猶勝摧折傍塵埃。","清宵翫月唯紅葉，永日关门但綠苔。","幽院菊荒同寂寞，野橋僧去独裴回。","隔籬農叟遙相賀，□□□□膏雨来。"]', '诗', 'shi', '', NULL, '深村 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4ca5c0-aad6-4c92-bf9e-fbda6813f57d', '重遊曲江', '重游曲江', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["追尋前事立江汀，漁者應聞太息聲。","避客野鷗如有感，損花微雪似無情。","疎林自覺長堤在，春水空連古岸平。","惆悵引人還到夜，鞭鞘風冷柳煙輕。"]', '["追尋前事立江汀，漁者應闻太息声。","避客野鷗如有感，損花微雪似無情。","疎林自覺长堤在，春水空連古岸平。","惆悵引人還到夜，鞭鞘风冷柳煙轻。"]', '诗', 'shi', '', NULL, '重遊曲江 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('511fd322-e75b-452e-a4a8-17b833aa932b', '三月', '三月', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["辛夷纔謝小桃發，蹋青過後寒食前。","四時最好是三月，一去不迴唯少年。","吳國地遙江接海，漢陵魂斷草連天。","新愁舊恨真無奈，須就鄰家甕底眠。"]', '["辛夷纔謝小桃發，蹋青過後寒食前。","四时最好是三月，一去不迴唯少年。","吳国地遙江接海，漢陵魂斷草連天。","新愁旧恨真無奈，須就鄰家甕底眠。"]', '诗', 'shi', '', NULL, '三月 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68c54db-98e7-4696-a8c5-d39ca0c75904', '秋村', '秋村', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["稻壟蓼紅溝水清，荻園葉白秋日明。","空坡路細見騎過，遠田人靜聞水行。","柴門狼藉牛羊氣，竹塢幽深雞犬聲。","絕粒看經香一炷，心知無事即長生。"]', '["稻壟蓼紅溝水清，荻园葉白秋日明。","空坡路細见騎過，远田人静闻水行。","柴门狼藉牛羊氣，竹塢幽深雞犬声。","絕粒看經香一炷，心知無事即长生。"]', '诗', 'shi', '', NULL, '秋村 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f984fbe1-6bab-4cb7-b9c6-801f9dac6b24', '殘花', '殘花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["餘霞殘雪幾多在，蔫香冶態猶無窮。","黃昏月下惆悵白，清明雨後寥𤞚紅。","樹底草齊千片淨，牆頭風急數枝空。","西園此日傷心處，一曲高歌水向東。"]', '["餘霞殘雪幾多在，蔫香冶態猶無窮。","黄昏月下惆悵白，清明雨後寥𤞚紅。","樹底草齊千片淨，牆头风急數枝空。","西园此日傷心处，一曲高歌水向东。"]', '诗', 'shi', '', NULL, '殘花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95eed0ec-1579-4c8c-8f16-925e130f6345', '夜船', '夜船', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["野雲低迷煙蒼蒼，平波揮目如凝霜。","月明船上簾幕卷，露重岸頭花木香。","村遠夜深無火燭，江寒坐久換衣裳。","誠知不覺天將曙，幾簇青山雁一行。"]', '["野云低迷煙蒼蒼，平波揮目如凝霜。","月明船上簾幕卷，露重岸头花木香。","村远夜深無火燭，江寒坐久換衣裳。","誠知不覺天將曙，幾簇青山雁一行。"]', '诗', 'shi', '', NULL, '夜船 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fd5f89d-4394-4f52-aadc-6a20825c83ae', '傷春', '傷春', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["三月光景不忍看，五陵春色何摧殘。","窮途得志反惆悵，飲席話舊多闌珊。","中酒向陽成美睡，惜花衝雨覺傷寒。","野棠飛盡蒲根暖，寂寞南溪倚釣竿。"]', '["三月光景不忍看，五陵春色何摧殘。","窮途得志反惆悵，饮席話旧多闌珊。","中酒向陽成美睡，惜花衝雨覺傷寒。","野棠飞尽蒲根暖，寂寞南溪倚釣竿。"]', '诗', 'shi', '', NULL, '傷春 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626f2e03-f11a-46b0-8c68-4c7dac25c7c4', '歸紫閣下', '归紫閣下', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一笈攜歸紫閣峰，馬蹄閑慢水溶溶。","黃昏後見山田火，朧{月悤}時聞縣郭鐘。","瘦竹迸生僧坐石，野藤纏殺鶴翹松。","釣磯自別經秋雨，長得莓苔更幾重。"]', '["一笈携归紫閣峰，马蹄闲慢水溶溶。","黄昏後见山田火，朧{月悤}时闻縣郭鐘。","瘦竹迸生僧坐石，野藤纏殺鹤翹松。","釣磯自別經秋雨，长得莓苔更幾重。"]', '诗', 'shi', '', NULL, '歸紫閣下 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94204506-4c6e-4cc8-8f8f-1ea3f34902d1', '夜坐', '夜坐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天似空江星似波，時時珠露滴圓荷。","平生蹤跡慕真隱，此夕襟懷深自多。","格是厭厭饒酒病，終須的的學漁歌。","無名無位堪休去，猶擬朝衣換釣蓑。"]', '["天似空江星似波，时时珠露滴圓荷。","平生蹤跡慕真隐，此夕襟懷深自多。","格是厭厭饒酒病，終須的的学漁歌。","無名無位堪休去，猶擬朝衣換釣蓑。"]', '诗', 'shi', '', NULL, '夜坐 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611f950a-0743-40bb-a620-f5b11bbb5735', '午寢夢江外兄弟', '午寢梦江外兄弟', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["長夏居閑門不開，繞門青草絕塵埃。","空庭日午獨眠覺，旅夢天涯相見迴。","鬢向此時應有雪，心從別處即成灰。","如何水陸三千里，幾月書郵始一來。"]', '["长夏居闲门不开，繞门青草絕塵埃。","空庭日午独眠覺，旅梦天涯相见迴。","鬢向此时應有雪，心從別处即成灰。","如何水陸三千里，幾月书郵始一来。"]', '诗', 'shi', '', NULL, '午寢夢江外兄弟 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66372a6c-64ab-418a-a9f7-040b6f53f3bb', '曲江夜思', '曲江夜思', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鼓聲將絕月斜痕，園外閑坊半掩門。","池裏紅蓮凝白露，苑中青草伴黃昏。","林塘闃寂偏宜夜，煙火稀疎便似村。","大抵世間幽獨景，最關詩思與離魂。"]', '["鼓声將絕月斜痕，园外闲坊半掩门。","池裏紅蓮凝白露，苑中青草伴黄昏。","林塘闃寂偏宜夜，煙火稀疎便似村。","大抵世间幽独景，最关诗思與離魂。"]', '诗', 'shi', '', NULL, '曲江夜思 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c6cadd-7683-455a-bccd-8a64807ac9d4', '過漢口', '過漢口', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["濁世清名一概休，古今飜覆賸堪愁。","年年春浪來巫峽，日日殘陽過沔州。","居雜商徒偏富庶，地多詞客自風流。","聯翩半世騰騰過，不在漁船即酒樓。"]', '["濁世清名一概休，古今飜覆賸堪愁。","年年春浪来巫峽，日日殘陽過沔州。","居杂商徒偏富庶，地多词客自风流。","聯翩半世腾腾過，不在漁船即酒楼。"]', '诗', 'shi', '', NULL, '過漢口 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8827a8a3-2164-47cd-8c47-211345dd707b', '惜春', '惜春', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["願言未偶非高臥，多病無憀選勝遊。","一夜雨聲三月盡，萬般人事五更頭。","年踰弱冠即爲老，節過清明却似秋。","應是西園花已落，滿溪紅片向東流。"]', '["願言未偶非高臥，多病無憀選勝游。","一夜雨声三月尽，万般人事五更头。","年踰弱冠即爲老，節過清明却似秋。","應是西园花已落，满溪紅片向东流。"]', '诗', 'shi', '', NULL, '惜春 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47a9ffc7-61fe-4dab-b5ef-6c92119b9a18', '及第過堂日作', '及第過堂日作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["早隨真侶集蓬瀛，閶闔門開尚見星。","龍尾樓臺迎曉日，鼇頭宮殿入青冥。","暗驚凡骨升仙籍，忽訝麻衣謁相庭。","百辟斂容開路看，片時輝赫勝圖形。"]', '["早隨真侶集蓬瀛，閶闔门开尚见星。","龙尾楼台迎晓日，鼇头宮殿入青冥。","暗驚凡骨升仙籍，忽訝麻衣謁相庭。","百辟斂容开路看，片时輝赫勝圖形。"]', '诗', 'shi', '', NULL, '及第過堂日作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ceaeb8c-4bcd-4d8c-a49a-01e1efdd3ec6', '夏課成感懷', '夏課成感懷', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["別離終日心忉忉，五湖煙波歸夢勞。","淒涼身事夏課畢，濩落生涯秋風高。","居世無媒多困躓，昔賢因此亦號咷。","誰憐愁苦多衰改，未到潘年有二毛。"]', '["別離終日心忉忉，五湖煙波归梦勞。","淒涼身事夏課畢，濩落生涯秋风高。","居世無媒多困躓，昔賢因此亦號咷。","誰怜愁苦多衰改，未到潘年有二毛。"]', '诗', 'shi', '', NULL, '夏課成感懷 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da7b2be-0ad0-4344-8c95-65bb529ae7e5', '離家第二日却寄諸兄弟', '離家第二日却寄諸兄弟', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["睡起褰簾日出時，今辰初恨間容輝。","千行淚激傍人感，一點心隨健步歸。","却望山川空黯黯，迴看僮僕亦依依。","定知兄弟高樓上，遙指征途羨鳥飛。"]', '["睡起褰簾日出时，今辰初恨间容輝。","千行泪激傍人感，一点心隨健步归。","却望山川空黯黯，迴看僮僕亦依依。","定知兄弟高楼上，遙指征途羨鸟飞。"]', '诗', 'shi', '', NULL, '離家第二日却寄諸兄弟 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a07628a0-7d96-4f37-9b7f-6e0f81056f8f', '遊江南水陸院', '游江南水陸院', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["早於喧雜是深讎，猶恐行藏墜俗流。","高寺嬾爲攜酒去，名山長恨送人遊。","關河見月空垂淚，風雨看花欲白頭。","除却祖師心法外，浮生何處不堪愁。"]', '["早於喧杂是深讎，猶恐行藏墜俗流。","高寺嬾爲携酒去，名山长恨送人游。","关河见月空垂泪，风雨看花欲白头。","除却祖師心法外，浮生何处不堪愁。"]', '诗', 'shi', '', NULL, '遊江南水陸院 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b429a614-b5cb-44ca-89f2-d253f196bd00', '江南送別', '江南送別', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["江南行止忽相逢，江館棠棃葉正紅。","一笑共嗟成往事，半酣相顧似衰翁。","關山月皎清風起，送別人歸野渡空。","大抵多情應易老，不堪岐路數西東。"]', '["江南行止忽相逢，江館棠棃葉正紅。","一笑共嗟成往事，半酣相顧似衰翁。","关山月皎清风起，送別人归野渡空。","大抵多情應易老，不堪岐路數西东。"]', '诗', 'shi', '', NULL, '江南送別 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64884e6b-1886-4394-9869-95cc8a7d9c6c', '格卑', '格卑', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["格卑嘗恨足牽仍，欲學忘情似不能。","入意雲山輸畫匠，動人風月羨琴僧。","南朝峻潔推弘景，東晉清狂數季鷹。","惆悵後塵流落盡，自拋懷抱醉懵騰。"]', '["格卑嘗恨足牽仍，欲学忘情似不能。","入意云山輸畫匠，动人风月羨琴僧。","南朝峻潔推弘景，东晉清狂數季鷹。","惆悵後塵流落尽，自拋懷抱醉懵腾。"]', '诗', 'shi', '', NULL, '格卑 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d6aaf6c-ce45-4ecf-9c2d-3a5c438979ee', '冬日', '冬日', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["蕭條古木銜斜日，戚瀝晴寒滯早梅。","愁處雪煙連野起，靜時風竹過牆來。","故人每憶心先見，新酒偷嘗手自開。","景狀入詩兼入畫，言情不盡恨無才。"]', '["蕭條古木銜斜日，戚瀝晴寒滯早梅。","愁处雪煙連野起，静时风竹過牆来。","故人每憶心先见，新酒偷嘗手自开。","景狀入诗兼入畫，言情不尽恨無才。"]', '诗', 'shi', '', NULL, '冬日 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e5d589-8f23-4c1e-b053-8f3ae70745e8', '再止廟居', '再止廟居', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["去值秋風來值春，前時今日共銷魂。","頹坦古柏疑山關，高柳鳴鴉似水村。","菜甲未齊初出葉，樹陰方合掩重門。","幽深凍餒皆推分，靜者還應爲討論。"]', '["去值秋风来值春，前时今日共銷魂。","頹坦古柏疑山关，高柳鳴鴉似水村。","菜甲未齊初出葉，樹陰方合掩重门。","幽深凍餒皆推分，静者還應爲討論。"]', '诗', 'shi', '', NULL, '再止廟居 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aceab09-f9a5-41f7-bfb0-0d727392d6c1', '老將', '老將', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["折槍黃馬倦塵埃，掩耳凶徒怕疾雷。","雪密酒酣偷號去，月明衣冷斫營回。","行驅貔虎披金甲，立聽笙歌擲玉杯。","坐久不須輕矍鑠，至今雙擘硬弓開。"]', '["折槍黄马倦塵埃，掩耳凶徒怕疾雷。","雪密酒酣偷號去，月明衣冷斫營回。","行驱貔虎披金甲，立听笙歌擲玉杯。","坐久不須轻矍鑠，至今雙擘硬弓开。"]', '诗', 'shi', '', NULL, '老將 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('943034f5-322e-496f-8839-4cf8d435348d', '邊上看獵贈元戎', '邊上看獵贈元戎', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["繡簾臨曉覺新霜，便遣移廚較獵場。","燕卒鐵衣圍漢相，魯儒戎服從梁王。","搜山閃閃旗頭遠，出樹斑斑豹尾長。","贊獲一聲連朔漠，賀杯環騎舞優倡。","軍迴野靜秋天白，角怨城遙晚照黃。","紅袖擁門持燭炬，解勞今夜宴華堂。"]', '["繡簾臨晓覺新霜，便遣移廚較獵場。","燕卒鐵衣圍漢相，魯儒戎服從梁王。","搜山閃閃旗头远，出樹斑斑豹尾长。","贊獲一声連朔漠，賀杯环騎舞優倡。","軍迴野静秋天白，角怨城遙晚照黄。","紅袖擁门持燭炬，解勞今夜宴华堂。"]', '诗', 'shi', '', NULL, '邊上看獵贈元戎 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3029a767-6580-4537-84b9-f9bcb65fafa3', '余自刑部員外郎爲權所擠值盤石出鎮藩屏朝選賓佐以余充職掌記鬱鬱不樂因成長句寄所知', '余自刑部員外郎爲權所擠值盤石出鎮藩屏朝選賓佐以余充職掌記鬱鬱不乐因成长句寄所知', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["正叨清級忽從戎，況與燕臺事不同。","開口謾勞矜道在，撫膺唯合哭途窮。","操心未省趨浮俗，點額尤慙自至公。"]', '["正叨清級忽從戎，況與燕台事不同。","开口謾勞矜道在，撫膺唯合哭途窮。","操心未省趨浮俗，点額尤慙自至公。"]', '诗', 'shi', '', NULL, '余自刑部員外郎爲權所擠值盤石出鎮藩屏朝選賓佐以余充職掌記鬱鬱不樂因成長句寄所知 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a50c02d-d4a4-421f-bae1-19505d448482', '北齊二首 一', '北齊二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["任道驕奢必敗亡，且將繁盛悅嬪嬙。","幾千籢鏡成樓柱，六十間雲號殿廊。","後主獵迴初按樂，胡姬酒醒更新妝。","綺羅堆裏春風畔，年少多情一帝王。"]', '["任道驕奢必敗亡，且將繁盛悅嬪嬙。","幾千籢镜成楼柱，六十间云號殿廊。","後主獵迴初按乐，胡姬酒醒更新妝。","綺羅堆裏春风畔，年少多情一帝王。"]', '诗', 'shi', '', NULL, '北齊二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce88cb23-d73d-429b-b8fc-59955666596f', '北齊二首 二', '北齊二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["神器傳時異至公，敗亡安可怨悤悤。","犯寒獵士朝頻戮，告急軍書夜不通。","幷部義旗遮日暗，鄴城飛燄照天紅。","周朝將相還無體，寧死何須入鐵籠。"]', '["神器傳时異至公，敗亡安可怨悤悤。","犯寒獵士朝頻戮，告急軍书夜不通。","幷部義旗遮日暗，鄴城飞燄照天紅。","周朝將相還無體，寧死何須入鐵籠。"]', '诗', 'shi', '', NULL, '北齊二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2221d898-d539-4a0f-839b-eb96aa5946b0', '寄京城親友二首 一', '寄京城親友二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["苦吟看墜葉，寥落共天涯。","壯歲空爲客，初寒更憶家。","雨牆經月蘚，山菊向陽花。","因味碧雲句，傷哉後會賒。"]', '["苦吟看墜葉，寥落共天涯。","壯歲空爲客，初寒更憶家。","雨牆經月蘚，山菊向陽花。","因味碧云句，傷哉後會賒。"]', '诗', 'shi', '', NULL, '寄京城親友二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7011a550-3042-435b-95f5-9870f142907c', '寄京城親友二首 二', '寄京城親友二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["相思凡幾日，日欲詠離衿。","直得吟成病，終難狀此心。","解衣悲緩帶，搔首悶遺簪。","西嶺斜陽外，潛疑是故林。"]', '["相思凡幾日，日欲詠離衿。","直得吟成病，終难狀此心。","解衣悲緩带，搔首悶遺簪。","西嶺斜陽外，潛疑是故林。"]', '诗', 'shi', '', NULL, '寄京城親友二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a085662a-fc0c-4923-9bf1-96dac2648e26', '野寺', '野寺', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["野寺看紅葉，縣城聞擣衣。","自憐癡病苦，猶共賞心違。","高閣正臨夜，前山應落暉。","離情在煙鳥，遙入故關飛。"]', '["野寺看紅葉，縣城闻擣衣。","自怜癡病苦，猶共賞心違。","高閣正臨夜，前山應落暉。","離情在煙鸟，遙入故关飞。"]', '诗', 'shi', '', NULL, '野寺 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266820f7-248a-4bf5-b601-8d54165d5ef2', '吳郡懷古', '吳郡懷古', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["主暗臣忠枉就刑，遂教強國醉中傾。","人亡建業空城在，花落西江春水平。","萬古壯夫猶抱恨，至今詞客盡傷情。","徒勞鐵鎖長千尺，不覺樓船下晉兵。"]', '["主暗臣忠枉就刑，遂教強国醉中傾。","人亡建業空城在，花落西江春水平。","万古壯夫猶抱恨，至今词客尽傷情。","徒勞鐵鎖长千尺，不覺楼船下晉兵。"]', '诗', 'shi', '', NULL, '吳郡懷古 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de0b12c-2cab-403b-9242-4ae9a79fae11', '守愚', '守愚', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["深院寥寥竹蔭廊，披衣欹枕過年芳。","守愚不覺世途險，無事始知春日長。","一畝落花圍隙地，半竿濃日界空牆。","今來自責趨時嬾，飜恨松軒書滿牀。"]', '["深院寥寥竹蔭廊，披衣欹枕過年芳。","守愚不覺世途險，無事始知春日长。","一畝落花圍隙地，半竿濃日界空牆。","今来自責趨时嬾，飜恨松軒书满牀。"]', '诗', 'shi', '', NULL, '守愚 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936d2ab6-9f39-48f8-8993-27faba27d037', '村居', '村居', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["二月三月雨晴初，舍南舍北唯平蕪。","前懽入望盈千恨，勝景牽心非一途。","日照神堂聞啄木，風含社樹叫提壺。","行看旦夕棃霜發，猶有山寒傷酒壚。"]', '["二月三月雨晴初，舍南舍北唯平蕪。","前懽入望盈千恨，勝景牽心非一途。","日照神堂闻啄木，风含社樹叫提壺。","行看旦夕棃霜發，猶有山寒傷酒壚。"]', '诗', 'shi', '', NULL, '村居 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c925083f-e765-45b4-a395-ae31d5f5be88', '離家', '離家', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["八月初長夜，千山第一程。","款顏唯有夢，怨泣却無聲。","祖席諸賓散，空郊匹馬行。","自憐非達識，局促爲浮名。"]', '["八月初长夜，千山第一程。","款顏唯有梦，怨泣却無声。","祖席諸賓散，空郊匹马行。","自怜非達識，局促爲浮名。"]', '诗', 'shi', '', NULL, '離家 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd063b7-6d59-4aba-8b68-06ea57031935', '秋雨內宴', '秋雨內宴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一帶清風入畫堂，撼真珠箔碎玎璫。","更看檻外霏霏雨，似勸須教醉玉觴。"]', '["一带清风入畫堂，撼真珠箔碎玎璫。","更看檻外霏霏雨，似勸須教醉玉觴。"]', '诗', 'shi', '', NULL, '秋雨內宴 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fc6879b-525f-45df-8790-4075dbe27ab2', '寒食日沙縣雨中看薔薇', '寒食日沙縣雨中看薔薇', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["何處遇薔薇，殊鄉冷節時。","雨聲籠錦帳，風勢偃羅幃。","通體全無力，酡顏不自持。","綠疎微露刺，紅密欲藏枝。","愜意凭闌久，貪吟放醆遲。","旁人應見訝，自醉自題詩。"]', '["何处遇薔薇，殊乡冷節时。","雨声籠錦帳，风勢偃羅幃。","通體全無力，酡顏不自持。","綠疎微露刺，紅密欲藏枝。","愜意凭闌久，貪吟放醆遲。","旁人應见訝，自醉自題诗。"]', '诗', 'shi', '', NULL, '寒食日沙縣雨中看薔薇 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361e7cd1-0717-4284-b0ba-21e027f2a97e', '地爐', '地爐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["兩星殘火地爐畔，夢斷背燈重擁衾。","側聽空堂聞靜響，似敲疎磬褭清音。","風燈有影隨籠轉，臘雪無聲逐夜深。","禪客釣翁徒自好，那知此際湛然心。"]', '["兩星殘火地爐畔，梦斷背灯重擁衾。","側听空堂闻静响，似敲疎磬褭清音。","风灯有影隨籠轉，臘雪無声逐夜深。","禪客釣翁徒自好，那知此際湛然心。"]', '诗', 'shi', '', NULL, '地爐 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7054287-c59b-484e-8fe5-3d6196d52b57', '隰州新驛贈刺史', '隰州新驛贈刺史', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["賢侯新換古長亭，先定心機指顧成。","高義盡招秦逐客，曠懷偏接魯諸生。","萍蓬到此銷離恨，燕雀飛來帶喜聲。","却笑昔賢交易極，一開東閤便垂名。"]', '["賢侯新換古长亭，先定心機指顧成。","高義尽招秦逐客，曠懷偏接魯諸生。","萍蓬到此銷離恨，燕雀飞来带喜声。","却笑昔賢交易極，一开东閤便垂名。"]', '诗', 'shi', '', NULL, '隰州新驛贈刺史 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2068b0e-af40-46d6-9c30-7371f4ba32ab', '草書屏風', '草书屏风', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["何處一屏風，分明懷素蹤。","雖多塵色染，猶見墨痕濃。","怪石奔秋澗，寒藤挂古松。","若教臨水畔，字字恐成龍。"]', '["何处一屏风，分明懷素蹤。","雖多塵色染，猶见墨痕濃。","怪石奔秋澗，寒藤挂古松。","若教臨水畔，字字恐成龙。"]', '诗', 'shi', '', NULL, '草書屏風 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd9c9cf-31b1-4a97-9fce-525d3b7a643c', '永明禪師房', '永明禪師房', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["景色方妍媚，尋真出近郊。","寶香爐上爇，金磬佛前敲。","蔓草稜山徑，晴雲拂樹梢。","支公禪寂處，時有鶴來巢。"]', '["景色方妍媚，尋真出近郊。","寶香爐上爇，金磬佛前敲。","蔓草稜山徑，晴云拂樹梢。","支公禪寂处，时有鹤来巢。"]', '诗', 'shi', '', NULL, '永明禪師房 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f696b6ad-5546-4b3e-9f4e-128669e5e5d8', '登樓有題', '登楼有題', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["暑氣檐前過，蟬聲樹杪交。","待潮生浦口，看雨過山坳。","才見蘭舟動，仍聞桂檝敲。","窣雲朱檻好，終覩鳳來巢。"]', '["暑氣檐前過，蟬声樹杪交。","待潮生浦口，看雨過山坳。","才见蘭舟动，仍闻桂檝敲。","窣云朱檻好，終覩鳳来巢。"]', '诗', 'shi', '', NULL, '登樓有題 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0532fb36-14b8-485d-b1d7-28e610073650', '朝退書懷', '朝退书懷', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鶴帔星冠羽客裝，寢樓西畔坐書堂。","山禽養久知人喚，窗竹芟多漏月光。","粉壁不題新拙惡，小屏唯錄古篇章。","孜孜莫患勞心力，富國安民理道長。"]', '["鹤帔星冠羽客裝，寢楼西畔坐书堂。","山禽養久知人喚，窗竹芟多漏月光。","粉壁不題新拙惡，小屏唯錄古篇章。","孜孜莫患勞心力，富国安民理道长。"]', '诗', 'shi', '', NULL, '朝退書懷 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1994c0bf-2857-436e-9013-3cbd7b15b39c', '元夜即席', '元夜即席', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["元宵清景亞元正，絲雨霏霏向晚傾。","桂兔韜光雲葉重，燭龍銜耀月輪明。","煙空但仰如膏潤，綺席都忘滴砌聲。","更待今宵開霽後，九衢車馬未妨行。"]', '["元宵清景亞元正，絲雨霏霏向晚傾。","桂兔韜光云葉重，燭龙銜耀月輪明。","煙空但仰如膏潤，綺席都忘滴砌声。","更待今宵开霽後，九衢车马未妨行。"]', '诗', 'shi', '', NULL, '元夜即席 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d344565-86ef-4819-bbb2-8b851597bd70', '大慶堂賜宴元璫而有詩呈吳越王', '大慶堂賜宴元璫而有诗呈吳越王', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["非爲親賢展綺筵，恆常寧敢恣遊盤。","綠搓楊柳緜初輭，紅暈櫻桃粉未乾。","谷鳥乍啼聲似澀，甘霖方霽景猶寒。","笙歌風緊人酣醉，却繞珍叢爛熳看。"]', '["非爲親賢展綺筵，恆常寧敢恣游盤。","綠搓楊柳緜初輭，紅暈櫻桃粉未乾。","谷鸟乍啼声似澀，甘霖方霽景猶寒。","笙歌风緊人酣醉，却繞珍叢爛熳看。"]', '诗', 'shi', '', NULL, '大慶堂賜宴元璫而有詩呈吳越王 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c825b83c-8680-48bc-9180-94208572aeb8', '又和大慶堂賜宴元璫而有詩呈吳越王', '又和大慶堂賜宴元璫而有诗呈吳越王', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["櫻桃花下會親賢，風遠銅烏轉露盤。","蝶下粉牆梅乍坼，蟻浮金斝酒難乾。","雲和緩奏泉聲咽，珠箔低垂水影寒。","狂簡斐然吟詠足，却邀羣彥重吟看。"]', '["櫻桃花下會親賢，风远銅烏轉露盤。","蝶下粉牆梅乍坼，蟻浮金斝酒难乾。","云和緩奏泉声咽，珠箔低垂水影寒。","狂簡斐然吟詠足，却邀羣彥重吟看。"]', '诗', 'shi', '', NULL, '又和大慶堂賜宴元璫而有詩呈吳越王 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42e18cf9-2f1a-4600-b502-67fe4aa53f55', '再和大慶堂賜宴元璫而有詩呈吳越王', '再和大慶堂賜宴元璫而有诗呈吳越王', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["我有嘉賓宴乍歡，畫簾紋細鳳雙盤。","影籠沼沚修篁密，聲透笙歌羯鼓乾。","散後便依書篋寐，渴來潛想玉壺寒。","櫻桃零落紅桃媚，更俟旬餘共醉看。"]', '["我有嘉賓宴乍歡，畫簾紋細鳳雙盤。","影籠沼沚修篁密，声透笙歌羯鼓乾。","散後便依书篋寐，渴来潛想玉壺寒。","櫻桃零落紅桃媚，更俟旬餘共醉看。"]', '诗', 'shi', '', NULL, '再和大慶堂賜宴元璫而有詩呈吳越王 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea410d34-6364-406b-b508-f100622440fa', '重和大慶堂賜宴元璫而有詩呈吳越王', '重和大慶堂賜宴元璫而有诗呈吳越王', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["冷宴殷勤展小園，舞鞇柔輭綵虯盤。","篸花盡日疑頭重，病酒經宵覺口乾。","嘉樹倚樓青瑣暗，晚雲藏雨碧山寒。","文章天子文章別，八米盧郎未可看。"]', '["冷宴殷勤展小园，舞鞇柔輭綵虯盤。","篸花尽日疑头重，病酒經宵覺口乾。","嘉樹倚楼青瑣暗，晚云藏雨碧山寒。","文章天子文章別，八米盧郎未可看。"]', '诗', 'shi', '', NULL, '重和大慶堂賜宴元璫而有詩呈吳越王 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b46888-2a9d-494b-8063-283b6e18bdef', '余作探使以繚綾手帛子寄賀因而有詩', '余作探使以繚綾手帛子寄賀因而有诗', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["解寄繚綾小字封，探花筵上映春叢。","黛眉印在微微綠，檀口消來薄薄紅。","緶處直應心共緊，砑時兼恐汗先融。","帝臺春盡還東去，却繫帬腰伴雪胷。"]', '["解寄繚綾小字封，探花筵上映春叢。","黛眉印在微微綠，檀口消来薄薄紅。","緶处直應心共緊，砑时兼恐汗先融。","帝台春尽還东去，却繫帬腰伴雪胷。"]', '诗', 'shi', '', NULL, '余作探使以繚綾手帛子寄賀因而有詩 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a81572-7480-4250-9b49-3a4d89133fa9', '別錦兒', '別錦兒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一尺紅綃一首詩，贈君相別兩相思。","畫眉今日空留語，解佩他年更可期。","臨去莫論交頸意，清歌休著斷腸詞。","出門何事休惆悵，曾夢良人折桂枝。"]', '["一尺紅綃一首诗，贈君相別兩相思。","畫眉今日空留語，解佩他年更可期。","臨去莫論交頸意，清歌休著斷腸词。","出门何事休惆悵，曾梦良人折桂枝。"]', '诗', 'shi', '', NULL, '別錦兒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021d9666-1711-4b18-970b-4ed31eb2b178', '閑步', '闲步', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["莊南縱步遊荒野，獨鳥寒煙輕惹惹。","傍山疎雨溼秋花，僻路淺泉浮敗果。","樵人相見指驚麏，牧童四散收嘶馬。","一壺傾盡未能歸，黃昏更望諸峰火。"]', '["莊南縱步游荒野，独鸟寒煙轻惹惹。","傍山疎雨溼秋花，僻路淺泉浮敗果。","樵人相见指驚麏，牧童四散收嘶马。","一壺傾尽未能归，黄昏更望諸峰火。"]', '诗', 'shi', '', NULL, '閑步 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5c4cc2-f903-46d8-be20-5eb2b098d68b', '乾寧三年丙辰在奉天重圍作', '乾寧三年丙辰在奉天重圍作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["仗劒夜巡城，衣襟滿霜霰。","賊火徧郊坰，飛燄侵星漢。","積雪似空江，長林如斷岸。","獨凭女牆頭，思家起長歎。"]', '["仗劒夜巡城，衣襟满霜霰。","賊火徧郊坰，飞燄侵星漢。","積雪似空江，长林如斷岸。","独凭女牆头，思家起长歎。"]', '诗', 'shi', '', NULL, '乾寧三年丙辰在奉天重圍作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde60786-075b-4447-ae3a-2c398241e9bf', '雨中', '雨中', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["青桐承雨聲，聲聲何重疊。","疎滴下高枝，次打敧低葉。","鳥溼更梳翎，人愁方拄頰。","獨自上西樓，風襟寒帖帖。"]', '["青桐承雨声，声声何重叠。","疎滴下高枝，次打敧低葉。","鸟溼更梳翎，人愁方拄頰。","独自上西楼，风襟寒帖帖。"]', '诗', 'shi', '', NULL, '雨中 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577e12b2-9f7e-4815-8bb6-e91a02690d57', '與僧', '與僧', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["江海扁舟客，雲山一衲僧。","相逢兩無語，若箇是南能。"]', '["江海扁舟客，云山一衲僧。","相逢兩無語，若箇是南能。"]', '诗', 'shi', '', NULL, '與僧 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ab5b79-1b3d-405e-a261-71de1236f091', '晚岸', '晚岸', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["揭起青𦪪上岸頭，野花和雨冷脩脩。","春江一夜無波浪，校得行人分外愁。"]', '["揭起青𦪪上岸头，野花和雨冷脩脩。","春江一夜無波浪，校得行人分外愁。"]', '诗', 'shi', '', NULL, '晚岸 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('557c3fa3-04ee-46d0-92af-e059d3d0427d', '仙山', '仙山', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一炷心香洞府開，偃松皺澀半莓苔。","水清無底山如削，始有仙人騎鶴來。"]', '["一炷心香洞府开，偃松皺澀半莓苔。","水清無底山如削，始有仙人騎鹤来。"]', '诗', 'shi', '', NULL, '仙山 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eae55d1-8f2b-498e-8b32-8282f487e976', '過茂陵', '過茂陵', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["不悲霜露但傷春，孝理何因感兆民。","景帝龍髯消息斷，異香空見李夫人。"]', '["不悲霜露但傷春，孝理何因感兆民。","景帝龙髯消息斷，異香空见李夫人。"]', '诗', 'shi', '', NULL, '過茂陵 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb694f00-4f8e-47fc-82f0-16d9726ef918', '曲江秋日', '曲江秋日', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["斜煙縷縷鷺鷥棲，藕葉枯香折野泥。","有箇高僧入圖畫，把經吟立水塘西。"]', '["斜煙縷縷鷺鷥棲，藕葉枯香折野泥。","有箇高僧入圖畫，把經吟立水塘西。"]', '诗', 'shi', '', NULL, '曲江秋日 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5035184-1a66-4c43-b1b4-737110270921', '流年', '流年', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["三月傷心仍晦日，一春多病更陰天。","雄豪亦有流年恨，況是離魂易黯然。"]', '["三月傷心仍晦日，一春多病更陰天。","雄豪亦有流年恨，況是離魂易黯然。"]', '诗', 'shi', '', NULL, '流年 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df9936ec-3cf6-4f5a-892f-4e4292df4612', '商山道中', '商山道中', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["雲橫峭壁水平鋪，渡口人家日欲晡。","却憶往年看粉本，始知名畫有工夫。"]', '["云橫峭壁水平鋪，渡口人家日欲晡。","却憶往年看粉本，始知名畫有工夫。"]', '诗', 'shi', '', NULL, '商山道中 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6de5623-7f11-4b4c-8643-e5b0bfc9cffe', '招隱', '招隐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["立意忘機機已生，可能朝市汙高情。","時人未會嚴陵志，不釣鱸魚只釣名。"]', '["立意忘機機已生，可能朝市汙高情。","时人未會嚴陵志，不釣鱸鱼只釣名。"]', '诗', 'shi', '', NULL, '招隱 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85b808ec-f148-4031-872a-71d89d0b03cd', '雨村', '雨村', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["雁行斜拂雨村樓，簾下三重幕一鉤。","倚柱不知身半溼，黃昏獨自未迴頭。"]', '["雁行斜拂雨村楼，簾下三重幕一鉤。","倚柱不知身半溼，黄昏独自未迴头。"]', '诗', 'shi', '', NULL, '雨村 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0500d26b-4376-45a9-a8f1-148edec200df', '使風', '使风', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["茶煙睡覺心無事，一卷黃庭在手中。","敧枕卷簾江萬里，舟人不語滿帆風。"]', '["茶煙睡覺心無事，一卷黄庭在手中。","敧枕卷簾江万里，舟人不語满帆风。"]', '诗', 'shi', '', NULL, '使風 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f72fc7-f762-4e24-a1de-301239569d50', '阻風', '阻风', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["平生情趣羨漁師，此日煙江愜所思。","肥鱖香秔小艛艓，斷腸滋味阻風時。"]', '["平生情趣羨漁師，此日煙江愜所思。","肥鱖香秔小艛艓，斷腸滋味阻风时。"]', '诗', 'shi', '', NULL, '阻風 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b823e0cf-13d4-49c6-9553-2b8459d168a6', '幷州', '幷州', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["戍旗青草接榆關，雨裏幷州四月寒。","誰會凭闌潛忍淚，不勝天際似江干。"]', '["戍旗青草接榆关，雨裏幷州四月寒。","誰會凭闌潛忍泪，不勝天際似江干。"]', '诗', 'shi', '', NULL, '幷州 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb9caef8-ee28-4d7b-92ab-53d7371aff26', '夏夜', '夏夜', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["猛風飄電黑雲生，霎霎高林簇雨聲。","夜久雨休風又定，斷雲流月却斜明。"]', '["猛风飄電黑云生，霎霎高林簇雨声。","夜久雨休风又定，斷云流月却斜明。"]', '诗', 'shi', '', NULL, '夏夜 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd976142-6f60-418b-b9c0-fe1fbc3bfdad', '闌干', '闌干', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["埽花雖恨夜來雨，把酒却憐晴後寒。","吳質謾言愁得病，當時猶不凭闌干。"]', '["埽花雖恨夜来雨，把酒却怜晴後寒。","吳質謾言愁得病，當时猶不凭闌干。"]', '诗', 'shi', '', NULL, '闌干 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae4c769-82dd-48a8-a391-48a4c4804b75', '以庭前海棠棃花一枝寄李十九員外', '以庭前海棠棃花一枝寄李十九員外', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["二月春風澹蕩時，旅人虛對海棠棃。","不如寄與星郎去，想得朝回正畫眉。"]', '["二月春风澹蕩时，旅人虛对海棠棃。","不如寄與星郎去，想得朝回正畫眉。"]', '诗', 'shi', '', NULL, '以庭前海棠棃花一枝寄李十九員外 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1383e53-6ff9-4ada-ac7b-98098025637d', '驛樓', '驛楼', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["流雲溶溶水悠悠，故鄉千里空迴頭。","三更猶凭闌干月，淚滿關山孤驛樓。"]', '["流云溶溶水悠悠，故乡千里空迴头。","三更猶凭闌干月，泪满关山孤驛楼。"]', '诗', 'shi', '', NULL, '驛樓 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc5cd0e-1d3f-475b-a3a6-aeef9765a896', '頻訪盧秀才', '頻訪盧秀才', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["藥訣棊經思致論，柳腰蓮臉本忘情。","頻頻強入風流坐，酒肆應疑阮步兵。"]', '["藥訣棊經思致論，柳腰蓮臉本忘情。","頻頻強入风流坐，酒肆應疑阮步兵。"]', '诗', 'shi', '', NULL, '頻訪盧秀才 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b447cd88-87d9-445e-ab03-76b3b998821a', '荅友人見寄酒', '荅友人见寄酒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["雖可忘憂矣，其如作病何。","淋漓滿襟袖，更發楚狂歌。"]', '["雖可忘憂矣，其如作病何。","淋漓满襟袖，更發楚狂歌。"]', '诗', 'shi', '', NULL, '荅友人見寄酒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4afdf208-2b80-4665-a3e2-23a8bbd4e955', '野釣', '野釣', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["細雨桃花水，輕鷗逆浪飛。","風頭阻歸櫂，坐睡倚蓑衣。"]', '["細雨桃花水，轻鷗逆浪飞。","风头阻归櫂，坐睡倚蓑衣。"]', '诗', 'shi', '', NULL, '野釣 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c86f9f2e-ddf0-4d1f-beaa-56fe2fef9a87', '曲江晚思', '曲江晚思', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["雲物陰寂歷，竹木寒青蒼。","水冷鷺鷥立，煙月愁昏黃。"]', '["云物陰寂歷，竹木寒青蒼。","水冷鷺鷥立，煙月愁昏黄。"]', '诗', 'shi', '', NULL, '曲江晚思 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ffe24e6-8eb5-44c0-be0a-c26de43cf5f4', '贈友人', '贈友人', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["莫嫌談笑與經過，却恐閑多病亦多。","若遣心中無一事，不知爭奈日長何。"]', '["莫嫌談笑與經過，却恐闲多病亦多。","若遣心中無一事，不知爭奈日长何。"]', '诗', 'shi', '', NULL, '贈友人 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6529d0f-9b9a-46dd-9d96-867ddd5e565c', '半睡', '半睡', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["眉山暗澹向殘燈，一半雲鬟墜枕稜。","四體著人嬌欲泣，自家揉損砑繚綾。"]', '["眉山暗澹向殘灯，一半云鬟墜枕稜。","四體著人嬌欲泣，自家揉損砑繚綾。"]', '诗', 'shi', '', NULL, '半睡 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73ad083b-da5b-4d0b-8af6-d2c1ece6cc76', '已涼', '已涼', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["愁多却訝天涼早，思倦飜嫌夜漏遲。","何處山川孤館裏，向燈彎盡一雙眉。"]', '["愁多却訝天涼早，思倦飜嫌夜漏遲。","何处山川孤館裏，向灯彎尽一雙眉。"]', '诗', 'shi', '', NULL, '已涼 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c204ce3c-21ce-43ad-9537-703e4c26fa6a', '寄禪師', '寄禪師', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["從無入有雲峰聚，已有還無電火銷。","銷聚本來皆是幻，世間閑口漫囂囂。"]', '["從無入有云峰聚，已有還無電火銷。","銷聚本来皆是幻，世间闲口漫囂囂。"]', '诗', 'shi', '', NULL, '寄禪師 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16506161-f82b-493d-a0d0-1c324d14e9ef', '訪明公大德', '訪明公大德', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["寸髮如霜袒右肩，倚肩筇竹貌怡然。","懸燈深屋夜分坐，移榻向陽齋後眠。","刮膜且揚三毒論，攝心徐指二宗禪。","清涼藥分能知味，各自胷中有醴泉。"]', '["寸髮如霜袒右肩，倚肩筇竹貌怡然。","懸灯深屋夜分坐，移榻向陽斋後眠。","刮膜且揚三毒論，攝心徐指二宗禪。","清涼藥分能知味，各自胷中有醴泉。"]', '诗', 'shi', '', NULL, '訪明公大德 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c551b53f-7d06-4acc-9859-97040190e81b', '大酺樂', '大酺乐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["晚日催弦管，春風入綺羅。","杏花如有意，偏落舞衫多。"]', '["晚日催弦管，春风入綺羅。","杏花如有意，偏落舞衫多。"]', '诗', 'shi', '', NULL, '大酺樂 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d96149c-b4b2-4ebe-942e-108e2fabec03', '思歸樂', '思归乐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["淚滴珠難盡，容殊玉易銷。","儻隨明月去，莫道夢魂遙。"]', '["泪滴珠难尽，容殊玉易銷。","儻隨明月去，莫道梦魂遙。"]', '诗', 'shi', '', NULL, '思歸樂 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51280f0b-5a60-4865-80b1-557a1e6d008e', '御製春遊長句', '御製春游长句', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天意分明道已光，春遊嘉景勝仙鄉。","玉爐煙直風初靜，銀漢雲消日正長。","柳帶似眉全展綠，杏苞如臉半開香。","黃鶯歷歷啼紅樹，紫燕關關語畫梁。","低檻晚晴籠翡翠，小池波暖浴鴛鴦。","馬嘶廣陌貪新草，人醉花堤怕夕陽。","比屋管弦呈妙曲，連營羅綺鬬時妝。","全吳霸越千年後，獨此升平顯萬方。"]', '["天意分明道已光，春游嘉景勝仙乡。","玉爐煙直风初静，銀漢云消日正长。","柳带似眉全展綠，杏苞如臉半开香。","黄鶯歷歷啼紅樹，紫燕关关語畫梁。","低檻晚晴籠翡翠，小池波暖浴鴛鴦。","马嘶廣陌貪新草，人醉花堤怕夕陽。","比屋管弦呈妙曲，連營羅綺鬬时妝。","全吳霸越千年後，独此升平显万方。"]', '诗', 'shi', '', NULL, '御製春遊長句 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73ba6059-c8e0-4dec-81ad-534398fae2da', '幽窗', '幽窗', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["刺繡非無暇，幽窗自尟歡。","手香江橘嫩，齒輭越梅酸。","密約臨行怯，私書欲報難。","無憑諳鵲語，猶得暫心寬。"]', '["刺繡非無暇，幽窗自尟歡。","手香江橘嫩，齒輭越梅酸。","密約臨行怯，私书欲報难。","無憑諳鵲語，猶得暫心寬。"]', '诗', 'shi', '', NULL, '幽窗 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4034153b-4490-4b55-81d8-d1129753f56b', '江樓二首 一', '江楼二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["夢啼嗚咽覺無語，杳杳微微望煙浦。","樓空客散燕交飛，江靜帆飛日亭午。"]', '["梦啼嗚咽覺無語，杳杳微微望煙浦。","楼空客散燕交飞，江静帆飞日亭午。"]', '诗', 'shi', '', NULL, '江樓二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d3f7f00-9c7c-48c1-a0cd-46150bf4ef84', '江樓二首 二', '江楼二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鳀魚苦筍香味新，楊柳酒旗三月春。","風光百計牽人老，爭奈多情是病身。"]', '["鳀鱼苦筍香味新，楊柳酒旗三月春。","风光百計牽人老，爭奈多情是病身。"]', '诗', 'shi', '', NULL, '江樓二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('735d0f6c-1338-4d36-a741-3cb60712902b', '春盡日', '春尽日', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["樹頭初日照西檐，樹底蔫花夜雨霑。","外院池亭聞動鎖，後堂闌檻見垂簾。","柳腰入戶風斜倚，榆莢堆牆水半淹。","把酒送春惆悵在，年年三月病厭厭。"]', '["樹头初日照西檐，樹底蔫花夜雨霑。","外院池亭闻动鎖，後堂闌檻见垂簾。","柳腰入戶风斜倚，榆莢堆牆水半淹。","把酒送春惆悵在，年年三月病厭厭。"]', '诗', 'shi', '', NULL, '春盡日 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a57acaf-59f9-403f-a6c8-7039461a139b', '詠燈', '詠灯', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["高在酒樓明錦幕，遠隨漁艇泊煙江。","古來幽怨皆銷骨，休向長門背雨窗。"]', '["高在酒楼明錦幕，远隨漁艇泊煙江。","古来幽怨皆銷骨，休向长门背雨窗。"]', '诗', 'shi', '', NULL, '詠燈 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a564a6e-d8aa-49c5-8478-39a7697724c4', '別緒', '別緒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["別緒靜愔愔，牽愁暗入心。","已回花渚櫂，悔聽酒壚琴。","菊露淒羅幕，棃霜惻錦衾。","此生終獨宿，到死誓相尋。","月好知何計，歌闌歎不禁。","山巔更高處，憶上上頭吟。"]', '["別緒静愔愔，牽愁暗入心。","已回花渚櫂，悔听酒壚琴。","菊露淒羅幕，棃霜惻錦衾。","此生終独宿，到死誓相尋。","月好知何計，歌闌歎不禁。","山巔更高处，憶上上头吟。"]', '诗', 'shi', '', NULL, '別緒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9964314-a0ea-4f2c-87a4-aa87f44080fe', '見花', '见花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["褰裳擁鼻正吟詩，日午牆頭獨見時。","血染蜀羅山躑躅，肉紅宮錦海棠棃。","因狂得病真閑事，欲詠無才是所悲。","看却東風歸去也，爭教判得最繁枝。"]', '["褰裳擁鼻正吟诗，日午牆头独见时。","血染蜀羅山躑躅，肉紅宮錦海棠棃。","因狂得病真闲事，欲詠無才是所悲。","看却东风归去也，爭教判得最繁枝。"]', '诗', 'shi', '', NULL, '見花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec668690-153b-4beb-8668-5013b5e28820', '馬上見', '马上见', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["驕馬錦連錢，乘騎是謫仙。","和帬穿玉鐙，隔袖把金鞭。","去帶懵騰醉，歸成困頓眠。","自憐輸廐吏，餘煖在香韉。"]', '["驕马錦連錢，乘騎是謫仙。","和帬穿玉鐙，隔袖把金鞭。","去带懵腾醉，归成困頓眠。","自怜輸廐吏，餘煖在香韉。"]', '诗', 'shi', '', NULL, '馬上見 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d71ed4d1-7e07-4c4f-ba21-a1075caeb95d', '繞廊', '繞廊', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["濃煙隔簾香漏泄，斜燈映竹光參差。","繞廊倚柱堪惆悵，細雨輕寒花落時。"]', '["濃煙隔簾香漏泄，斜灯映竹光參差。","繞廊倚柱堪惆悵，細雨轻寒花落时。"]', '诗', 'shi', '', NULL, '繞廊 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55663383-5899-4e2d-9ce2-eaefb0c48874', '屐子', '屐子', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["方寸膚圓光緻緻，白羅繡屧紅托裏。","南朝天子欠風流，却重金蓮輕綠齒。"]', '["方寸膚圓光緻緻，白羅繡屧紅托裏。","南朝天子欠风流，却重金蓮轻綠齒。"]', '诗', 'shi', '', NULL, '屐子 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('081fcc0d-3551-4ec2-939d-943b5fcf698f', '青春', '青春', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["眼意心期卒未休，暗中終擬約秦樓。","光陰負我難相遇，情緒牽人不自由。","遙夜定嫌香蔽膝，悶時應弄玉搔頭。","櫻桃花謝棃花發，腸斷青春兩處愁。"]', '["眼意心期卒未休，暗中終擬約秦楼。","光陰負我难相遇，情緒牽人不自由。","遙夜定嫌香蔽膝，悶时應弄玉搔头。","櫻桃花謝棃花發，腸斷青春兩处愁。"]', '诗', 'shi', '', NULL, '青春 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de845f8f-03ae-49f8-8007-716b8ef5ba5d', '聞雨', '闻雨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["香侵蔽膝夜寒輕，聞雨傷春夢不成。","羅帳四垂紅燭背，玉釵敲著枕函聲。"]', '["香侵蔽膝夜寒轻，闻雨傷春梦不成。","羅帳四垂紅燭背，玉釵敲著枕函声。"]', '诗', 'shi', '', NULL, '聞雨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c08fb29-5cab-4eb5-93d2-d62677c066ed', '嬾起', '嬾起', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["百舌喚朝眠，春心動幾般。","枕痕霞黯澹，淚粉玉闌珊。","籠繡香煙歇，屏山燭燄殘。","煖嫌羅韤窄，瘦覺錦衣寬。","昨夜三更雨，今朝一陣寒。","海棠花在否，側臥卷簾看。"]', '["百舌喚朝眠，春心动幾般。","枕痕霞黯澹，泪粉玉闌珊。","籠繡香煙歇，屏山燭燄殘。","煖嫌羅韤窄，瘦覺錦衣寬。","昨夜三更雨，今朝一陣寒。","海棠花在否，側臥卷簾看。"]', '诗', 'shi', '', NULL, '嬾起 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1deac6d5-6da0-4d9f-a182-2f0697cbb932', '已涼', '已涼', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["碧闌干外繡簾垂，猩血屏風畫折枝。","八尺龍鬚方錦褥，已涼天氣未寒時。"]', '["碧闌干外繡簾垂，猩血屏风畫折枝。","八尺龙鬚方錦褥，已涼天氣未寒时。"]', '诗', 'shi', '', NULL, '已涼 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('600b055c-cffb-48d7-bf63-36d4b8ef6071', '欲去', '欲去', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["紛紜隔窗語，重約蹋青期。","總得相逢處，無非欲去時。","恨深書不盡，寵極意多疑。","惆悵桃源路，惟教夢寐知。"]', '["紛紜隔窗語，重約蹋青期。","總得相逢处，無非欲去时。","恨深书不尽，寵極意多疑。","惆悵桃源路，惟教梦寐知。"]', '诗', 'shi', '', NULL, '欲去 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f84d62-65f3-47ed-b2a7-2454f354276b', '橫塘', '橫塘', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["秋寒灑背入簾霜，鳳脛燈清照洞房。","蜀紙麝煤沾筆興，越甌犀液發茶香。","風飄亂點更籌轉，拍送繁弦曲破長。","散客出門斜月在，兩眉愁思問橫塘。"]', '["秋寒灑背入簾霜，鳳脛灯清照洞房。","蜀紙麝煤沾笔兴，越甌犀液發茶香。","风飄亂点更籌轉，拍送繁弦曲破长。","散客出门斜月在，兩眉愁思问橫塘。"]', '诗', 'shi', '', NULL, '橫塘 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b2b69e-ed01-4a03-9cd8-b9ecbb2bc2b9', '五更', '五更', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["往年曾約鬱金牀，半夜潛身入洞房。","懷裏不知金鈿落，暗中唯覺繡鞵香。","此時欲別魂俱斷，自後相逢眼更狂。","光景旋消惆悵在，一生贏得是淒涼。"]', '["往年曾約鬱金牀，半夜潛身入洞房。","懷裏不知金鈿落，暗中唯覺繡鞵香。","此时欲別魂俱斷，自後相逢眼更狂。","光景旋消惆悵在，一生贏得是淒涼。"]', '诗', 'shi', '', NULL, '五更 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27aaf29-a365-46ae-93dd-3e855dedc02e', '聯綴體', '聯綴體', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["院宇秋明日日長，社前一雁到遼陽。","隴頭鍼線年年事，不喜寒碪擣斷腸。"]', '["院宇秋明日日长，社前一雁到遼陽。","隴头鍼線年年事，不喜寒碪擣斷腸。"]', '诗', 'shi', '', NULL, '聯綴體 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a37da24-6ff6-491a-bd2c-ead3df126e94', '半睡', '半睡', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["擡鏡仍嫌重，更衣又怕寒。","宵分未歸帳，半睡待郎看。"]', '["擡镜仍嫌重，更衣又怕寒。","宵分未归帳，半睡待郎看。"]', '诗', 'shi', '', NULL, '半睡 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0589a3e-6f1a-447d-9792-994c4af9398b', '寒食夜', '寒食夜', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["清江碧草兩悠悠，各自風流一種愁。","正是落花寒食夜，夜深無伴倚南樓。"]', '["清江碧草兩悠悠，各自风流一種愁。","正是落花寒食夜，夜深無伴倚南楼。"]', '诗', 'shi', '', NULL, '寒食夜 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4462bb65-2600-4ffe-bca1-6f11899de712', '哭花', '哭花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["曾愁香結破顏遲，今見妖紅委地時。","若是有情爭不哭，夜來風雨葬西施。"]', '["曾愁香結破顏遲，今见妖紅委地时。","若是有情爭不哭，夜来风雨葬西施。"]', '诗', 'shi', '', NULL, '哭花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2165cce4-3a7d-484a-9bd4-ec6e8ee925d9', '重遊曲江', '重游曲江', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鞭梢亂拂暗傷情，蹤跡難尋露草青。","猶是玉輪曾輾處，一泓秋水漲浮萍。"]', '["鞭梢亂拂暗傷情，蹤跡难尋露草青。","猶是玉輪曾輾处，一泓秋水漲浮萍。"]', '诗', 'shi', '', NULL, '重遊曲江 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b0b440-9222-441c-a22a-969c6c5f89a8', '遙見', '遙见', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["悲歌淚溼澹胭脂，閑立風吹金縷衣。","白玉堂東遙見後，令人斗薄畫楊妃。"]', '["悲歌泪溼澹胭脂，闲立风吹金縷衣。","白玉堂东遙见後，令人斗薄畫楊妃。"]', '诗', 'shi', '', NULL, '遙見 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b89ddfab-befa-4387-b120-9aea264180ec', '新秋', '新秋', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一夜清風動扇愁，背時容色入新秋。","桃花臉裏汪汪淚，忍到更深枕上流。"]', '["一夜清风动扇愁，背时容色入新秋。","桃花臉裏汪汪泪，忍到更深枕上流。"]', '诗', 'shi', '', NULL, '新秋 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12bb090c-7e30-4acb-bd88-276e8d45a049', '宮詞', '宮词', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["繡帬斜立正銷魂，侍女移燈掩殿門。","燕子不來花著雨，春風應自怨黃昏。"]', '["繡帬斜立正銷魂，侍女移灯掩殿门。","燕子不来花著雨，春风應自怨黄昏。"]', '诗', 'shi', '', NULL, '宮詞 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e57b71-e2fc-4559-adcc-3db1fc5b7640', '蹋青', '蹋青', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["蹋青會散欲歸時，金車久立頻催上。","收帬整髻故遲遲，兩點深心各惆悵。"]', '["蹋青會散欲归时，金车久立頻催上。","收帬整髻故遲遲，兩点深心各惆悵。"]', '诗', 'shi', '', NULL, '蹋青 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36563b54-2b56-4ffa-8e64-5d65e9ce715e', '夜深', '夜深', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["惻惻輕寒翦翦風，小梅飄雪杏花紅。","夜深斜搭鞦韆索，樓閣朦朧煙雨中。"]', '["惻惻轻寒翦翦风，小梅飄雪杏花紅。","夜深斜搭鞦韆索，楼閣朦朧煙雨中。"]', '诗', 'shi', '', NULL, '夜深 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0606d2ab-617e-4b59-880c-0e11b2ebed03', '夏日', '夏日', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["庭樹新陰葉未成，玉階人靜一蟬聲。","相風不動烏龍睡，時有嬌鶯自喚名。"]', '["庭樹新陰葉未成，玉階人静一蟬声。","相风不动烏龙睡，时有嬌鶯自喚名。"]', '诗', 'shi', '', NULL, '夏日 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e232d5c-325f-4119-a85b-9f6fcd1da1a5', '新上頭', '新上头', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["學梳鬆鬢試新帬，消息佳期在此春。","爲要好多心轉惑，徧將宜稱問傍人。"]', '["学梳鬆鬢試新帬，消息佳期在此春。","爲要好多心轉惑，徧將宜稱问傍人。"]', '诗', 'shi', '', NULL, '新上頭 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f33651-e5e9-4edd-bb59-25aad8fcdc16', '中庭', '中庭', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["夜短睡遲慵早起，日高方始出紗窗。","中庭自摘青梅子，先向釵頭戴一雙。"]', '["夜短睡遲慵早起，日高方始出紗窗。","中庭自摘青梅子，先向釵头戴一雙。"]', '诗', 'shi', '', NULL, '中庭 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0fa306-1791-4d0e-935a-2338705f4adf', '詠浴', '詠浴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["再整魚犀攏翠簪，解衣先覺冷森森。","教移蘭燭頻羞影，自試香湯更怕深。","初似洗花難抑按，終憂沃雪不勝任。","豈知侍女簾帷外，賸取君王幾餅金。"]', '["再整鱼犀攏翠簪，解衣先覺冷森森。","教移蘭燭頻羞影，自試香湯更怕深。","初似洗花难抑按，終憂沃雪不勝任。","豈知侍女簾帷外，賸取君王幾餅金。"]', '诗', 'shi', '', NULL, '詠浴 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05ebac5-df81-4347-8a06-0cbf6e773c24', '席上有贈', '席上有贈', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["矜嚴標格絕嫌猜，嗔怒雖逢笑靨開。","小雁斜侵眉柳去，媚霞橫接眼波來。","鬢垂香頸雲遮藕，粉著蘭胷雪壓梅。","莫道風流無宋玉，好將心力事妝臺。"]', '["矜嚴標格絕嫌猜，嗔怒雖逢笑靨开。","小雁斜侵眉柳去，媚霞橫接眼波来。","鬢垂香頸云遮藕，粉著蘭胷雪壓梅。","莫道风流無宋玉，好將心力事妝台。"]', '诗', 'shi', '', NULL, '席上有贈 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('539d9067-ddd4-42a0-a236-dd768b39a3fb', '早歸', '早归', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["去是黃昏後，歸當朧{月悤}時。","扠衣吟宿醉，風露動相思。"]', '["去是黄昏後，归當朧{月悤}时。","扠衣吟宿醉，风露动相思。"]', '诗', 'shi', '', NULL, '早歸 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae28e94c-11f4-4147-833e-7978d1e8993c', '玉合', '玉合', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["羅囊繡兩鳳皇，玉合雕雙鸂鶒。","中有蘭膏漬紅豆，每回拈著長相憶。","長相憶，經幾春。","人悵望，香氤氳。","開緘不見新書迹，帶粉猶殘舊淚痕。"]', '["羅囊繡兩鳳皇，玉合雕雙鸂鶒。","中有蘭膏漬紅豆，每回拈著长相憶。","长相憶，經幾春。","人悵望，香氤氳。","开緘不见新书迹，带粉猶殘旧泪痕。"]', '诗', 'shi', '', NULL, '玉合 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c598957-e484-4b95-aa04-06def69cce7b', '金陵', '金陵', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["風雨蕭蕭，石頭城下木蘭橈。","煙月迢迢，金陵渡口去來潮。","自古風流皆暗銷，才魂妖魂誰與招。","彩牋麗句今已矣，羅韈金蓮何寂寥。"]', '["风雨蕭蕭，石头城下木蘭橈。","煙月迢迢，金陵渡口去来潮。","自古风流皆暗銷，才魂妖魂誰與招。","彩牋丽句今已矣，羅韈金蓮何寂寥。"]', '诗', 'shi', '', NULL, '金陵 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8f64e35-bd8d-4fa9-b362-b1ff9532d952', '嬾卸頭', '嬾卸头', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["侍女動妝籢，故故驚人睡。","那知本未眠，背面偷垂淚。","嬾卸鳳皇釵，羞入鴛鴦被。","時復見殘燈，和煙墜金穗。"]', '["侍女动妝籢，故故驚人睡。","那知本未眠，背面偷垂泪。","嬾卸鳳皇釵，羞入鴛鴦被。","时复见殘灯，和煙墜金穗。"]', '诗', 'shi', '', NULL, '嬾卸頭 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86fd59f2-c97f-4cac-a057-2e0b5681c1f8', '倚醉', '倚醉', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["倚醉無端尋舊約，却憐惆悵轉難勝。","靜中樓閣深春雨，遠處簾櫳半夜燈。","抱柱立時風細細，繞廊行處思騰騰。","分明窗下聞裁翦，敲徧闌干喚不譍。"]', '["倚醉無端尋旧約，却怜惆悵轉难勝。","静中楼閣深春雨，远处簾櫳半夜灯。","抱柱立时风細細，繞廊行处思腾腾。","分明窗下闻裁翦，敲徧闌干喚不譍。"]', '诗', 'shi', '', NULL, '倚醉 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f005b5d4-37c5-4509-a474-4f33a06caca0', '詠手', '詠手', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["腕白膚紅玉筍芽，調琴抽線露尖斜。","背人細撚垂臙鬢，向鏡輕勻襯臉霞。","悵望昔逢褰繡幔，依稀曾見托金車。","後園笑向同行道，摘得蘼蕪又折花。"]', '["腕白膚紅玉筍芽，調琴抽線露尖斜。","背人細撚垂臙鬢，向镜轻勻襯臉霞。","悵望昔逢褰繡幔，依稀曾见托金车。","後园笑向同行道，摘得蘼蕪又折花。"]', '诗', 'shi', '', NULL, '詠手 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbb41e14-8b16-4286-93c4-cf0feb0cf7d1', '荷花', '荷花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["紈扇相敧綠，香囊獨立紅。","浸淫因重露，狂暴是秋風。","逸調無人唱，秋塘每夜空。","何繇見周昉，移入畫屏中。"]', '["紈扇相敧綠，香囊独立紅。","浸淫因重露，狂暴是秋风。","逸調無人唱，秋塘每夜空。","何繇见周昉，移入畫屏中。"]', '诗', 'shi', '', NULL, '荷花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5e38966-817e-4666-90c5-636d400dcbb6', '鬆髻', '鬆髻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["髻根鬆慢玉釵垂，指點花枝又過時。","坐久暗生惆悵事，背人勻却淚臙脂。"]', '["髻根鬆慢玉釵垂，指点花枝又過时。","坐久暗生惆悵事，背人勻却泪臙脂。"]', '诗', 'shi', '', NULL, '鬆髻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4a9f6cf-afe7-4bd4-a36f-0cef0ee09c79', '寄遠', '寄远', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["眉如半月雲如鬟，梧桐葉落敲井闌。","孤燈亭亭公署寒，微霜淒淒客衣單。","想美人兮雲一端，夢魂悠悠關山難。","空房展轉懷悲酸，銅壺漏盡聞金鸞。"]', '["眉如半月云如鬟，梧桐葉落敲井闌。","孤灯亭亭公署寒，微霜淒淒客衣單。","想美人兮云一端，梦魂悠悠关山难。","空房展轉懷悲酸，銅壺漏尽闻金鸾。"]', '诗', 'shi', '', NULL, '寄遠 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d188e5a-252b-4ee2-9312-963c738f36d4', '蹤跡', '蹤跡', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["東烏西兔似車輪，劫火桑田不復論。","唯有風光與蹤跡，思量長是暗銷魂。"]', '["东烏西兔似车輪，劫火桑田不复論。","唯有风光與蹤跡，思量长是暗銷魂。"]', '诗', 'shi', '', NULL, '蹤跡 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0bda067-2b0f-4350-91b5-263fef49d679', '病憶', '病憶', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["信知尤物必牽情，一顧難酬覺命輕。","曾把禪機銷此病，破除纔盡又重生。"]', '["信知尤物必牽情，一顧难酬覺命轻。","曾把禪機銷此病，破除纔尽又重生。"]', '诗', 'shi', '', NULL, '病憶 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d36430f-6c79-46c4-a32f-356e82cc17d7', '妬媒', '妬媒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["洞房深閉不曾開，橫臥烏龍作妬媒。","好鳥豈勞兼比翼，異華何必更重臺。","難留旋逐驚飆去，暫見如隨急電來。","多爲過防成後悔，偶因翻語得深猜。","已嫌刻蠟春宵短，最恨鳴珂曉鼓催。","應笑楚囊仙分薄，日中長是獨裴回。"]', '["洞房深閉不曾开，橫臥烏龙作妬媒。","好鸟豈勞兼比翼，異华何必更重台。","难留旋逐驚飆去，暫见如隨急電来。","多爲過防成後悔，偶因翻語得深猜。","已嫌刻蠟春宵短，最恨鳴珂晓鼓催。","應笑楚囊仙分薄，日中长是独裴回。"]', '诗', 'shi', '', NULL, '妬媒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3275afa6-909d-4ff3-8013-95deb60e6370', '不見', '不见', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["動靜防閑又怕疑，佯佯脈脈是深機。","此身願作君家燕，秋社歸時也不歸。"]', '["动静防闲又怕疑，佯佯脈脈是深機。","此身願作君家燕，秋社归时也不归。"]', '诗', 'shi', '', NULL, '不見 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d425875b-b6a9-4e2a-922d-212a0ab2b181', '晝寢', '晝寢', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["碧桐陰盡隔簾櫳，扇拂金鵝玉簟烘。","撲粉更添香體滑，解衣唯見下裳紅。","煩襟乍觸冰壺冷，倦枕徐敧寶髻鬆。","何必苦勞魂與夢，王昌只在此牆東。"]', '["碧桐陰尽隔簾櫳，扇拂金鵝玉簟烘。","撲粉更添香體滑，解衣唯见下裳紅。","煩襟乍觸冰壺冷，倦枕徐敧寶髻鬆。","何必苦勞魂與梦，王昌只在此牆东。"]', '诗', 'shi', '', NULL, '晝寢 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039e9918-e8b2-4172-95f1-2feab66a64c8', '意緒', '意緒', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["絕代佳人何寂寞，棃花未發梅花落。","東風吹雨入西園，銀綫千條度虛閣。","臉粉難勻蜀酒濃，口脂易印吳綾薄。","嬌饒意態不勝羞，願倚郎肩永相著。"]', '["絕代佳人何寂寞，棃花未發梅花落。","东风吹雨入西园，銀綫千條度虛閣。","臉粉难勻蜀酒濃，口脂易印吳綾薄。","嬌饒意態不勝羞，願倚郎肩永相著。"]', '诗', 'shi', '', NULL, '意緒 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d861b947-eb7a-4782-8202-7b52616fa213', '惆悵', '惆悵', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["身情長在暗相隨，生魄隨君君豈知。","被頭不煖空霑淚，釵股欲分猶半疑。","朗月清風難愜意，詞人絕色多傷離。","何如飲酒連千醉，席地幕天無所知。"]', '["身情长在暗相隨，生魄隨君君豈知。","被头不煖空霑泪，釵股欲分猶半疑。","朗月清风难愜意，词人絕色多傷離。","何如饮酒連千醉，席地幕天無所知。"]', '诗', 'shi', '', NULL, '惆悵 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d136e35-ed32-44ae-85a3-7ef902fa66de', '忍笑', '忍笑', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["宮樣衣裳淺畫眉，晚來梳洗更相宜。","水精鸚鵡釵頭顫，舉袂佯羞忍笑時。"]', '["宮樣衣裳淺畫眉，晚来梳洗更相宜。","水精鸚鵡釵头顫，舉袂佯羞忍笑时。"]', '诗', 'shi', '', NULL, '忍笑 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c82d653f-2323-4d90-9685-c55a15ee3df6', '詠柳', '詠柳', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["褭雨拖風不自持，全身無力向人垂。","玉纖折得遙相贈，便似觀音手裏時。"]', '["褭雨拖风不自持，全身無力向人垂。","玉纖折得遙相贈，便似观音手裏时。"]', '诗', 'shi', '', NULL, '詠柳 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1c63db-d120-4679-acd0-ac49def44b62', '密意', '密意', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["呵花貼鬢黏寒髮，凝酥光透猩猩血。","經過洛水幾多人，唯有陳王見羅韈。"]', '["呵花貼鬢黏寒髮，凝酥光透猩猩血。","經過洛水幾多人，唯有陳王见羅韈。"]', '诗', 'shi', '', NULL, '密意 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24adc1f8-2221-45ff-a8b8-c760bcb0c17f', '偶見', '偶见', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["鞦韆打困解羅帬，指點醍醐索一尊。","見客入來和笑走，手搓梅子映中門。"]', '["鞦韆打困解羅帬，指点醍醐索一尊。","见客入来和笑走，手搓梅子映中门。"]', '诗', 'shi', '', NULL, '偶見 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9442cf34-ce1b-47c7-8779-dccb11de4373', '寒食夜有寄', '寒食夜有寄', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["風流大抵是倀倀，此際相思必斷腸。","雲薄月昏寒食夜，隔簾微雨杏花香。"]', '["风流大抵是倀倀，此際相思必斷腸。","云薄月昏寒食夜，隔簾微雨杏花香。"]', '诗', 'shi', '', NULL, '寒食夜有寄 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ebd1227-9a94-4f30-bc83-8aa364549f2c', '寒食夜有寄', '寒食夜有寄', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["風流大抵是倀倀，一度相思一斷腸。","雲薄月昏寒食夜，隔簾微雨杏花香。"]', '["风流大抵是倀倀，一度相思一斷腸。","云薄月昏寒食夜，隔簾微雨杏花香。"]', '诗', 'shi', '', NULL, '寒食夜有寄 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78b2a65-7582-4a33-aeca-030091c8c3a8', '效崔國輔體四首 一', '效崔国輔體四首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["澹月照中庭，海棠花自落。","獨立俯閑階，風動鞦韆索。"]', '["澹月照中庭，海棠花自落。","独立俯闲階，风动鞦韆索。"]', '诗', 'shi', '', NULL, '效崔國輔體四首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abb8de6b-83f2-4e33-8c2f-2e2c9b2bc601', '效崔國輔體四首 二', '效崔国輔體四首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["雨後碧苔院，霜來紅葉樓。","閑階上斜日，鸚鵡伴人愁。"]', '["雨後碧苔院，霜来紅葉楼。","闲階上斜日，鸚鵡伴人愁。"]', '诗', 'shi', '', NULL, '效崔國輔體四首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5e10aeb-d2ff-445c-ade1-96d5483b03a5', '效崔國輔體四首 三', '效崔国輔體四首 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["酒力滋睡眸，鹵莽聞街鼓。","欲明天更寒，東風打窗雨。"]', '["酒力滋睡眸，鹵莽闻街鼓。","欲明天更寒，东风打窗雨。"]', '诗', 'shi', '', NULL, '效崔國輔體四首 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f24a1d-1aa5-483e-a4e6-29e56869c13b', '效崔國輔體四首 四', '效崔国輔體四首 四', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["羅幕生春寒，繡窗愁未眠。","南湖一夜雨，應溼采蓮船。"]', '["羅幕生春寒，繡窗愁未眠。","南湖一夜雨，應溼采蓮船。"]', '诗', 'shi', '', NULL, '效崔國輔體四首 四 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec27cbe-ddaf-4788-979e-09a358c922d3', '後魏時相州人作李波小妹歌疑其未備因補之', '後魏时相州人作李波小妹歌疑其未備因補之', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["李波小妹字雍容，窄衣短袖蠻錦紅。","未解有情夢梁殿，何曾自媚妒吳宮。","難教牽引知酒味，因令悵望成春慵。","海棠花下鞦韆畔，背人撩鬢道怱怱。"]', '["李波小妹字雍容，窄衣短袖蠻錦紅。","未解有情梦梁殿，何曾自媚妒吳宮。","难教牽引知酒味，因令悵望成春慵。","海棠花下鞦韆畔，背人撩鬢道怱怱。"]', '诗', 'shi', '', NULL, '後魏時相州人作李波小妹歌疑其未備因補之 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc92492-14f6-4380-b450-205ce7361af1', '春晝', '春晝', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["春融豔豔，大醉陶陶。","漏添遲日，箭減良宵。","藤垂戟戶，柳拂河橋。","簾幕燕子，池塘[伯]勞。","膚清臂瘦，衫薄香銷。","楚殿衣窄，南朝髻高。","河陽縣遠，清波地遙。","絲纏露泣，各自無憀。"]', '["春融豔豔，大醉陶陶。","漏添遲日，箭減良宵。","藤垂戟戶，柳拂河橋。","簾幕燕子，池塘[伯]勞。","膚清臂瘦，衫薄香銷。","楚殿衣窄，南朝髻高。","河陽縣远，清波地遙。","絲纏露泣，各自無憀。"]', '诗', 'shi', '', NULL, '春晝 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a22f497-6057-4278-9bed-6d1e2a1d625b', '三憶 一', '三憶 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["憶眠時，春夢困騰騰。","展轉不能起，玉釵垂枕稜。"]', '["憶眠时，春梦困腾腾。","展轉不能起，玉釵垂枕稜。"]', '诗', 'shi', '', NULL, '三憶 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc59edb-ddc2-483d-a3aa-75fd9550c807', '三憶 二', '三憶 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["憶行時，背手挼金雀。","斂笑慢回頭，步轉闌干角。"]', '["憶行时，背手挼金雀。","斂笑慢回头，步轉闌干角。"]', '诗', 'shi', '', NULL, '三憶 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78591d34-88de-41de-a9ec-a27bd0524dfe', '三憶 三', '三憶 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["憶去時，向月遲遲行。","強語戲同伴，圖郎聞笑聲。"]', '["憶去时，向月遲遲行。","強語戲同伴，圖郎闻笑声。"]', '诗', 'shi', '', NULL, '三憶 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd41af99-b592-4d19-9526-9b98759f3dfd', '六言三首 一', '六言三首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["春樓處子傾城，金陵狎客多情。","朝雲暮雨會合，羅韤繡被逢迎。","華山梧桐相覆，蠻江荳蔻連生。","幽歡不盡告別，秋河悵望平明。"]', '["春楼处子傾城，金陵狎客多情。","朝云暮雨會合，羅韤繡被逢迎。","华山梧桐相覆，蠻江荳蔻連生。","幽歡不尽告別，秋河悵望平明。"]', '诗', 'shi', '', NULL, '六言三首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe6db001-85fa-4642-b150-7d0ee66cc9e5', '六言三首 二', '六言三首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一燈前雨落夜，三月盡草青時。","半寒半暖正好，花開花謝相思。","惆悵空教夢見，懊惱多成酒悲。","紅袖不乾誰會，揉損聯娟澹眉。"]', '["一灯前雨落夜，三月尽草青时。","半寒半暖正好，花开花謝相思。","惆悵空教梦见，懊惱多成酒悲。","紅袖不乾誰會，揉損聯娟澹眉。"]', '诗', 'shi', '', NULL, '六言三首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7595c3-a611-4ed9-8ba9-576380e239b6', '六言三首 三', '六言三首 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["此間青草更遠，不唯空繞汀洲。","那裏朝日才出，還應先照西樓。","憶淚因成恨淚，夢遊常續心遊。","桃源洞口來否，絳節霓旌久留。"]', '["此间青草更远，不唯空繞汀洲。","那裏朝日才出，還應先照西楼。","憶泪因成恨泪，梦游常續心游。","桃源洞口来否，絳節霓旌久留。"]', '诗', 'shi', '', NULL, '六言三首 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d17588cc-0e34-4bfc-8c20-a16a939b31b4', '寒食日重遊李氏園亭有懷', '寒食日重游李氏园亭有懷', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["往年同在鸞橋上，見倚朱闌詠柳緜。","今日獨來香徑裏，更無人跡有苔錢。","傷心闊別三千里，屈指思量四五年。","料得他鄉遇佳節，亦應懷抱暗淒然。"]', '["往年同在鸾橋上，见倚朱闌詠柳緜。","今日独来香徑裏，更無人跡有苔錢。","傷心闊別三千里，屈指思量四五年。","料得他乡遇佳節，亦應懷抱暗淒然。"]', '诗', 'shi', '', NULL, '寒食日重遊李氏園亭有懷 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cbaa67b-97f3-473e-8438-9976693e1dcc', '思錄舊詩於卷上淒然有感因成一章', '思錄旧诗於卷上淒然有感因成一章', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["緝綴小詩鈔卷裏，尋思閑事到心頭。","自吟自泣無人會，腸斷蓬山第一流。"]', '["緝綴小诗鈔卷裏，尋思闲事到心头。","自吟自泣無人會，腸斷蓬山第一流。"]', '诗', 'shi', '', NULL, '思錄舊詩於卷上淒然有感因成一章 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac439702-7c98-48c0-a087-8b2f8674e025', '春閨二首 一', '春閨二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["願結交加夢，因傾瀲灩尊。","醒來情緒惡，簾外正黃昏。"]', '["願結交加梦，因傾瀲灩尊。","醒来情緒惡，簾外正黄昏。"]', '诗', 'shi', '', NULL, '春閨二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c161fe9-2cd6-4b7e-94b2-4b38d878c8ac', '春閨二首 二', '春閨二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["氤氳帳裏香，薄薄睡時妝。","長吁解羅帶，怯見上空牀。"]', '["氤氳帳裏香，薄薄睡时妝。","长吁解羅带，怯见上空牀。"]', '诗', 'shi', '', NULL, '春閨二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f267a052-49bf-4ba5-8357-92f6bceb82c0', '代小玉家爲蕃騎所虜後寄故集賢裴公相國', '代小玉家爲蕃騎所虜後寄故集賢裴公相国', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["動天金鼓逼神州，惜別無心學墜樓。","不得回眸辭傅粉，便須含淚對殘秋。","折釵伴妾埋青冢，半鏡隨郎葬杜郵。","唯有此宵魂夢裏，殷勤見覓鳳池頭。"]', '["动天金鼓逼神州，惜別無心学墜楼。","不得回眸辞傅粉，便須含泪对殘秋。","折釵伴妾埋青冢，半镜隨郎葬杜郵。","唯有此宵魂梦裏，殷勤见覓鳳池头。"]', '诗', 'shi', '', NULL, '代小玉家爲蕃騎所虜後寄故集賢裴公相國 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695d97de-86e8-48be-8e43-3b4fbace1630', '薦福寺講筵偶見又別', '薦福寺講筵偶见又別', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["見時濃日午，別處暮鐘殘。","景色疑春盡，襟懷似酒闌。","兩情含眷戀，一餉致辛酸。","夜靜長廊下，難尋屐齒看。"]', '["见时濃日午，別处暮鐘殘。","景色疑春尽，襟懷似酒闌。","兩情含眷戀，一餉致辛酸。","夜静长廊下，难尋屐齒看。"]', '诗', 'shi', '', NULL, '薦福寺講筵偶見又別 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3168a5c2-50fd-46d1-808f-d911988d0807', '復偶見三絕 一', '复偶见三絕 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["霧爲襟袖玉爲冠，半似羞人半忍寒。","別易會難長自歎，轉身應把淚珠彈。"]', '["霧爲襟袖玉爲冠，半似羞人半忍寒。","別易會难长自歎，轉身應把泪珠彈。"]', '诗', 'shi', '', NULL, '復偶見三絕 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a204f0e-638b-40ca-8cc0-3ea291f7867b', '復偶見三絕 二', '复偶见三絕 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["桃花臉薄難藏淚，柳葉眉長易覺愁。","密跡未成當面笑，幾迴擡眼又低頭。"]', '["桃花臉薄难藏泪，柳葉眉长易覺愁。","密跡未成當面笑，幾迴擡眼又低头。"]', '诗', 'shi', '', NULL, '復偶見三絕 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4acbcf98-a9a7-4137-8f1f-3ec2a7beb87e', '復偶見三絕 三', '复偶见三絕 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["半身映竹輕聞語，一手揭簾微轉頭。","此意別人應未覺，不勝情緒兩風流。"]', '["半身映竹轻闻語，一手揭簾微轉头。","此意別人應未覺，不勝情緒兩风流。"]', '诗', 'shi', '', NULL, '復偶見三絕 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4ef9fc-781f-453d-9000-933feada38f7', '厭花落', '厭花落', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["厭花落，人寂寞。","果樹陰成燕翅齊，西園永日閑高閣。","後堂夾簾愁不卷，低頭悶把衣襟撚。","忽然事到心中來，四肢嬌入茸茸眼。","也曾同在華堂宴，佯佯攏鬢偷迴面。","半醉狂心忍不禁，分明一任傍人見。","書中說却平生事，猶疑未滿情郎意。","錦囊封了又重開，夜深窗下燒紅紙。","紅紙千張言不盡，至誠無語傳心印。","但得鴛鴦枕臂眠，也任時光都一瞬。"]', '["厭花落，人寂寞。","果樹陰成燕翅齊，西园永日闲高閣。","後堂夾簾愁不卷，低头悶把衣襟撚。","忽然事到心中来，四肢嬌入茸茸眼。","也曾同在华堂宴，佯佯攏鬢偷迴面。","半醉狂心忍不禁，分明一任傍人见。","书中说却平生事，猶疑未满情郎意。","錦囊封了又重开，夜深窗下燒紅紙。","紅紙千張言不尽，至誠無語傳心印。","但得鴛鴦枕臂眠，也任时光都一瞬。"]', '诗', 'shi', '', NULL, '厭花落 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acaf1a0e-3669-4c2d-9859-6fd956d40a34', '春悶偶成十二韻', '春悶偶成十二韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["阡陌懸雲壤，闌畦隔艾芝。","路遙行雨嬾，河闊過橋遲。","雁足應難達，狐蹤浪得疑。","謝鯤吟未廢，張碩夢堪思。","有意通情處，無言攏鬢時。","格高歸斂笑，歌怨在顰眉。","醉後金蟬重，歡餘玉燕敧。","素姿凌白柰，圓頰誚紅棃。","粉字題花筆，香牋詠柳詩。","繡窗攜手約，芳草蹋青期。","別淚開泉脈，春愁罥藕絲。","相思不相信，幽恨更誰知。"]', '["阡陌懸云壤，闌畦隔艾芝。","路遙行雨嬾，河闊過橋遲。","雁足應难達，狐蹤浪得疑。","謝鯤吟未廢，張碩梦堪思。","有意通情处，無言攏鬢时。","格高归斂笑，歌怨在顰眉。","醉後金蟬重，歡餘玉燕敧。","素姿凌白柰，圓頰誚紅棃。","粉字題花笔，香牋詠柳诗。","繡窗携手約，芳草蹋青期。","別泪开泉脈，春愁罥藕絲。","相思不相信，幽恨更誰知。"]', '诗', 'shi', '', NULL, '春悶偶成十二韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e070241f-b094-48b6-8d5c-345d58557ae8', '想得', '想得', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["兩重門裏玉堂前，寒食花枝月午天。","想得那人垂手立，嬌羞不肯上鞦韆。"]', '["兩重门裏玉堂前，寒食花枝月午天。","想得那人垂手立，嬌羞不肯上鞦韆。"]', '诗', 'shi', '', NULL, '想得 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4173c8c-49d2-410d-aad3-bdff981c3761', '偶見背面是夕兼夢', '偶见背面是夕兼梦', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["酥凝背胛玉搓肩，輕薄紅綃覆白蓮。","此夜分明來入夢，當時惆悵不成眠。","眼波向我無端豔，心火因君特地然。","莫道人生難際會，秦樓鸞鳳有神仙。"]', '["酥凝背胛玉搓肩，轻薄紅綃覆白蓮。","此夜分明来入梦，當时惆悵不成眠。","眼波向我無端豔，心火因君特地然。","莫道人生难際會，秦楼鸾鳳有神仙。"]', '诗', 'shi', '', NULL, '偶見背面是夕兼夢 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a9e4cc-407e-4a0e-8cfb-1869fce730a8', '五更', '五更', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["秋雨五更頭，桐竹鳴騷屑。","却似殘春間，斷送花時節。","空樓雁一聲，遠屏燈半滅。","繡被擁嬌寒，眉山正愁絕。"]', '["秋雨五更头，桐竹鳴騷屑。","却似殘春间，斷送花时節。","空楼雁一声，远屏灯半滅。","繡被擁嬌寒，眉山正愁絕。"]', '诗', 'shi', '', NULL, '五更 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bbac938-fd13-48f8-9c47-10ba7682a05d', '有憶', '有憶', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["晝漏迢迢夜漏遲，傾城消息杳無期。","愁腸泥酒人千里，淚眼倚樓天四垂。","自笑計狂多獨語，誰憐夢好轉相思。","何時斗帳濃香裏，分付東風與玉兒。"]', '["晝漏迢迢夜漏遲，傾城消息杳無期。","愁腸泥酒人千里，泪眼倚楼天四垂。","自笑計狂多独語，誰怜梦好轉相思。","何时斗帳濃香裏，分付东风與玉兒。"]', '诗', 'shi', '', NULL, '有憶 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949f69b6-e482-4ae9-9c8d-6530878a7532', '半夜', '半夜', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["板閤數尊後，至今猶酒悲。","一宵相見事，半夜獨眠時。","明朝窗下照，應有鬢如絲。"]', '["板閤數尊後，至今猶酒悲。","一宵相见事，半夜独眠时。","明朝窗下照，應有鬢如絲。"]', '诗', 'shi', '', NULL, '半夜 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f36a631-8f9f-41a3-ab1f-216495a297c3', '信筆', '信笔', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["睡髻休頻攏，春眉忍更長。","整釵梔子重，泛酒菊花香。","繡疊昏金色，羅揉損砑光。","有時閑弄筆，亦畫兩鴛鴦。"]', '["睡髻休頻攏，春眉忍更长。","整釵梔子重，泛酒菊花香。","繡叠昏金色，羅揉損砑光。","有时闲弄笔，亦畫兩鴛鴦。"]', '诗', 'shi', '', NULL, '信筆 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f992854-6df6-4949-885d-9b7cbc6261b1', '寄恨', '寄恨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["秦釵枉斷長條玉，蜀紙虛留小字紅。","死恨物情難會處，蓮花不肯嫁春風。"]', '["秦釵枉斷长條玉，蜀紙虛留小字紅。","死恨物情难會处，蓮花不肯嫁春风。"]', '诗', 'shi', '', NULL, '寄恨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ada57845-f348-4b9f-91e8-48d39b24c58a', '兩處', '兩处', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["樓上澹山橫，樓前溝水清。","憐山又憐水，兩處總牽情。"]', '["楼上澹山橫，楼前溝水清。","怜山又怜水，兩处總牽情。"]', '诗', 'shi', '', NULL, '兩處 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101e0115-192c-496d-b282-92d31bfe8b12', '擁鼻', '擁鼻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["擁鼻悲吟一向愁，寒更轉盡未回頭。","綠屏無睡秋分簟，紅葉傷心月午樓。","却要因循添逸興，若爲趨競愴離憂。","殷勤憑仗官渠水，爲到西溪動釣舟。"]', '["擁鼻悲吟一向愁，寒更轉尽未回头。","綠屏無睡秋分簟，紅葉傷心月午楼。","却要因循添逸兴，若爲趨競愴離憂。","殷勤憑仗官渠水，爲到西溪动釣舟。"]', '诗', 'shi', '', NULL, '擁鼻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377deb10-3359-4928-8ac7-8a5880e85af7', '閨怨', '閨怨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["時光潛去暗淒涼，嬾對菱花暈曉妝。","初坼鞦韆人寂寞，後園青草任他長。"]', '["时光潛去暗淒涼，嬾对菱花暈晓妝。","初坼鞦韆人寂寞，後园青草任他长。"]', '诗', 'shi', '', NULL, '閨怨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9703d0c3-0c3c-469d-9595-082674fb8582', '褭娜', '褭娜', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["褭娜腰肢澹薄妝，六朝宮樣窄衣裳。","著詞暫見櫻桃破，飛醆遙聞荳蔻香。","春惱情懷身覺瘦，酒添顏色粉生光。","此時不敢分明道，風月應知暗斷腸。"]', '["褭娜腰肢澹薄妝，六朝宮樣窄衣裳。","著词暫见櫻桃破，飞醆遙闻荳蔻香。","春惱情懷身覺瘦，酒添顏色粉生光。","此时不敢分明道，风月應知暗斷腸。"]', '诗', 'shi', '', NULL, '褭娜 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff2b7e7-15e5-4de6-8f26-9dab2900b1a9', '多情', '多情', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天遣多情不自持，多情兼與病相宜。","蠭偷野蜜初嘗處，鶯啄含桃欲咽時。","酒蕩襟懷微駊騀，春牽情緒更融怡。","水香賸置金盆裏，瓊樹長須浸一枝。"]', '["天遣多情不自持，多情兼與病相宜。","蠭偷野蜜初嘗处，鶯啄含桃欲咽时。","酒蕩襟懷微駊騀，春牽情緒更融怡。","水香賸置金盆裏，瓊樹长須浸一枝。"]', '诗', 'shi', '', NULL, '多情 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('236dbeb0-604a-43a4-a8cb-d5733d7b60fa', '偶見', '偶见', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["千金莫惜旱蓮生，一笑從教下蔡傾。","仙樹有花難問種，御香聞氣不知名。","愁來自覺歌喉咽，瘦去誰憐舞掌輕。","小疊紅箋書恨字，與奴方便寄卿卿。"]', '["千金莫惜旱蓮生，一笑從教下蔡傾。","仙樹有花难问種，御香闻氣不知名。","愁来自覺歌喉咽，瘦去誰怜舞掌轻。","小叠紅箋书恨字，與奴方便寄卿卿。"]', '诗', 'shi', '', NULL, '偶見 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3f1766-c952-4b95-adfc-59b2df129a7c', '箇儂', '箇儂', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["甚感殷勤意，其如阻礙何。","隔簾窺綠齒，映柱送橫波。","老大逢知少，襟懷暗喜多。","因傾一尊酒，聊以慰蹉跎。"]', '["甚感殷勤意，其如阻礙何。","隔簾窺綠齒，映柱送橫波。","老大逢知少，襟懷暗喜多。","因傾一尊酒，聊以慰蹉跎。"]', '诗', 'shi', '', NULL, '箇儂 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b4229ef-dfa0-4d4b-b619-58db1756edc3', '無題 一', '無題 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["小檻移燈灺，空房鎖隙塵。","額波風盡日，簾影月侵晨。","香辣更衣後，釵梁攏鬢新。","吉音聞詭計，醉語近天真。","妝好方長歎，歡餘却淺顰。","繡屏金作屋，絲幰玉爲輪。","致意通緜竹，精誠託錦鱗。","歌凝眉際恨，酒發臉邊春。","溪紵殊傾越，樓簫豈羨秦。","柳虛禳沴氣，梅實引芳津。","樂府降清唱，宮廚減食珍。","防閑襟幷斂，忍妬淚休勻。","宿飲愁縈夢，春寒瘦著人。","手持雙荳蔻，的的爲東鄰。"]', '["小檻移灯灺，空房鎖隙塵。","額波风尽日，簾影月侵晨。","香辣更衣後，釵梁攏鬢新。","吉音闻詭計，醉語近天真。","妝好方长歎，歡餘却淺顰。","繡屏金作屋，絲幰玉爲輪。","致意通緜竹，精誠託錦鱗。","歌凝眉際恨，酒發臉邊春。","溪紵殊傾越，楼簫豈羨秦。","柳虛禳沴氣，梅實引芳津。","乐府降清唱，宮廚減食珍。","防闲襟幷斂，忍妬泪休勻。","宿饮愁縈梦，春寒瘦著人。","手持雙荳蔻，的的爲东鄰。"]', '诗', 'shi', '', NULL, '無題 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c402fa0-548f-41a8-b2c1-3070e34684f6', '無題 二', '無題 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["碧瓦偏光日，紅簾不受塵。","柳昏連綠野，花爛爍清晨。","書密偷看數，情通破體新。","明言終未實，暗祝始應真。","枉道嫌偷藥，推誠鄙效顰。","合成雲五色，宜作日中輪。","照獸金塗爪，釵魚玉鏤鱗。","渺瀰三島浪，平遠一樓春。","墮髻還名壽，修蛾本姓秦。","櫂尋聞犬洞，槎入飲牛津。","麟脯隨重釀，霜華間八珍。","錦囊霞彩爛，羅韤砑光勻。","羞澀佯牽伴，嬌饒欲泥人。","偷兒難捉搦，慎莫共比鄰。"]', '["碧瓦偏光日，紅簾不受塵。","柳昏連綠野，花爛爍清晨。","书密偷看數，情通破體新。","明言終未實，暗祝始應真。","枉道嫌偷藥，推誠鄙效顰。","合成云五色，宜作日中輪。","照獸金塗爪，釵鱼玉鏤鱗。","渺瀰三島浪，平远一楼春。","墮髻還名壽，修蛾本姓秦。","櫂尋闻犬洞，槎入饮牛津。","麟脯隨重釀，霜华间八珍。","錦囊霞彩爛，羅韤砑光勻。","羞澀佯牽伴，嬌饒欲泥人。","偷兒难捉搦，慎莫共比鄰。"]', '诗', 'shi', '', NULL, '無題 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4b5060-7a74-4650-8720-872efc10c7c2', '無題 三', '無題 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["紫蠟融花蔕，紅緜拭鏡塵。","夢狂飜惜夜，妝嬾厭凌晨。","茜袖啼痕數，香牋墨色新。"]', '["紫蠟融花蔕，紅緜拭镜塵。","梦狂飜惜夜，妝嬾厭凌晨。","茜袖啼痕數，香牋墨色新。"]', '诗', 'shi', '', NULL, '無題 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b15810f-cc50-4a01-91e3-eb5f62610d4b', '倒押前韻', '倒押前韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["白下同歸路，烏衣枉作鄰。","珮聲猶隔箔，香氣已迎人。","酒勸杯須滿，書羞字不勻。","歌憐黃竹怨，味實碧桃珍。","翦燭非良策，當關是要津。","東阿初度洛，楊惲舊家秦。","粉化橫波溢，衫輕曉霧春。","鵶黃雙鳳翅，麝月半魚鱗。","別袂飜如浪，迴腸轉似輪。","後期纔注脚，前事又含顰。","縱有才難詠，寧無畫逼真。","天香聞更有，瓊樹見長新。","鬬草常更僕，迷鬮誤達晨。","齅花判不得，檀注惹風塵。"]', '["白下同归路，烏衣枉作鄰。","珮声猶隔箔，香氣已迎人。","酒勸杯須满，书羞字不勻。","歌怜黄竹怨，味實碧桃珍。","翦燭非良策，當关是要津。","东阿初度洛，楊惲旧家秦。","粉化橫波溢，衫轻晓霧春。","鵶黄雙鳳翅，麝月半鱼鱗。","別袂飜如浪，迴腸轉似輪。","後期纔注脚，前事又含顰。","縱有才难詠，寧無畫逼真。","天香闻更有，瓊樹见长新。","鬬草常更僕，迷鬮誤達晨。","齅花判不得，檀注惹风塵。"]', '诗', 'shi', '', NULL, '倒押前韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f8e23c-67cc-468f-98a9-86a5eed3459d', '閨情', '閨情', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["輕風滴礫動簾鉤，宿酒猶酣嬾卸頭。","但覺夜深花有露，不知人靜月當樓。","何郎燭暗誰能詠，韓壽香焦亦任偷。","敲折玉釵歌轉咽，一聲聲作兩眉愁。"]', '["轻风滴礫动簾鉤，宿酒猶酣嬾卸头。","但覺夜深花有露，不知人静月當楼。","何郎燭暗誰能詠，韓壽香焦亦任偷。","敲折玉釵歌轉咽，一声声作兩眉愁。"]', '诗', 'shi', '', NULL, '閨情 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dff6fe7-1993-4b4a-b014-d0d89d468211', '自負', '自負', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["人許風流自負才，偷桃三度到瑤臺。","至今衣領胭脂在，曾被謫仙痛齩來。"]', '["人許风流自負才，偷桃三度到瑤台。","至今衣領胭脂在，曾被謫仙痛齩来。"]', '诗', 'shi', '', NULL, '自負 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b76dae97-2b6c-47da-a501-76cc85c6b578', '天涼', '天涼', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["愁來却訝天涼早，思倦飜嫌夜漏遲。","何處山川孤館裏，向燈彎盡一雙眉。"]', '["愁来却訝天涼早，思倦飜嫌夜漏遲。","何处山川孤館裏，向灯彎尽一雙眉。"]', '诗', 'shi', '', NULL, '天涼 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db700bc-5cef-4497-8fff-f1a63e72c745', '日高', '日高', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["朦朧猶記管弦聲，噤[㾕]餘寒酒半醒。","春暮日高簾半卷，落花和雨滿中庭。"]', '["朦朧猶記管弦声，噤[㾕]餘寒酒半醒。","春暮日高簾半卷，落花和雨满中庭。"]', '诗', 'shi', '', NULL, '日高 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c300f82-c5a0-40f9-bd88-6ea11aa99ffe', '夕陽', '夕陽', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["花前灑淚臨寒食，醉裏回頭問夕陽。","不管相思人老盡，朝朝容易下西牆。"]', '["花前灑泪臨寒食，醉裏回头问夕陽。","不管相思人老尽，朝朝容易下西牆。"]', '诗', 'shi', '', NULL, '夕陽 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efa311b-821f-47c4-8244-0cb5bf5710aa', '舊館', '旧館', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["前歡往恨分明在，酒興詩情大半亡。","還似牆西紫荆樹，殘花摘索映高塘。"]', '["前歡往恨分明在，酒兴诗情大半亡。","還似牆西紫荆樹，殘花摘索映高塘。"]', '诗', 'shi', '', NULL, '舊館 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d20df6b0-f1f4-4373-b3d2-3309406cd35d', '中春憶贈', '中春憶贈', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["年年長是阻佳期，萬種恩情只自知。","春色轉添惆悵事，似君花發兩三枝。"]', '["年年长是阻佳期，万種恩情只自知。","春色轉添惆悵事，似君花發兩三枝。"]', '诗', 'shi', '', NULL, '中春憶贈 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f9711cb-f271-4e07-bd57-1affa5902970', '春恨', '春恨', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["殘夢依依酒力餘，城頭畫角伴啼烏。","平明未卷西樓幕，院靜時聞響轆轤。"]', '["殘梦依依酒力餘，城头畫角伴啼烏。","平明未卷西楼幕，院静时闻响轆轤。"]', '诗', 'shi', '', NULL, '春恨 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f553c6-52f6-45d5-b43e-8fd81a5370ff', '鞦韆', '鞦韆', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["池塘夜歇清明雨，繞院無塵近花塢。","五絲繩繫出牆遲，力盡纔瞵見鄰圃。","下來嬌喘未能調，斜倚朱闌久無語。","無語兼動所思愁，轉眼看天一長吐。"]', '["池塘夜歇清明雨，繞院無塵近花塢。","五絲繩繫出牆遲，力尽纔瞵见鄰圃。","下来嬌喘未能調，斜倚朱闌久無語。","無語兼动所思愁，轉眼看天一长吐。"]', '诗', 'shi', '', NULL, '鞦韆 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da151296-2dd9-4980-b27c-d672c92fe922', '長信宮二首 一', '长信宮二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天上夢魂何杳杳，宮中消息太沈沈。","君恩不似黃金井，一處團圓萬丈深。"]', '["天上梦魂何杳杳，宮中消息太沈沈。","君恩不似黄金井，一处團圓万丈深。"]', '诗', 'shi', '', NULL, '長信宮二首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74c58df-6df8-4399-b5d2-a92b4bb2729d', '長信宮二首 二', '长信宮二首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天上鳳皇休寄夢，人間鸚鵡舊堪悲。","平生心緒無人識，一隻金梭萬丈絲。"]', '["天上鳳皇休寄梦，人间鸚鵡旧堪悲。","平生心緒無人識，一隻金梭万丈絲。"]', '诗', 'shi', '', NULL, '長信宮二首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66b4d94f-7506-4350-a0e9-327f954acffa', '句', '句', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["豈獨鴟夷解歸去，五湖漁艇且餔糟。"]', '["豈独鴟夷解归去，五湖漁艇且餔糟。"]', '诗', 'shi', '', NULL, '句 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d5593d-f7f3-40cc-a401-2c28eb612983', '奉和御製', '奉和御製', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["嶽寺清秋霽，宸遊永日閑。","霓旌森物外，鳳吹落人間。","玉漱穿城水，屏開對闕山。","皆知聖情悅，麗藻灑芳蘭。"]', '["嶽寺清秋霽，宸游永日闲。","霓旌森物外，鳳吹落人间。","玉漱穿城水，屏开对闕山。","皆知聖情悅，丽藻灑芳蘭。"]', '诗', 'shi', '', NULL, '奉和御製 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad10e9c0-e632-4d90-be31-71113f75a3b3', '和集賢相公西溪侍宴觀競渡', '和集賢相公西溪侍宴观競渡', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["片水聳層橋，祥煙靄慶霄。","晝花鋪廣宴，晴電閃飛橈。","浪疊搖仙仗，風微定彩標。","都人同盛觀，不覺在行朝。"]', '["片水聳層橋，祥煙靄慶霄。","晝花鋪廣宴，晴電閃飞橈。","浪叠搖仙仗，风微定彩標。","都人同盛观，不覺在行朝。"]', '诗', 'shi', '', NULL, '和集賢相公西溪侍宴觀競渡 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e31332a-d1cd-4109-9b80-cf5e40c7f4e7', '山居即事四首 一', '山居即事四首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["桂樹秋來風滿枝，碧巖歸日免乖期。","故人盡向蟾宮折，獨我攀條欲寄誰。"]', '["桂樹秋来风满枝，碧巖归日免乖期。","故人尽向蟾宮折，独我攀條欲寄誰。"]', '诗', 'shi', '', NULL, '山居即事四首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('561e0d19-381b-4b91-a283-4dcc5eaccb07', '山居即事四首 二', '山居即事四首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["不傲南窗且採樵，乾松每帶溼雲燒。","庖廚却得長兼味，三秀芝根五朮苗。"]', '["不傲南窗且採樵，乾松每带溼云燒。","庖廚却得长兼味，三秀芝根五朮苗。"]', '诗', 'shi', '', NULL, '山居即事四首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('971034f6-5ef7-4f17-b48a-999f5e3a8a96', '山居即事四首 三', '山居即事四首 三', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["萬事翛然只有棊，小軒高淨簟涼時。","闌珊半局和微醉，花落中庭樹影移。"]', '["万事翛然只有棊，小軒高淨簟涼时。","闌珊半局和微醉，花落中庭樹影移。"]', '诗', 'shi', '', NULL, '山居即事四首 三 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f796c0c-a070-47e4-8aff-edb01d7e9495', '山居即事四首 四', '山居即事四首 四', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["無鄰無里不成村，水曲雲重掩石門。","何用深求避秦客，吾家便是武陵源。"]', '["無鄰無里不成村，水曲云重掩石门。","何用深求避秦客，吾家便是武陵源。"]', '诗', 'shi', '', NULL, '山居即事四首 四 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7933ada7-3c20-4dbe-be3c-b51f791b5c2e', '紅白牡丹', '紅白牡丹', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["不必繁弦不必歌，靜中相對更情多。","殷鮮一半霞分綺，潔澈旁邊月颭波。","看久願成莊叟夢，惜留須倩魯陽戈。","重來應共今來別，風墮香殘襯綠莎。"]', '["不必繁弦不必歌，静中相对更情多。","殷鲜一半霞分綺，潔澈旁邊月颭波。","看久願成莊叟梦，惜留須倩魯陽戈。","重来應共今来別，风墮香殘襯綠莎。"]', '诗', 'shi', '', NULL, '紅白牡丹 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('980c7227-ba31-4795-b27f-f6c61265fe18', '中秋陪熙用學士禁中翫月', '中秋陪熙用学士禁中翫月', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["月圓年十二，秋半每多陰。","此夕無纖靄，同君宿禁林。","未高知海闊，當午見宮深。","衣似繁霜透，身疑積水沈。","遭逢陪侍輦，歸去憶抽簪。","太液池南岸，相期到曉吟。"]', '["月圓年十二，秋半每多陰。","此夕無纖靄，同君宿禁林。","未高知海闊，當午见宮深。","衣似繁霜透，身疑積水沈。","遭逢陪侍輦，归去憶抽簪。","太液池南岸，相期到晓吟。"]', '诗', 'shi', '', NULL, '中秋陪熙用學士禁中翫月 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad7a0d5-22ed-4333-813b-22843bd3d9b1', '題豪家故池', '題豪家故池', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["歲久無泉引，春來仰雨流。","萍枯黏朽檻，沙淺露沈舟。","照影人何在，持竿客寄遊。","翛然興廢外，回首謝眠鷗。"]', '["歲久無泉引，春来仰雨流。","萍枯黏朽檻，沙淺露沈舟。","照影人何在，持竿客寄游。","翛然兴廢外，回首謝眠鷗。"]', '诗', 'shi', '', NULL, '題豪家故池 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ca9c81-6ddb-473d-b6f0-f6d55dc06abd', '偶題', '偶題', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["賤子曾塵國士知，登門倒屣憶當時。","西州酌盡看花酒，東閣編成詠雪詩。","莫道精靈無伯有，尋聞任俠報爰絲。","烏衣舊宅猶能認，粉竹金松一兩枝。"]', '["賤子曾塵国士知，登门倒屣憶當时。","西州酌尽看花酒，东閣編成詠雪诗。","莫道精靈無伯有，尋闻任俠報爰絲。","烏衣旧宅猶能認，粉竹金松一兩枝。"]', '诗', 'shi', '', NULL, '偶題 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef680f8-51df-4f6e-a6bd-7445a9e096ac', '渚宮立春書懷', '渚宮立春书懷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["春候侵殘臘，江蕪綠已齊。","風高鶯囀澁，雨密鴈飛低。","向日心須在，歸朝路欲迷。","近聞驚御火，猶及灞陵西。"]', '["春候侵殘臘，江蕪綠已齊。","风高鶯囀澁，雨密鴈飞低。","向日心須在，归朝路欲迷。","近闻驚御火，猶及灞陵西。"]', '诗', 'shi', '', NULL, '渚宮立春書懷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc255ba0-86d7-4a2e-99c8-6bc598f4d785', '聞李翰林遊池上有寄', '闻李翰林游池上有寄', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["花飛絮落水和流，玉署詞臣奉詔遊。","四面看人隨畫鷁，中流合樂起眠鷗。","皇恩自抱丹心報，清頌誰將白雪酬。","不爲禁鐘催入宿，前峰月上未回舟。"]', '["花飞絮落水和流，玉署词臣奉詔游。","四面看人隨畫鷁，中流合乐起眠鷗。","皇恩自抱丹心報，清頌誰將白雪酬。","不爲禁鐘催入宿，前峰月上未回舟。"]', '诗', 'shi', '', NULL, '聞李翰林遊池上有寄 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c193e382-ac66-4672-a3a3-e5ef1da08cb5', '谷口寓居偶題', '谷口寓居偶題', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["涔涔病骨怯朝天，谷口歸來取性眠。","峭壁削成開畫障，急溪飛下咽繁弦。","不能塵土爭閑事，且放形神學散仙。"]', '["涔涔病骨怯朝天，谷口归来取性眠。","峭壁削成开畫障，急溪飞下咽繁弦。","不能塵土爭闲事，且放形神学散仙。"]', '诗', 'shi', '', NULL, '谷口寓居偶題 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9e722d0-0e22-4b14-972c-dafd77af8fbc', '無題', '無題', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["萬態千端一瞬中，沁園蕪沒佇秋風。","鵁鶄夜警池塘冷，蝙蝠晝飛樓閣空。","粉貌早聞殘洛市，簫聲猶自傍秦宮。","今朝陌上相非者，曾此歌鐘幾醉同。"]', '["万態千端一瞬中，沁园蕪沒佇秋风。","鵁鶄夜警池塘冷，蝙蝠晝飞楼閣空。","粉貌早闻殘洛市，簫声猶自傍秦宮。","今朝陌上相非者，曾此歌鐘幾醉同。"]', '诗', 'shi', '', NULL, '無題 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e01a0f3-87f9-421a-b1bc-dd75a971d7dc', '賦雪', '賦雪', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一夜陰風度，平明顥氣交。","未知融結判，唯見混茫包。","路莫藏行跡，林難出樹梢。","氣應封獸穴，險必墮禽巢。","影密燈回照，聲繁竹送敲。","翫宜蘇讓點，飡稱蜜勻抄。","結凍防魚躍，黏沙費馬跑。","爐寒資爇荻，屋暖賴編茅。","遠不分山疊，低宜失地坳。","闌干高百尺，新霽若爲拋。"]', '["一夜陰风度，平明顥氣交。","未知融結判，唯见混茫包。","路莫藏行跡，林难出樹梢。","氣應封獸穴，險必墮禽巢。","影密灯回照，声繁竹送敲。","翫宜蘇讓点，飡稱蜜勻抄。","結凍防鱼躍，黏沙費马跑。","爐寒資爇荻，屋暖賴編茅。","远不分山叠，低宜失地坳。","闌干高百尺，新霽若爲拋。"]', '诗', 'shi', '', NULL, '賦雪 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1094f9b0-2b58-4678-ab6d-32f19fb2d589', '寄僧', '寄僧', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["柳拂池光一點清，紫方袍袖杖藜行。","偶傳新句來中禁，誰把閑書寄上卿。","錫倚山根重蘚破，棊敲石面碎雲生。","應憐正視淮王詔，不識東林物外情。"]', '["柳拂池光一点清，紫方袍袖杖藜行。","偶傳新句来中禁，誰把闲书寄上卿。","錫倚山根重蘚破，棊敲石面碎云生。","應怜正視淮王詔，不識东林物外情。"]', '诗', 'shi', '', NULL, '寄僧 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a135efcf-8182-437f-9f34-c836901fc2cf', '酬僧', '酬僧', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["吾師既續惠休才，況值高秋萬象開。","吟處遠峰橫落照，定中黃葉下青苔。","雙林不見金蘭久，丹楚空翻組繡來。","聞說近郊寒尚綠，登臨應待一追陪。"]', '["吾師既續惠休才，況值高秋万象开。","吟处远峰橫落照，定中黄葉下青苔。","雙林不见金蘭久，丹楚空翻組繡来。","闻说近郊寒尚綠，登臨應待一追陪。"]', '诗', 'shi', '', NULL, '酬僧 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69942c0b-dc1c-4037-b04e-99ddecf0b2b1', '題延壽坊東南角古池', '題延壽坊东南角古池', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["蔓草蕭森曲岸摧，水籠沙淺露莓苔。","更無蔟蔟紅妝點，猶有雙雙翠羽來。","雨細幾逢耕犢去，日斜時見釣人回。","繁華自古皆相似，金谷荒園土一堆。"]', '["蔓草蕭森曲岸摧，水籠沙淺露莓苔。","更無蔟蔟紅妝点，猶有雙雙翠羽来。","雨細幾逢耕犢去，日斜时见釣人回。","繁华自古皆相似，金谷荒园土一堆。"]', '诗', 'shi', '', NULL, '題延壽坊東南角古池 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5befb939-b7d2-4293-b6d7-24877158917f', '登鸛雀樓', '登鸛雀楼', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鳥在林梢脚底看，夕陽無際戍煙殘。","凍開河水奔渾急，雪洗條山錯落寒。","始爲一名拋故國，近因多難怕長安。","祖鞭掉折徒爲爾，贏得雲溪負釣竿。"]', '["鸟在林梢脚底看，夕陽無際戍煙殘。","凍开河水奔渾急，雪洗條山錯落寒。","始爲一名拋故国，近因多难怕长安。","祖鞭掉折徒爲爾，贏得云溪負釣竿。"]', '诗', 'shi', '', NULL, '登鸛雀樓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe0f461-7959-431c-8539-0562e39ab405', '和峽州馮使君題所居', '和峽州馮使君題所居', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["三年拔薤成仁政，一日誅茅葺所居。","曉岫近排吟閣冷，夜江遙響寢堂虛。","唯懷避地逃多難，不羨朝天臥直廬。","記得街西鄰舍否，投荒南去五千餘。"]', '["三年拔薤成仁政，一日誅茅葺所居。","晓岫近排吟閣冷，夜江遙响寢堂虛。","唯懷避地逃多难，不羨朝天臥直廬。","記得街西鄰舍否，投荒南去五千餘。"]', '诗', 'shi', '', NULL, '和峽州馮使君題所居 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2197313b-579a-4222-bf58-cf82dfc3673d', '秋日感事', '秋日感事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一葉飄然夕照沈，世間何事不經心。","幾人欲話雲臺峻，獨我方探禹穴深。","雞檄固應無下策，鶴書還要問中林。","自憐情爲多憂動，不爲西風白露吟。"]', '["一葉飄然夕照沈，世间何事不經心。","幾人欲話云台峻，独我方探禹穴深。","雞檄固應無下策，鹤书還要问中林。","自怜情爲多憂动，不爲西风白露吟。"]', '诗', 'shi', '', NULL, '秋日感事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85215aad-a839-48d7-a8cc-1c06fd0f4c4d', '鶯', '鶯', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["日落林西鳥未知，自先飛上最高枝。","千啼萬語不離恨，已去又來如有期。","慣識江南春早處，長驚薊北夢回時。","謝家園裏成吟久，只欠池塘一句詩。"]', '["日落林西鸟未知，自先飞上最高枝。","千啼万語不離恨，已去又来如有期。","慣識江南春早处，长驚薊北梦回时。","謝家园裏成吟久，只欠池塘一句诗。"]', '诗', 'shi', '', NULL, '鶯 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4976cdbf-ffa4-44f1-9a43-4662518cafc3', '次韻和王員外雜遊四韻', '次韻和王員外杂游四韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一分難減亦難加，得似溪頭浣越紗。","兩槳慣邀催去艇，七香曾占取來車。","黃昏忽墮當樓月，清曉休開滿鏡花。","誰見玉郎腸斷處，露牀風簟半欹斜。"]', '["一分难減亦难加，得似溪头浣越紗。","兩槳慣邀催去艇，七香曾占取来车。","黄昏忽墮當楼月，清晓休开满镜花。","誰见玉郎腸斷处，露牀风簟半欹斜。"]', '诗', 'shi', '', NULL, '次韻和王員外雜遊四韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edefb7be-8264-4ee2-a193-c94710f34e6d', '秋事', '秋事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["江天暑氣自涼清，物候須知一雨成。","松竹健來唯欠語，蕙蘭衰去始多情。","他年擬獻書空在，此日知機意盡平。","更欲輕橈放煙浪，葦花深處睡秋聲。"]', '["江天暑氣自涼清，物候須知一雨成。","松竹健来唯欠語，蕙蘭衰去始多情。","他年擬獻书空在，此日知機意尽平。","更欲轻橈放煙浪，葦花深处睡秋声。"]', '诗', 'shi', '', NULL, '秋事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7662f254-11c8-460a-8afc-8f9f7fec66c6', '和陸拾遺題諫院松', '和陸拾遺題諫院松', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["落落孤松何處尋，月華西畔結根深。","曉含仙掌三清露，晚上宮牆百雉陰。","野鶴不歸應有怨，白雲高去太無心。","碧巖秋澗休相望，捧日元須在禁林。"]', '["落落孤松何处尋，月华西畔結根深。","晓含仙掌三清露，晚上宮牆百雉陰。","野鹤不归應有怨，白云高去太無心。","碧巖秋澗休相望，捧日元須在禁林。"]', '诗', 'shi', '', NULL, '和陸拾遺題諫院松 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cc8843a-e2c2-4983-83d6-a890c3600e32', '題楊子津亭', '題楊子津亭', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["楊子江津十四經，紀行文字徧長亭。","驚人旅鬢斬新白，無事海門依舊青。","前路莫知霜凜凜，故鄉何處鴈冥冥。","可憐不識生離者，數點漁帆落暮汀。"]', '["楊子江津十四經，紀行文字徧长亭。","驚人旅鬢斬新白，無事海门依旧青。","前路莫知霜凜凜，故乡何处鴈冥冥。","可怜不識生離者，數点漁帆落暮汀。"]', '诗', 'shi', '', NULL, '題楊子津亭 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102adf2f-8824-48fa-9cf9-0197e54fb1e8', '閑望', '闲望', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["三點五點映山雨，一枝兩枝臨水花。","蛺蝶狂飛掠芳草，鴛鴦穩睡翹暖沙。","闕下新居成別業，江南舊隱是誰家。","東遷西去俱無計，却羨暝歸林上鴉。"]', '["三点五点映山雨，一枝兩枝臨水花。","蛺蝶狂飞掠芳草，鴛鴦穩睡翹暖沙。","闕下新居成別業，江南旧隐是誰家。","东遷西去俱無計，却羨暝归林上鴉。"]', '诗', 'shi', '', NULL, '閑望 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8214e95-b4bb-4b94-ad52-0e8545196a9d', '雪後過昭應', '雪後過昭應', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["路過章臺氣象寬，九重城闕在雲端。","煙含上苑沈沈紫，雪露南山悚悚寒。","綺陌已堪騎寶馬，綠蕪行即彈金丸。","灞川南北真圖畫，更待殘陽一望看。"]', '["路過章台氣象寬，九重城闕在云端。","煙含上苑沈沈紫，雪露南山悚悚寒。","綺陌已堪騎寶马，綠蕪行即彈金丸。","灞川南北真圖畫，更待殘陽一望看。"]', '诗', 'shi', '', NULL, '雪後過昭應 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3e783d1-64fe-4073-bb0e-03788183e8a1', '商人', '商人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["百尺竿頭五兩斜，此生何處不爲家。","北拋衡嶽南過鴈，朝發襄陽暮看花。","蹭蹬也應無陸地，團圓應覺有天涯。","隨風逐浪年年別，却笑如期八月槎。"]', '["百尺竿头五兩斜，此生何处不爲家。","北拋衡嶽南過鴈，朝發襄陽暮看花。","蹭蹬也應無陸地，團圓應覺有天涯。","隨风逐浪年年別，却笑如期八月槎。"]', '诗', 'shi', '', NULL, '商人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155181d2-f174-4e92-8e43-a09df28e9bf4', '岐下聞杜鵑', '岐下闻杜鵑', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["化去蠻鄉北，飛來渭水西。","爲多亡國恨，不忍故山啼。","怨已驚秦鳳，靈應識漢雞。","數聲煙漠漠，餘思草萋萋。","樓迥波無際，林昏日又低。","如何不腸斷，家近五雲溪。"]', '["化去蠻乡北，飞来渭水西。","爲多亡国恨，不忍故山啼。","怨已驚秦鳳，靈應識漢雞。","數声煙漠漠，餘思草萋萋。","楼迥波無際，林昏日又低。","如何不腸斷，家近五云溪。"]', '诗', 'shi', '', NULL, '岐下聞杜鵑 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28492d3c-f800-44f9-95c9-8962835d4f5e', '雨後聞思歸樂二首 一', '雨後闻思归乐二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["山禽連夜叫，兼雨未嘗休。","儘道思歸樂，應多離別愁。","我家方旅食，故國在滄洲。","聞此不能寐，青燈茆屋幽。"]', '["山禽連夜叫，兼雨未嘗休。","儘道思归乐，應多離別愁。","我家方旅食，故国在滄洲。","闻此不能寐，青灯茆屋幽。"]', '诗', 'shi', '', NULL, '雨後聞思歸樂二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9dc5713-5c0a-4c18-8cd7-236d7ca1f446', '雨後聞思歸樂二首 二', '雨後闻思归乐二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一夜鳥飛鳴，關關徹五更。","似因歸路隔，長使別魂驚。","未省愁雨暗，就中傷月明。","須知越吟客，欹枕不勝情。"]', '["一夜鸟飞鳴，关关徹五更。","似因归路隔，长使別魂驚。","未省愁雨暗，就中傷月明。","須知越吟客，欹枕不勝情。"]', '诗', 'shi', '', NULL, '雨後聞思歸樂二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c36636be-e8b1-4495-8b08-2be3957f9468', '中夜聞啼禽', '中夜闻啼禽', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["漠漠蒼蒼未五更，宿禽何處兩三聲。","若非西澗回波觸，即是南塘急雨驚。","金屋獨眠堪寄恨，商陵永訣更牽情。","此時歸夢隨腸斷，半壁殘燈閃閃明。"]', '["漠漠蒼蒼未五更，宿禽何处兩三声。","若非西澗回波觸，即是南塘急雨驚。","金屋独眠堪寄恨，商陵永訣更牽情。","此时归梦隨腸斷，半壁殘灯閃閃明。"]', '诗', 'shi', '', NULL, '中夜聞啼禽 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f85220c-3b3a-4472-ad7b-cfea8c8f85cb', '靈池縣見早梅', '靈池縣见早梅', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["小園晴日見寒梅，一寸鄉心萬里回。","春日暖時拋笠澤，戰塵飛處上琴臺。","棲身未識登龍地，落筆元非倚馬才。","待勒燕然歸未得，雪枝南畔少徘徊。"]', '["小园晴日见寒梅，一寸乡心万里回。","春日暖时拋笠澤，戰塵飞处上琴台。","棲身未識登龙地，落笔元非倚马才。","待勒燕然归未得，雪枝南畔少徘徊。"]', '诗', 'shi', '', NULL, '靈池縣見早梅 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71cf61e0-9d16-45f2-bb7f-d79f552965fd', '野廟', '野廟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["古原荒廟揜莓苔，何處喧喧鼓笛來。","日暮鳥歸人散盡，野風吹起紙錢灰。"]', '["古原荒廟揜莓苔，何处喧喧鼓笛来。","日暮鸟归人散尽，野风吹起紙錢灰。"]', '诗', 'shi', '', NULL, '野廟 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78afbe5d-8ae9-4570-9466-db4c37cc8404', '閑書', '闲书', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["接鷺陪鸞漫得羣，未如高臥紫溪雲。","晉陽起義尋常見，湖口屯營取次聞。","大底鷦鵬須自適，何嘗玉石不同焚。","回看帶礪山河者，濟得危時沒舊勳。"]', '["接鷺陪鸾漫得羣，未如高臥紫溪云。","晉陽起義尋常见，湖口屯營取次闻。","大底鷦鵬須自適，何嘗玉石不同焚。","回看带礪山河者，濟得危时沒旧勳。"]', '诗', 'shi', '', NULL, '閑書 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140a427c-d1f3-4a0d-893a-0b26ef4aabfe', '寄貫休上人', '寄貫休上人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["別來如夢亦如雲，八字微言不復聞。","世上浮沈應念我，筆端飛動只降君。","幾同江步吟秋霽，更憶山房語夜分。","見擬沃州尋舊約，且教丹頂許爲鄰。"]', '["別来如梦亦如云，八字微言不复闻。","世上浮沈應念我，笔端飞动只降君。","幾同江步吟秋霽，更憶山房語夜分。","见擬沃州尋旧約，且教丹頂許爲鄰。"]', '诗', 'shi', '', NULL, '寄貫休上人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ad117c-a510-405e-aadf-8ae1fd000eb1', '書懷', '书懷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["傍巖依樹結簷楹，夏物蕭疎景更清。","灘響忽高何處雨，松陰自轉遠山晴。","見多鄰犬遙相認，來慣幽禽近不驚。","爭得便誇饒勝事，九衢塵裏免勞生。"]', '["傍巖依樹結簷楹，夏物蕭疎景更清。","灘响忽高何处雨，松陰自轉远山晴。","见多鄰犬遙相認，来慣幽禽近不驚。","爭得便誇饒勝事，九衢塵裏免勞生。"]', '诗', 'shi', '', NULL, '書懷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dd1543b-b99d-4a07-b0f8-7dad85cc26a4', '重陽日荆州作', '重陽日荆州作', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["萬里投荒已自哀，高秋寓目更徘徊。","濁醪任冷難辭醉，黃菊因暄却未開。","上國莫歸戎馬亂，故人何在塞鴻來。","驚時感事俱無奈，不待殘陽下楚臺。"]', '["万里投荒已自哀，高秋寓目更徘徊。","濁醪任冷难辞醉，黄菊因暄却未开。","上国莫归戎马亂，故人何在塞鴻来。","驚时感事俱無奈，不待殘陽下楚台。"]', '诗', 'shi', '', NULL, '重陽日荆州作 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432a0cf8-f143-4731-9bce-5f62304b8e5d', '寄貫休', '寄貫休', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["休公何處在，知我宦情無。","已似馮唐老，方知武子愚。","一身仍更病，雙闕又須趨。","若得重相見，冥心學半銖。"]', '["休公何处在，知我宦情無。","已似馮唐老，方知武子愚。","一身仍更病，雙闕又須趨。","若得重相见，冥心学半銖。"]', '诗', 'shi', '', NULL, '寄貫休 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d88d4b-45cd-484f-a39a-986c49e73a04', '秋日渚宮即事', '秋日渚宮即事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["漠漠澹雲煙，秋歸澤國天。","風高還促燕，雨細未妨蟬。","靜引荒城望，涼驚旅枕眠。","更堪憔悴裏，欲泛洞庭船。"]', '["漠漠澹云煙，秋归澤国天。","风高還促燕，雨細未妨蟬。","静引荒城望，涼驚旅枕眠。","更堪憔悴裏，欲泛洞庭船。"]', '诗', 'shi', '', NULL, '秋日渚宮即事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49fcfb7b-783e-4c1e-afdc-b20dd736468b', '荆州寓居書懷', '荆州寓居书懷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一室四無鄰，荒郊接古津。","幽閑消俗態，搖落露家貧。","絕跡思浮海，修書嬾寄秦。","東西不復問，翻笑泣岐人。"]', '["一室四無鄰，荒郊接古津。","幽闲消俗態，搖落露家貧。","絕跡思浮海，修书嬾寄秦。","东西不复问，翻笑泣岐人。"]', '诗', 'shi', '', NULL, '荆州寓居書懷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ed2ebd-c708-427e-af4f-52773ed704b1', '和嚴諫議蕭山廟十韻', '和嚴諫議蕭山廟十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["澤國瞻遺廟，雲韶仰舊名。","一隅連障影，千仞落泉聲。","老狖尋危棟，秋蛇束畫楹。","路長資稅駕，歲儉絕豐盛。","默默雖難測，昭昭本至平。","豈知遷去客，自有復來兵。","美舜歌徒作，欺堯犬正獰。","近兼聞順動，敢復怨徂征。","日出天須霽，風休海自清。","肺腸無處說，一爲啓聰明。"]', '["澤国瞻遺廟，云韶仰旧名。","一隅連障影，千仞落泉声。","老狖尋危棟，秋蛇束畫楹。","路长資稅駕，歲儉絕豐盛。","默默雖难測，昭昭本至平。","豈知遷去客，自有复来兵。","美舜歌徒作，欺堯犬正獰。","近兼闻順动，敢复怨徂征。","日出天須霽，风休海自清。","肺腸無处说，一爲啓聰明。"]', '诗', 'shi', '', NULL, '和嚴諫議蕭山廟十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1806da88-cfad-40b2-9113-04d952bfc7cc', '松江晚泊', '松江晚泊', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["樹遠天疑盡，江奔地欲隨。","孤帆落何處，殘日更新離。","客是淒涼本，情爲繫滯枝。","寸腸無計免，應只楚猿知。"]', '["樹远天疑尽，江奔地欲隨。","孤帆落何处，殘日更新離。","客是淒涼本，情爲繫滯枝。","寸腸無計免，應只楚猿知。"]', '诗', 'shi', '', NULL, '松江晚泊 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e338036-ab5b-4aa5-ae1f-61d0ba657aad', '湖州溪樓書獻鄭員外', '湖州溪楼书獻鄭員外', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["危檻等飛檣，閑追晚際涼。","青林上雨色，白鳥破溪光。","目以高須極，心因靜更傷。","唯公舊相許，早晚侍長楊。"]', '["危檻等飞檣，闲追晚際涼。","青林上雨色，白鸟破溪光。","目以高須極，心因静更傷。","唯公旧相許，早晚侍长楊。"]', '诗', 'shi', '', NULL, '湖州溪樓書獻鄭員外 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4bcd42-346f-4c65-b7a9-9e3fbeb67fc0', '秋興', '秋兴', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["微雨過菰葦，野居生早涼。","襟期漸蕭灑，精爽欲飛揚。","魚買罾頭活，酒沽船上香。","不緣人不用，始道靜勝忙。"]', '["微雨過菰葦，野居生早涼。","襟期漸蕭灑，精爽欲飞揚。","鱼買罾头活，酒沽船上香。","不緣人不用，始道静勝忙。"]', '诗', 'shi', '', NULL, '秋興 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d84844a8-3590-4fee-ae0f-595f965e9592', '端居', '端居', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["片雨過前汀，端居枕簟清。","病魔隨暑退，詩思傍涼生。","別燕殷勤語，殘蟬彷彿鳴。","古來悲不盡，況我本多情。"]', '["片雨過前汀，端居枕簟清。","病魔隨暑退，诗思傍涼生。","別燕殷勤語，殘蟬彷彿鳴。","古来悲不尽，況我本多情。"]', '诗', 'shi', '', NULL, '端居 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a51f95-bc69-4ec3-b005-a7bb587a2e68', '途中', '途中', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一棹歸何處，蒼茫落照昏。","無人應失路，有樹始知春。","湖岸春耕廢，江城戰鼓喧。","儒冠解相悞，學劒盡乘軒。"]', '["一棹归何处，蒼茫落照昏。","無人應失路，有樹始知春。","湖岸春耕廢，江城戰鼓喧。","儒冠解相悞，学劒尽乘軒。"]', '诗', 'shi', '', NULL, '途中 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b67941f-14f0-4f05-af82-65fb7b0d7117', '西陵夜居', '西陵夜居', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["寒潮落遠汀，暝色入柴扃。","漏永沈沈靜，燈孤的的清。","林風移宿鳥，池雨定流螢。","盡夜成愁絕，啼蛩莫近庭。"]', '["寒潮落远汀，暝色入柴扃。","漏永沈沈静，灯孤的的清。","林风移宿鸟，池雨定流螢。","尽夜成愁絕，啼蛩莫近庭。"]', '诗', 'shi', '', NULL, '西陵夜居 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8cf389-4d62-4d9f-8e16-f58fd310aa69', '燕雛', '燕雛', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["掠水身猶重，偎風力尚微。","瓦苔難定立，簷雨忽喧歸。","未識重溟遠，先愁一葉飛。","銜泥在他日，兩兩占春暉。"]', '["掠水身猶重，偎风力尚微。","瓦苔难定立，簷雨忽喧归。","未識重溟远，先愁一葉飞。","銜泥在他日，兩兩占春暉。"]', '诗', 'shi', '', NULL, '燕雛 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9353b6-0b23-4ef4-aaa1-5e05ba9965e9', '新秋', '新秋', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["白髮又經秋，端居海上洲。","無機因事發，有涕爲時流。","新酒乘涼壓，殘碁隔夜收。","公車無路入，同拜老閑侯。"]', '["白髮又經秋，端居海上洲。","無機因事發，有涕爲时流。","新酒乘涼壓，殘碁隔夜收。","公车無路入，同拜老闲侯。"]', '诗', 'shi', '', NULL, '新秋 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('920b6e26-923b-48ac-a994-0de9506eba9e', '題越州法華寺', '題越州法华寺', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["寺在五峰陰，穿緣一徑尋。","雲藏古殿暗，石護小房深。","宿鳥連僧定，寒猨應客吟。","上方應見海，月出試登臨。"]', '["寺在五峰陰，穿緣一徑尋。","云藏古殿暗，石護小房深。","宿鸟連僧定，寒猨應客吟。","上方應见海，月出試登臨。"]', '诗', 'shi', '', NULL, '題越州法華寺 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb743dbf-45dd-4eca-8051-8bb0bbb75348', '寒食洛陽道', '寒食洛陽道', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["路岐無樂處，時節倍思家。","綵索颺輕吹，黃鸝啼落花。","連乹馳寶馬，歷祿鬬香車。","行客勝回首，看看春日斜。"]', '["路岐無乐处，时節倍思家。","綵索颺轻吹，黄鸝啼落花。","連乹驰寶马，歷祿鬬香车。","行客勝回首，看看春日斜。"]', '诗', 'shi', '', NULL, '寒食洛陽道 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a353ed2-9ece-4023-8c05-ad76712839c8', '憶事', '憶事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["去年花下把金巵，曾賦楊花數句詩。","回首朱門閉荒草，如今愁到牡丹時。"]', '["去年花下把金巵，曾賦楊花數句诗。","回首朱门閉荒草，如今愁到牡丹时。"]', '诗', 'shi', '', NULL, '憶事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b152319-c7f2-4993-8220-f606c6311d1e', '金陵遇悟空上人', '金陵遇悟空上人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["東閣無人事渺茫，老僧持鉢過丹陽。","十年栖止如何報，好與南譙剩炷香。"]', '["东閣無人事渺茫，老僧持鉢過丹陽。","十年栖止如何報，好與南譙剩炷香。"]', '诗', 'shi', '', NULL, '金陵遇悟空上人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e9ed07-47ae-4d50-acb6-93bc2963783f', '途中', '途中', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["柳弱風長在，雲輕雨易休。","不勞芳草色，更惹夕陽愁。","萬里獨歸去，五陵無與遊。"]', '["柳弱风长在，云轻雨易休。","不勞芳草色，更惹夕陽愁。","万里独归去，五陵無與游。"]', '诗', 'shi', '', NULL, '途中 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c75b80a4-ff93-45ad-9098-52befa707174', '秋園', '秋园', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["始憐春草細霏霏，不覺秋來綠漸稀。","惆悵擷芳人散盡，滿園煙露蝶高飛。"]', '["始怜春草細霏霏，不覺秋来綠漸稀。","惆悵擷芳人散尽，满园煙露蝶高飞。"]', '诗', 'shi', '', NULL, '秋園 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731da7dc-efe6-497e-a900-5e2a049c21c3', '富春', '富春', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天下有水亦有山，富春山水非人寰。","長川不是春來綠，千峰倒影落其間。"]', '["天下有水亦有山，富春山水非人寰。","长川不是春来綠，千峰倒影落其间。"]', '诗', 'shi', '', NULL, '富春 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75b2a1c1-5825-4e5e-b43b-487e4ce3ec60', '山居即事', '山居即事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["小亭前面接青崖，白石交加襯綠苔。","日暮松聲滿階砌，不關風雨鶴歸來。"]', '["小亭前面接青崖，白石交加襯綠苔。","日暮松声满階砌，不关风雨鹤归来。"]', '诗', 'shi', '', NULL, '山居即事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f88d4c6-9121-4cd4-b245-2bdc0d433522', '寓言', '寓言', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["非明非暗朦朦月，不暖不寒慢慢風。","獨臥空牀好天氣，平生閑事到心中。"]', '["非明非暗朦朦月，不暖不寒慢慢风。","独臥空牀好天氣，平生闲事到心中。"]', '诗', 'shi', '', NULL, '寓言 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('699cb47c-9f13-4f5b-b43a-b0e7445bca50', '華清宮二首 一', '华清宮二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["四郊飛雪暗雲端，唯此宮中落旋乾。","綠樹碧簷相掩映，無人知道外邊寒。"]', '["四郊飞雪暗云端，唯此宮中落旋乾。","綠樹碧簷相掩映，無人知道外邊寒。"]', '诗', 'shi', '', NULL, '華清宮二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9bb1d5-eff7-4bfc-bc2e-9644b6190ff9', '華清宮二首 二', '华清宮二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["長生祕殿倚青蒼，擬敵金庭不死鄉。","無奈逝川東去急，秦陵松柏滿殘陽。"]', '["长生祕殿倚青蒼，擬敵金庭不死乡。","無奈逝川东去急，秦陵松柏满殘陽。"]', '诗', 'shi', '', NULL, '華清宮二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a70ddb-ef27-4241-a6e5-7ca2612f7cfd', '過九成宮', '過九成宮', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鳳輦東歸二百年，九成宮殿半荒阡。","魏公碑字封蒼蘚，文帝泉聲落野田。","碧草斷霑仙掌露，綠楊猶憶御爐煙。","昇平舊事無人說，萬疊青山但一川。"]', '["鳳輦东归二百年，九成宮殿半荒阡。","魏公碑字封蒼蘚，文帝泉声落野田。","碧草斷霑仙掌露，綠楊猶憶御爐煙。","昇平旧事無人说，万叠青山但一川。"]', '诗', 'shi', '', NULL, '過九成宮 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b01c696-0d47-4af5-9ed3-23d9a39b8fbc', '出潼關', '出潼关', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["重門隨地險，一徑入天開。","華嶽眼前盡，黃河腳底來。","飛軒何滿路，丹陛正求才。","獨我疎慵質，飄然又此回。"]', '["重门隨地險，一徑入天开。","华嶽眼前尽，黄河腳底来。","飞軒何满路，丹陛正求才。","独我疎慵質，飄然又此回。"]', '诗', 'shi', '', NULL, '出潼關 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9493c2c0-8064-4199-9b05-8d3a6b0847da', '過丹陽', '過丹陽', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雲陽縣郭半郊坰，風雨蕭條萬古情。","山帶梁朝陵路斷，水連劉尹宅基平。","桂枝自折思前代，藻鑑難逢恥後生。","遺事滿懷兼滿目，不堪孤棹艤荒城。"]', '["云陽縣郭半郊坰，风雨蕭條万古情。","山带梁朝陵路斷，水連劉尹宅基平。","桂枝自折思前代，藻鑑难逢恥後生。","遺事满懷兼满目，不堪孤棹艤荒城。"]', '诗', 'shi', '', NULL, '過丹陽 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308dfc63-7280-49c3-b9bb-fd99c5603fb9', '和人題武城寺', '和人題武城寺', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["神清已覺三清近，目斷仍勞萬象牽。","渭水遠含秋草渡，漢陵高枕夕陽天。","半巖雲粉千竿竹，滿寺風雷百尺泉。","別有闌干壓行路，看人塵土竟流年。"]', '["神清已覺三清近，目斷仍勞万象牽。","渭水远含秋草渡，漢陵高枕夕陽天。","半巖云粉千竿竹，满寺风雷百尺泉。","別有闌干壓行路，看人塵土竟流年。"]', '诗', 'shi', '', NULL, '和人題武城寺 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca9a51f-6a28-4503-861c-4e9ccc95d71d', '長安里中聞猨', '长安里中闻猨', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["夾巷重門似海深，楚猨爭得此中吟。","一聲紫陌纔回首，萬里青山已到心。","慣倚客船和雨聽，可堪侯第見塵侵。","無因永夜聞清嘯，禁路人歸月自沈。"]', '["夾巷重门似海深，楚猨爭得此中吟。","一声紫陌纔回首，万里青山已到心。","慣倚客船和雨听，可堪侯第见塵侵。","無因永夜闻清嘯，禁路人归月自沈。"]', '诗', 'shi', '', NULL, '長安里中聞猨 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d34ba5-e506-443d-92f7-de044fdf2b9b', '岐下聞子規', '岐下闻子規', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["劒閣西南遠鳳臺，蜀魂何事此飛來。","偶因隴樹相迷至，唯恐邊風却送回。","只有花知啼血處，更無猨替斷腸哀。","誰憐越客曾聞處，月落江平曉霧開。"]', '["劒閣西南远鳳台，蜀魂何事此飞来。","偶因隴樹相迷至，唯恐邊风却送回。","只有花知啼血处，更無猨替斷腸哀。","誰怜越客曾闻处，月落江平晓霧开。"]', '诗', 'shi', '', NULL, '岐下聞子規 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8621f331-846e-41e2-a6d9-ec0f2e2517c3', '敷水有丐者云是馬侍中諸孫憫而有贈', '敷水有丐者云是马侍中諸孫憫而有贈', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天地塵昏九鼎危，大貂曾出武侯師。","一心忠赤山河見，百戰功名日月知。","舊宅已聞栽禁樹，諸孫仍見丐征岐。","而今不要教人識，正藉將軍死鬬時。"]', '["天地塵昏九鼎危，大貂曾出武侯師。","一心忠赤山河见，百戰功名日月知。","旧宅已闻栽禁樹，諸孫仍见丐征岐。","而今不要教人識，正藉將軍死鬬时。"]', '诗', 'shi', '', NULL, '敷水有丐者云是馬侍中諸孫憫而有贈 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12ce4af-eeb1-4d5b-960f-f6a6f1fd891f', '還俗尼', '還俗尼', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["柳眉梅額倩妝新，笑脫袈裟得舊身。","三峽却爲行雨客，九天曾是散花人。","空門付與悠悠夢，寶帳迎回暗暗春。","寄語江南徐孝克，一生長短託清塵。"]', '["柳眉梅額倩妝新，笑脫袈裟得旧身。","三峽却爲行雨客，九天曾是散花人。","空门付與悠悠梦，寶帳迎回暗暗春。","寄語江南徐孝克，一生长短託清塵。"]', '诗', 'shi', '', NULL, '還俗尼 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bdc6347-e805-4b89-b386-abbb796b1cfe', '彭門用兵後經汴路三首 一', '彭门用兵後經汴路三首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["長亭一望一徘徊，千里關河百戰來。","細柳舊營猶鏁月，[祁]連新塚已封苔。","霜凋綠野愁無際，燒接黃雲慘不開。","若比江南更牢落，子山詞賦莫興[哀]。"]', '["长亭一望一徘徊，千里关河百戰来。","細柳旧營猶鏁月，[祁]連新塚已封苔。","霜凋綠野愁無際，燒接黄云慘不开。","若比江南更牢落，子山词賦莫兴[哀]。"]', '诗', 'shi', '', NULL, '彭門用兵後經汴路三首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b305db2-e155-4f70-993f-81084e4cc89a', '彭門用兵後經汴路三首 二', '彭门用兵後經汴路三首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["隋堤風物已淒涼，堤下仍多舊戰塲。","金鏃有苔人拾得，蘆花無主鳥銜將。","秋聲暗促河聲急，野色遙連日色黃。","獨上寒城正愁絕，戍鼙驚起鴈行行。"]', '["隋堤风物已淒涼，堤下仍多旧戰塲。","金鏃有苔人拾得，蘆花無主鸟銜將。","秋声暗促河声急，野色遙連日色黄。","独上寒城正愁絕，戍鼙驚起鴈行行。"]', '诗', 'shi', '', NULL, '彭門用兵後經汴路三首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e62efb3c-8e7c-47d1-93fe-9544f271107b', '彭門用兵後經汴路三首 三', '彭门用兵後經汴路三首 三', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鐵馬雲旗夢渺茫，東來無處不堪傷。","風吹白草人行少，月落空城鬼嘯長。","一自紛爭驚宇宙，可憐蕭索絕煙光。","曾爲塞北閑遊客，遼水天山未斷腸。"]', '["鐵马云旗梦渺茫，东来無处不堪傷。","风吹白草人行少，月落空城鬼嘯长。","一自紛爭驚宇宙，可怜蕭索絕煙光。","曾爲塞北闲游客，遼水天山未斷腸。"]', '诗', 'shi', '', NULL, '彭門用兵後經汴路三首 三 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f04079-d6f1-441a-ba93-7f08da7c52ad', '寄殿院高侍御', '寄殿院高侍御', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["黃梅雨細羃長洲，柳密花疎水慢流。","釣艇正尋逋客去，繡衣方結少年遊。","風前不肯看垂手，燈下還應惜裹頭。","一夜自憐無羽翼，獨當何遜滴階愁。"]', '["黄梅雨細羃长洲，柳密花疎水慢流。","釣艇正尋逋客去，繡衣方結少年游。","风前不肯看垂手，灯下還應惜裹头。","一夜自怜無羽翼，独當何遜滴階愁。"]', '诗', 'shi', '', NULL, '寄殿院高侍御 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da73c615-65f3-4bd3-b486-979f19e20d3c', '新安道中翫流水', '新安道中翫流水', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一渠春碧弄潺潺，密竹繁花掩映間。","看處便須終日住，算來爭得此身閑。","縈紆似接迷春洞，清冷應連有雪山。","上却征車再回首，了然塵土不相關。"]', '["一渠春碧弄潺潺，密竹繁花掩映间。","看处便須終日住，算来爭得此身闲。","縈紆似接迷春洞，清冷應連有雪山。","上却征车再回首，了然塵土不相关。"]', '诗', 'shi', '', NULL, '新安道中翫流水 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0571ed01-a9b3-415e-9d4f-a3310f49272f', '憶釣舟', '憶釣舟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["青山小隱枕潺湲，一葉垂綸幾泝沿。","後浦春風隨興去，南塘秋雨有時眠。","慣衝曉霧驚羣鴈，愛颭殘陽入亂煙。","迴首無人寄惆悵，九衢塵土困揚鞭。"]', '["青山小隐枕潺湲，一葉垂綸幾泝沿。","後浦春风隨兴去，南塘秋雨有时眠。","慣衝晓霧驚羣鴈，愛颭殘陽入亂煙。","迴首無人寄惆悵，九衢塵土困揚鞭。"]', '诗', 'shi', '', NULL, '憶釣舟 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c251522a-952a-4039-a4c6-16f8d50c8a96', '靈寶縣西側津', '靈寶縣西側津', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["碧溪瀲瀲流殘陽，晴沙兩兩眠鴛鴦。","柳花無賴苦多暇，蛺蝶有情長自忙。","千里宦遊成底事，每年風景是他鄉。","高歌一曲垂鞭去，盡日無人識楚狂。"]', '["碧溪瀲瀲流殘陽，晴沙兩兩眠鴛鴦。","柳花無賴苦多暇，蛺蝶有情长自忙。","千里宦游成底事，每年风景是他乡。","高歌一曲垂鞭去，尽日無人識楚狂。"]', '诗', 'shi', '', NULL, '靈寶縣西側津 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39bdb2f4-6ce9-4873-ae3f-586600fd1b40', '即席', '即席', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["家住叢臺舊，名參絳圃新。","醉波疑奪燭，嬌態欲沈春。","伴雨聊過楚，歸雲定占秦。","桃花正濃暖，爭不浪迷人。"]', '["家住叢台旧，名參絳圃新。","醉波疑奪燭，嬌態欲沈春。","伴雨聊過楚，归云定占秦。","桃花正濃暖，爭不浪迷人。"]', '诗', 'shi', '', NULL, '即席 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f94995-cc31-466b-a87b-720371b4292c', '出遲', '出遲', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["園密花藏易，樓深月到難。","酒虛留客盡，燈暗遠更殘。","麝想眉間印，鴉知頂上盤。","文王之囿小，莫惜借人看。"]', '["园密花藏易，楼深月到难。","酒虛留客尽，灯暗远更殘。","麝想眉间印，鴉知頂上盤。","文王之囿小，莫惜借人看。"]', '诗', 'shi', '', NULL, '出遲 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1413143a-3de1-4ebe-8ef2-ff510f9a2d6a', '送僧歸日本國', '送僧归日本国', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["滄溟分故國，渺渺泛杯歸。","天盡終期到，人生此別稀。","無風亦駭浪，未午已斜暉。","繫帛何須鴈，金烏日日飛。"]', '["滄溟分故国，渺渺泛杯归。","天尽終期到，人生此別稀。","無风亦駭浪，未午已斜暉。","繫帛何須鴈，金烏日日飞。"]', '诗', 'shi', '', NULL, '送僧歸日本國 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee6b36a3-3dfb-466c-b991-062409637b3c', '送僧歸破山寺', '送僧归破山寺', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["萬里指吳山，高秋杖錫還。","別來雙闕老，歸去片雲閑。","師在有無外，我嬰塵土間。","居然本相別，不要慘離顏。"]', '["万里指吳山，高秋杖錫還。","別来雙闕老，归去片云闲。","師在有無外，我嬰塵土间。","居然本相別，不要慘離顏。"]', '诗', 'shi', '', NULL, '送僧歸破山寺 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d59f9d54-5ea5-4712-abbe-53561449d069', '夏夜有寄', '夏夜有寄', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["月上簟如水，軒高簾在鉤。","竹聲寒不夏，蛩思靜先秋。","偶得清宵興，方知白日愁。","所思何處遠，斜漢欲低流。"]', '["月上簟如水，軒高簾在鉤。","竹声寒不夏，蛩思静先秋。","偶得清宵兴，方知白日愁。","所思何处远，斜漢欲低流。"]', '诗', 'shi', '', NULL, '夏夜有寄 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d50092-8ac3-4b56-8f56-58d00812d7ad', '春詞', '春词', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鸞鏡長侵夜，鴛衾不識寒。","羞多轉面語，妬極定睛看。","金市舊居近，鈿車新造寬。","春期莫相悞，一日百花殘。"]', '["鸾镜长侵夜，鴛衾不識寒。","羞多轉面語，妬極定睛看。","金市旧居近，鈿车新造寬。","春期莫相悞，一日百花殘。"]', '诗', 'shi', '', NULL, '春詞 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6896816c-ec5d-4cdc-a45d-bc26b9a77921', '汴上晚泊', '汴上晚泊', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["亭上風猶急，橋邊月已斜。","柳寒難吐絮，浪濁不成花。","岐路春三月，園林海一涯。","蕭然正無寐，夜櫓莫咿啞。"]', '["亭上风猶急，橋邊月已斜。","柳寒难吐絮，浪濁不成花。","岐路春三月，园林海一涯。","蕭然正無寐，夜櫓莫咿啞。"]', '诗', 'shi', '', NULL, '汴上晚泊 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21309043-c1cd-4a5f-b03a-424206b0fe7e', '送僧南遊', '送僧南游', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["戰鼙鳴未已，瓶屨抵何鄉。","偶別塵中易，貪歸物外忙。","後蟬拋鄠杜，先鴈下瀟湘。","不得從師去，殷勤謝草堂。"]', '["戰鼙鳴未已，瓶屨抵何乡。","偶別塵中易，貪归物外忙。","後蟬拋鄠杜，先鴈下瀟湘。","不得從師去，殷勤謝草堂。"]', '诗', 'shi', '', NULL, '送僧南遊 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11c99f5-be8b-4633-bd1b-bd08f284b870', '戲', '戲', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["恨極同填海，情長抵導江。","丁香從小結，蓮子徹枝雙。","整髻花當檻，吹燈月在窗。","秦臺非久計，早晚降霓幢。"]', '["恨極同填海，情长抵導江。","丁香從小結，蓮子徹枝雙。","整髻花當檻，吹灯月在窗。","秦台非久計，早晚降霓幢。"]', '诗', 'shi', '', NULL, '戲 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13cce0bf-eece-4fc2-9d95-a0d559cafa2a', '雪中寄慮延讓秀才', '雪中寄慮延讓秀才', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["苦貧皆共雪，吾子豈同悲。","永日應無食，經宵必有詩。","渚宮寒過節，華省試臨期。","努力圖西去，休將凍餒辭。"]', '["苦貧皆共雪，吾子豈同悲。","永日應無食，經宵必有诗。","渚宮寒過節，华省試臨期。","努力圖西去，休將凍餒辞。"]', '诗', 'shi', '', NULL, '雪中寄慮延讓秀才 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('532dcb7b-5d14-41a9-9552-0419d49a2a1e', '花村六韻', '花村六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["地勝非離郭，花深故號村。","已憐梁雪重，仍愧楚雲繁。","山近當吟冷，泉高入夢喧。","依稀小有洞，邂逅武陵源。","月好頻移座，風輕莫閉門。","流鶯更多思，百囀待黃昏。"]', '["地勝非離郭，花深故號村。","已怜梁雪重，仍愧楚云繁。","山近當吟冷，泉高入梦喧。","依稀小有洞，邂逅武陵源。","月好頻移座，风轻莫閉门。","流鶯更多思，百囀待黄昏。"]', '诗', 'shi', '', NULL, '花村六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a49aa269-ecf3-40fb-97f1-1218103da124', '賦雪十韻', '賦雪十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雨凍輕輕下，風乹淅淅吹。","喜勝花發處，驚似客來時。","河靜膠行棹，巖空響折枝。","終無鷓鴣識，先有鶺鴒知。","馬勢晨爭急，鵰聲晚更飢。","替霜嚴柏署，藏月上龍墀。","百尺樓堪倚，千錢酒要追。","朝歸紫閣早，漏出建章遲。","臘候何曾爽，春工是所資。","遙知故溪柳，排比萬條絲。"]', '["雨凍轻轻下，风乹淅淅吹。","喜勝花發处，驚似客来时。","河静膠行棹，巖空响折枝。","終無鷓鴣識，先有鶺鴒知。","马勢晨爭急，鵰声晚更飢。","替霜嚴柏署，藏月上龙墀。","百尺楼堪倚，千錢酒要追。","朝归紫閣早，漏出建章遲。","臘候何曾爽，春工是所資。","遙知故溪柳，排比万條絲。"]', '诗', 'shi', '', NULL, '賦雪十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50f695f-84ce-4b51-b0a9-3e2682494ce1', '溪邊', '溪邊', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["溪邊花滿枝，百鳥帶香飛。","下有一白鷺，日斜翹石磯。"]', '["溪邊花满枝，百鸟带香飞。","下有一白鷺，日斜翹石磯。"]', '诗', 'shi', '', NULL, '溪邊 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58089e89-6a2c-4e3d-aa71-bbca468454a5', '長安逢故人', '长安逢故人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["歲暮長安客，相逢酒一杯。","眼前閑事靜，心裏故山來。","池影含新草，林芳動早梅。","如何不歸去，霜鬢共風埃。"]', '["歲暮长安客，相逢酒一杯。","眼前闲事静，心裏故山来。","池影含新草，林芳动早梅。","如何不归去，霜鬢共风埃。"]', '诗', 'shi', '', NULL, '長安逢故人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855cf2f9-8db2-4020-b954-b6a5df58f59d', '雨夜', '雨夜', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["旅夕那禁雨，梅天已思秋。","未明孤枕倦，相弔一燈愁。","有戀慚滄海，無機奈白頭。","何人得濃睡，溪上釣魚舟。"]', '["旅夕那禁雨，梅天已思秋。","未明孤枕倦，相弔一灯愁。","有戀慚滄海，無機奈白头。","何人得濃睡，溪上釣鱼舟。"]', '诗', 'shi', '', NULL, '雨夜 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b4af768-a047-4477-9263-67644f607c20', '旅中送遷客', '旅中送遷客', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天南不可去，君去弔靈均。","落日青山路，秋風白髮人。","言危無繼者，道在有明神。"]', '["天南不可去，君去弔靈均。","落日青山路，秋风白髮人。","言危無繼者，道在有明神。"]', '诗', 'shi', '', NULL, '旅中送遷客 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58af8754-da51-4174-a12a-01fdb62d1438', '寄尚顏師', '寄尚顏師', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["僧中難得靜，靜得是吾師。","到闕不求紫，歸山秪愛詩。","臨風翹雪足，向日剃霜髭。","自歎眠漳久，雙林動所思。"]', '["僧中难得静，静得是吾師。","到闕不求紫，归山秪愛诗。","臨风翹雪足，向日剃霜髭。","自歎眠漳久，雙林动所思。"]', '诗', 'shi', '', NULL, '寄尚顏師 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80eb4323-ac37-4940-8d29-415cb1152446', '微雨', '微雨', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天青織未徧，風急舞難成。","粉重低飛蝶，黃沈不語鶯。","自隨春靄亂，還放夕陽明。","惆悵池塘上，荷珠點點傾。"]', '["天青织未徧，风急舞难成。","粉重低飞蝶，黄沈不語鶯。","自隨春靄亂，還放夕陽明。","惆悵池塘上，荷珠点点傾。"]', '诗', 'shi', '', NULL, '微雨 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301f325c-d7bd-45e3-9fdb-45660088e2fc', '送廣利大師東歸', '送廣利大師东归', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["紫殿久霑恩，東歸過海門。","浮榮知是夢，輕別肯銷魂。","明發先晨鳥，寒棲入暝猨。","蕺山如重到，應老舊雲根。"]', '["紫殿久霑恩，东归過海门。","浮榮知是梦，轻別肯銷魂。","明發先晨鸟，寒棲入暝猨。","蕺山如重到，應老旧云根。"]', '诗', 'shi', '', NULL, '送廣利大師東歸 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3e4c7a-3f0e-4da8-9c30-240dd4aee049', '關東獻兵部劉員外', '关东獻兵部劉員外', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["昨夜星辰動，仙郎近漢關。","玳筵吟雪罷，錦帳押春還。","已到青雲上，應棲絳圃間。","臨卭有詞賦，一爲奏天顏。"]', '["昨夜星辰动，仙郎近漢关。","玳筵吟雪罷，錦帳押春還。","已到青云上，應棲絳圃间。","臨卭有词賦，一爲奏天顏。"]', '诗', 'shi', '', NULL, '關東獻兵部劉員外 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab6d24e-e3fa-4230-a33a-9829e08adbe5', '途次淮口', '途次淮口', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["寒流萬派碧，南渡見煙光。","人向隋宮近，山盤楚塞長。","有村皆綠暗，無徑不紅芳。","已帶傷春病，如何更異鄉。"]', '["寒流万派碧，南渡见煙光。","人向隋宮近，山盤楚塞长。","有村皆綠暗，無徑不紅芳。","已带傷春病，如何更異乡。"]', '诗', 'shi', '', NULL, '途次淮口 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5369ca74-bd04-4284-8309-468515269eab', '詠柳', '詠柳', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["自與鶯爲地，不教花作媒。","細應和雨斷，輕秪愛風裁。","好拂錦步障，莫遮銅雀臺。","灞陵千萬樹，日暮別離回。"]', '["自與鶯爲地，不教花作媒。","細應和雨斷，轻秪愛风裁。","好拂錦步障，莫遮銅雀台。","灞陵千万樹，日暮別離回。"]', '诗', 'shi', '', NULL, '詠柳 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431c53bb-cdd7-4dcb-a0de-b6fe758cc9f6', '武牢關遇雨', '武牢关遇雨', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["澤春關路迥，暮雨細霏霏。","帶霧昏河浪，和塵重客衣。","望中迷去騎，愁裏亂斜暉。","惆悵家山遠，溟濛溼翠微。"]', '["澤春关路迥，暮雨細霏霏。","带霧昏河浪，和塵重客衣。","望中迷去騎，愁裏亂斜暉。","惆悵家山远，溟濛溼翠微。"]', '诗', 'shi', '', NULL, '武牢關遇雨 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f65d64-837c-4159-b5ed-174064cfd0ce', '春寒', '春寒', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["固教梅忍落，休與杏藏嬌。","已過冬疑剩，將來暖未饒。","玉堦殘雪在，羅薦暗魂銷。","莫問王孫事，煙蕪正寂寥。"]', '["固教梅忍落，休與杏藏嬌。","已過冬疑剩，將来暖未饒。","玉堦殘雪在，羅薦暗魂銷。","莫问王孫事，煙蕪正寂寥。"]', '诗', 'shi', '', NULL, '春寒 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('824ddb5f-4277-439d-ab9a-88ee83e2cc18', '早發潼關', '早發潼关', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天邊月初落，馬上夢猶殘。","關樹蒼蒼曉，玉階澹澹寒。","宦遊終自苦，身世靜堪觀。","爭似山中隱，和雲枕碧湍。"]', '["天邊月初落，马上梦猶殘。","关樹蒼蒼晓，玉階澹澹寒。","宦游終自苦，身世静堪观。","爭似山中隐，和云枕碧湍。"]', '诗', 'shi', '', NULL, '早發潼關 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c67a7e7-78b5-41b4-a306-46035781d325', '送策上人', '送策上人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["昨來非有意，今去亦無心。","闕下拋新院，江南指舊林。","瓶添新澗綠，笠卸晚峰陰。","八字如相許，終辭尺組尋。"]', '["昨来非有意，今去亦無心。","闕下拋新院，江南指旧林。","瓶添新澗綠，笠卸晚峰陰。","八字如相許，終辞尺組尋。"]', '诗', 'shi', '', NULL, '送策上人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ca8aa4e-b1fc-42c4-bb64-0efef2db7fe8', '和諸學士秋夕禁直偶雪', '和諸学士秋夕禁直偶雪', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["大華積秋雪，禁闈生夜寒。","硯冰憂詔急，燈燼惜更殘。","正遂攀稽願，翻追訪戴歡。","更爲三日約，高興未將闌。"]', '["大华積秋雪，禁闈生夜寒。","硯冰憂詔急，灯燼惜更殘。","正遂攀稽願，翻追訪戴歡。","更爲三日約，高兴未將闌。"]', '诗', 'shi', '', NULL, '和諸學士秋夕禁直偶雪 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f86334b8-70f2-4d47-9c84-73401a29ef70', '御溝十六韻', '御溝十六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一水終南下，何年派作溝。","穿城初北注，過苑却東流。","繞岸清波溢，連宮瑞氣浮。","去應涵鳳沼，來必滲龍湫。","激石珠爭碎，縈堤練不收。","照花長樂曙，泛葉建章秋。","影炫金莖表，光搖綺陌頭。","旁沾畫眉府，斜入教簫樓。","有雨難澄鏡，無萍易擲鉤。","鼓宜堯女瑟，盪必蔡姬舟。","臯著通鳴鶴，津應接斗牛。","迴風還瀲瀲，和月更悠悠。","淺憶觴堪泛，深思杖可投。","秪懷涇合慮，不帶隴分愁。","自有朝宗樂，曾無潰穴憂。","不勞誇大漢，清渭貫神州。"]', '["一水終南下，何年派作溝。","穿城初北注，過苑却东流。","繞岸清波溢，連宮瑞氣浮。","去應涵鳳沼，来必滲龙湫。","激石珠爭碎，縈堤練不收。","照花长乐曙，泛葉建章秋。","影炫金莖表，光搖綺陌头。","旁沾畫眉府，斜入教簫楼。","有雨难澄镜，無萍易擲鉤。","鼓宜堯女瑟，盪必蔡姬舟。","臯著通鳴鹤，津應接斗牛。","迴风還瀲瀲，和月更悠悠。","淺憶觴堪泛，深思杖可投。","秪懷涇合慮，不带隴分愁。","自有朝宗乐，曾無潰穴憂。","不勞誇大漢，清渭貫神州。"]', '诗', 'shi', '', NULL, '御溝十六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fc091bf-83dd-498d-87e0-d82fd2575e0f', '赴闕次留獻荆南成相公三十韻', '赴闕次留獻荆南成相公三十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["分閫兼文德，持衡有武功。","荆南知獨去，海內更誰同。","拔地孤峰秀，當天一鶚雄。","雲生五色筆，月吐六鈞弓。","骨格凌秋聳，心源見底空。","神清飡沆瀣，氣逸飲洪濛。","臨事成奇策，全身仗至忠。","解鞍欺李廣，煮弩笑臧洪。","往昔逢多難，來茲故統戎。","卓旗雲夢澤，撲火細腰宮。","鏟土樓臺搆，連江雉堞籠。","似平鋪掌上，疑湧出壺中。","豈是勞人力，寧因役鬼工。","本遺三戶在，今匝萬家通。","畫舸橫青雀，危檣列綵虹。","席飛巫峽雨，袖拂宋亭風。","塲廣盤毬子，池閑引釣筒。","禮賢金璧賤，煦物雪霜融。","酒滿梁塵動，棊殘漏滴終。","儉常資澹靜，貴絕恃穹崇。","唯要臣誠顯，那求帝渥隆。","甘棠名異奭，大樹姓非馮。","自念爲遷客，方諧謁上公。","痛知遭止棘，頻歎委飄蓬。","借宅誅茅綠，分囷指粟紅。","只慚燕館盛，寧覺阮途窮。","渙汗霑明主，滄浪別釣翁。","去曾憂塞馬，歸欲逐邊鴻。","積感深於海，銜恩重極嵩。","行行柳門路，回首下離東。"]', '["分閫兼文德，持衡有武功。","荆南知独去，海內更誰同。","拔地孤峰秀，當天一鶚雄。","云生五色笔，月吐六鈞弓。","骨格凌秋聳，心源见底空。","神清飡沆瀣，氣逸饮洪濛。","臨事成奇策，全身仗至忠。","解鞍欺李廣，煮弩笑臧洪。","往昔逢多难，来茲故統戎。","卓旗云梦澤，撲火細腰宮。","鏟土楼台搆，連江雉堞籠。","似平鋪掌上，疑湧出壺中。","豈是勞人力，寧因役鬼工。","本遺三戶在，今匝万家通。","畫舸橫青雀，危檣列綵虹。","席飞巫峽雨，袖拂宋亭风。","塲廣盤毬子，池闲引釣筒。","禮賢金璧賤，煦物雪霜融。","酒满梁塵动，棊殘漏滴終。","儉常資澹静，貴絕恃穹崇。","唯要臣誠显，那求帝渥隆。","甘棠名異奭，大樹姓非馮。","自念爲遷客，方諧謁上公。","痛知遭止棘，頻歎委飄蓬。","借宅誅茅綠，分囷指粟紅。","只慚燕館盛，寧覺阮途窮。","渙汗霑明主，滄浪別釣翁。","去曾憂塞马，归欲逐邊鴻。","積感深於海，銜恩重極嵩。","行行柳门路，回首下離东。"]', '诗', 'shi', '', NULL, '赴闕次留獻荆南成相公三十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b12b96e-71fd-4dc7-8784-abbce41a332a', '三峰府內矮柏十韻', '三峰府內矮柏十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["擢秀依黃閣，移根自碧岑。","周圍雖合抱，直上豈盈尋。","遠砌行窺頂，當庭坐庇陰。","短堪驚衆木，高已讓他林。","日轉無長影，風回有細音。","不容蘿蔦附，只耐雪霜侵。","玉帳籠應匝，牙旗倚更禁。","葉低宜拂席，枝褭易抽簪。","綠澗支離久，朱門掩映深。","何須一千丈，方有歲寒心。"]', '["擢秀依黄閣，移根自碧岑。","周圍雖合抱，直上豈盈尋。","远砌行窺頂，當庭坐庇陰。","短堪驚衆木，高已讓他林。","日轉無长影，风回有細音。","不容蘿蔦附，只耐雪霜侵。","玉帳籠應匝，牙旗倚更禁。","葉低宜拂席，枝褭易抽簪。","綠澗支離久，朱门掩映深。","何須一千丈，方有歲寒心。"]', '诗', 'shi', '', NULL, '三峰府內矮柏十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683b61fa-9f91-4636-88b3-40cd02d821fa', '雪十韻', '雪十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["灑密蔽璇穹，霏霏杳莫窮。","遲於雨到地，疾甚絮隨風。","四野蒼茫際，千家晃朗中。","夜迷三繞鵲，晝斷一行鴻。","結片飛瓊樹，栽花點蘂宮。","壅應邊盡北，填合海無東。","高愛危峰積，低愁暖氣融。","月交都浩渺，日射更𤫩瓏。","送臘辭寒律，迎春入舊叢。","自憐曾末至，聊復賦玄功。"]', '["灑密蔽璇穹，霏霏杳莫窮。","遲於雨到地，疾甚絮隨风。","四野蒼茫際，千家晃朗中。","夜迷三繞鵲，晝斷一行鴻。","結片飞瓊樹，栽花点蘂宮。","壅應邊尽北，填合海無东。","高愛危峰積，低愁暖氣融。","月交都浩渺，日射更𤫩瓏。","送臘辞寒律，迎春入旧叢。","自怜曾末至，聊复賦玄功。"]', '诗', 'shi', '', NULL, '雪十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e1d1ee-7095-4b56-ba08-813c351058a4', '和睦州盧中丞題茅堂十韻', '和睦州盧中丞題茅堂十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["有士當今重，忘情自古稀。","獨開青嶂路，閑掩白雲扉。","石累千層險，泉分一帶微。","棟危猨競下，簷迥鳥爭歸。","煙冷茶鐺靜，波香蘭舸飛。","好移鍾阜蓼，莫種首陽薇。","樹密含輕霧，川空漾薄暉。","芝泥看只捧，蕙帶且休圍。","東郭鄰穿履，西林近衲衣。","瓊瑤一百字，千古見清機。"]', '["有士當今重，忘情自古稀。","独开青嶂路，闲掩白云扉。","石累千層險，泉分一带微。","棟危猨競下，簷迥鸟爭归。","煙冷茶鐺静，波香蘭舸飞。","好移鍾阜蓼，莫種首陽薇。","樹密含轻霧，川空漾薄暉。","芝泥看只捧，蕙带且休圍。","东郭鄰穿履，西林近衲衣。","瓊瑤一百字，千古见清機。"]', '诗', 'shi', '', NULL, '和睦州盧中丞題茅堂十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b7eb07-737a-453c-9a42-b0c09c259227', '奉和御製六韻', '奉和御製六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["天曉密雲開，亭亭翠葆來。","芰荷籠水殿，楊柳蔽風臺。","恩洽三時雨，歡騰萬歲雷。","日華偏照御，星彩迥分台。","葦岸縈仙棹，蓮峰倒玉杯。","獨慚歌聖德，不是侍臣才。"]', '["天晓密云开，亭亭翠葆来。","芰荷籠水殿，楊柳蔽风台。","恩洽三时雨，歡腾万歲雷。","日华偏照御，星彩迥分台。","葦岸縈仙棹，蓮峰倒玉杯。","独慚歌聖德，不是侍臣才。"]', '诗', 'shi', '', NULL, '奉和御製六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40fa7b5a-31dc-4c32-87d8-c7fb5afe22f1', '敗簾六韻', '敗簾六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["有客編來久，彌年斷不收。","不堪風作候，豈復燕爲讐。","盡見三重閣，難迷百尺樓。","伴燈微揜夢，兼扇劣遮羞。","零落亡珠綴，殷勤謝玉鉤。","涼宵何必捲，月自入軒流。"]', '["有客編来久，彌年斷不收。","不堪风作候，豈复燕爲讐。","尽见三重閣，难迷百尺楼。","伴灯微揜梦，兼扇劣遮羞。","零落亡珠綴，殷勤謝玉鉤。","涼宵何必捲，月自入軒流。"]', '诗', 'shi', '', NULL, '敗簾六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9e5cec-a7df-41a1-9141-f560b6c95109', '玉堂種竹六韻', '玉堂種竹六韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["當砌植檀欒，濃陰五月寒。","引風穿玉牖，搖露滴金盤。","有韻和宮漏，無香雜畹蘭。","地疑雲鏁易，日近雪封難。","靜稱圍棋會，閑宜閣筆看。","他年終結實，不羨樹棲鸞。"]', '["當砌植檀欒，濃陰五月寒。","引风穿玉牖，搖露滴金盤。","有韻和宮漏，無香杂畹蘭。","地疑云鏁易，日近雪封难。","静稱圍棋會，闲宜閣笔看。","他年終結實，不羨樹棲鸾。"]', '诗', 'shi', '', NULL, '玉堂種竹六韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb70773-9fcf-40cd-8e39-bfd102d344b6', '和韓致光侍郎無題三首十四韻 一', '和韓致光侍郎無題三首十四韻 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["珠佩元消暑，犀簪自辟塵。","揜燈容燕宿，開鏡待雞晨。","去嬾都忘舊，來多未厭新。","每逢憂是夢，長憶故延真。","杏小雙圓壓，山濃兩點嚬。","瘦難勝寶帶，輕欲馭飆輪。","箆鳳金雕翼，釵魚玉鏤鱗。","月明無睡夜，花落斷腸春。","解舞何須楚，能箏可在秦。","怯探同海底，稀遇極天津。","綠柰攀宮豔，青梅弄嶺珍。","管纖銀字咽，梭密錦書勻。","厭勝還隨俗，無疑不避人。","可憐三五夕，娬媚善爲鄰。"]', '["珠佩元消暑，犀簪自辟塵。","揜灯容燕宿，开镜待雞晨。","去嬾都忘旧，来多未厭新。","每逢憂是梦，长憶故延真。","杏小雙圓壓，山濃兩点嚬。","瘦难勝寶带，轻欲馭飆輪。","箆鳳金雕翼，釵鱼玉鏤鱗。","月明無睡夜，花落斷腸春。","解舞何須楚，能箏可在秦。","怯探同海底，稀遇極天津。","綠柰攀宮豔，青梅弄嶺珍。","管纖銀字咽，梭密錦书勻。","厭勝還隨俗，無疑不避人。","可怜三五夕，娬媚善爲鄰。"]', '诗', 'shi', '', NULL, '和韓致光侍郎無題三首十四韻 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9affc77-e4c0-4d8d-a4c7-8f567ab51eca', '和韓致光侍郎無題三首十四韻 二', '和韓致光侍郎無題三首十四韻 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["舞轉輕輕雪，歌霏漠漠塵。","漫遊多卜夜，慵起不知晨。","玉箸和妝裛，金蓮逐步新。","鳳笙追北里，鶴馭訪南真。","有恨都無語，非愁亦有嚬。","戲應過蚌浦，飛合入蟾輪。","杯樣成言鳥，梳文解臥鱗。","逢迎大堤晚，離別洞庭春。","似玉曾誇趙，如雲不讓秦。","錦收花上露，珠引月中津。","木爲連枝貴，禽因比翼珍。","萬峰酥點薄，五色繡妝勻。","獺髓求魚客，鮫綃托海人。","寸腸誰與達，洞府四無鄰。"]', '["舞轉轻轻雪，歌霏漠漠塵。","漫游多卜夜，慵起不知晨。","玉箸和妝裛，金蓮逐步新。","鳳笙追北里，鹤馭訪南真。","有恨都無語，非愁亦有嚬。","戲應過蚌浦，飞合入蟾輪。","杯樣成言鸟，梳文解臥鱗。","逢迎大堤晚，離別洞庭春。","似玉曾誇趙，如云不讓秦。","錦收花上露，珠引月中津。","木爲連枝貴，禽因比翼珍。","万峰酥点薄，五色繡妝勻。","獺髓求鱼客，鮫綃托海人。","寸腸誰與達，洞府四無鄰。"]', '诗', 'shi', '', NULL, '和韓致光侍郎無題三首十四韻 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47fa26c-04ed-494e-865b-a3fea9c78ee4', '和韓致光侍郎無題三首十四韻 三', '和韓致光侍郎無題三首十四韻 三', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["綺閣臨初日，銅臺拂暗塵。","鷾鴯偏報曉，烏鶂慣驚晨。","魚網裁書數，鵾弦上曲新。","病多疑厄重，語切見心真。","子母錢徵笑，西南月借嚬。","擣衣嫌獨杵，分袂怨雙輪。","貝葉教丹觜，金刀寄赤鱗。","捲簾吟塞雪，飛楫渡江春。","解織宜名蕙，能歌合姓秦。","眼穿回鴈嶺，魂斷飲牛津。","藥自偷來絕，香從竊去珍。","茗煎雲沫聚，藥種玉苗勻。","草密應迷客，花繁好避人。","長干足風雨，遙夜與誰鄰。"]', '["綺閣臨初日，銅台拂暗塵。","鷾鴯偏報晓，烏鶂慣驚晨。","鱼網裁书數，鵾弦上曲新。","病多疑厄重，語切见心真。","子母錢徵笑，西南月借嚬。","擣衣嫌独杵，分袂怨雙輪。","貝葉教丹觜，金刀寄赤鱗。","捲簾吟塞雪，飞楫渡江春。","解织宜名蕙，能歌合姓秦。","眼穿回鴈嶺，魂斷饮牛津。","藥自偷来絕，香從竊去珍。","茗煎云沫聚，藥種玉苗勻。","草密應迷客，花繁好避人。","长干足风雨，遙夜與誰鄰。"]', '诗', 'shi', '', NULL, '和韓致光侍郎無題三首十四韻 三 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8d85779-981b-4eb9-8607-ffc4348cf6e0', '倒次元韻', '倒次元韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["南陌來尋伴，東城去卜鄰。","生憎無賴客，死憶有情人。","似束腰支細，如描髮彩勻。","黃鸝裁帽貴，紫燕刻釵珍。","身近從淄右，家元接觀津。","雨臺誰屬楚，花洞不知秦。","淚滴空牀冷，妝濃滿鏡春。","枕涼欹琥珀，簟潔展麒麟。","茂苑廊千步，昭陽扇九輪。","陽城迷處笑，京兆畫時嚬。","魚子封牋短，蠅頭學字真。","易判期已遠，難諱事還新。","艇子愁衝夜，驪駒怕拂晨。","如何斷岐路，免得見行塵。"]', '["南陌来尋伴，东城去卜鄰。","生憎無賴客，死憶有情人。","似束腰支細，如描髮彩勻。","黄鸝裁帽貴，紫燕刻釵珍。","身近從淄右，家元接观津。","雨台誰屬楚，花洞不知秦。","泪滴空牀冷，妝濃满镜春。","枕涼欹琥珀，簟潔展麒麟。","茂苑廊千步，昭陽扇九輪。","陽城迷处笑，京兆畫时嚬。","鱼子封牋短，蠅头学字真。","易判期已远，难諱事還新。","艇子愁衝夜，驪駒怕拂晨。","如何斷岐路，免得见行塵。"]', '诗', 'shi', '', NULL, '倒次元韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ed0282-d420-437a-ae6d-cde935675129', '箇人三十韻', '箇人三十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["嫋嫋復盈盈，何年墜玉京。","見人還道姓，羞客不稱名。","故事諳金谷，新居近石城。","臉橫秋水溢，眉拂遠山晴。","粉薄塗雲母，簪寒篸水晶。","催來兩槳送，怕起五絲縈。","髻學盤桓綰，牀依宛轉成。","博山凝霧重，油壁隱車輕。","額點梅花樣，心通棘刺情。","搔頭邀顧遇，約指到平生。","魚網徐徐襞，螺巵淺淺傾。","芙蓉褥已展，荳蔻水休更。","趙女憐膠膩，丁娘愛燭明。","炷香龍薦腦，辟魘虎輸精。","管咽參差韻，弦嘈倰僜聲。","花殘春寂寂，月落漏丁丁。","柳絮聯章敏，椒花屬思清。","剪羅成彩字，銷蠟脫珠纓。","邂逅當投珮，難難莫拊楹。","熨來身熱定，舐得面痕平。","匣鏡金螭怒，簾旌繡獸獰。","頸長堪鶴並，腰細任蜂爭。","滴淚泉饒竭，論心石未貞。","必雙成鳳去，豈獨化蟬鳴。","書遠腸空斷，樓高膽易驚。","數錢紅帶結，鬬草蒨裙盛。","䘧柳闌干小，侵波略彴橫。","夜愁遙寄鴈，曉夢半和鶯。","翼秪思鶼比，根長羨藕幷。","可憐衣帶緩，休賦重行行。"]', '["嫋嫋复盈盈，何年墜玉京。","见人還道姓，羞客不稱名。","故事諳金谷，新居近石城。","臉橫秋水溢，眉拂远山晴。","粉薄塗云母，簪寒篸水晶。","催来兩槳送，怕起五絲縈。","髻学盤桓綰，牀依宛轉成。","博山凝霧重，油壁隐车轻。","額点梅花樣，心通棘刺情。","搔头邀顧遇，約指到平生。","鱼網徐徐襞，螺巵淺淺傾。","芙蓉褥已展，荳蔻水休更。","趙女怜膠膩，丁娘愛燭明。","炷香龙薦腦，辟魘虎輸精。","管咽參差韻，弦嘈倰僜声。","花殘春寂寂，月落漏丁丁。","柳絮聯章敏，椒花屬思清。","剪羅成彩字，銷蠟脫珠纓。","邂逅當投珮，难难莫拊楹。","熨来身熱定，舐得面痕平。","匣镜金螭怒，簾旌繡獸獰。","頸长堪鹤並，腰細任蜂爭。","滴泪泉饒竭，論心石未貞。","必雙成鳳去，豈独化蟬鳴。","书远腸空斷，楼高膽易驚。","數錢紅带結，鬬草蒨裙盛。","䘧柳闌干小，侵波略彴橫。","夜愁遙寄鴈，晓梦半和鶯。","翼秪思鶼比，根长羨藕幷。","可怜衣带緩，休賦重行行。"]', '诗', 'shi', '', NULL, '箇人三十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988d4e4c-b46a-4e42-8f82-2bfcdeb4ba05', '即席十韻', '即席十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["住處方窺宋，平生未嫁盧。","暖金輕鑄骨，寒玉細凝膚。","妬蜨長成伴，傷鸞耐得孤。","城堪迷下蔡，臺合上姑蘇。","弄眼難降柳，含茸欲鬬蒲。","生涼雲母扇，直夜博山爐。","翡翠交妝鏡，鴛鴦入畫圖。","無心同石轉，有淚約泉枯。","猨渴應須見，鷹飢秪待呼。","銀河正清淺，霓節過來無。"]', '["住处方窺宋，平生未嫁盧。","暖金轻鑄骨，寒玉細凝膚。","妬蜨长成伴，傷鸾耐得孤。","城堪迷下蔡，台合上姑蘇。","弄眼难降柳，含茸欲鬬蒲。","生涼云母扇，直夜博山爐。","翡翠交妝镜，鴛鴦入畫圖。","無心同石轉，有泪約泉枯。","猨渴應須见，鷹飢秪待呼。","銀河正清淺，霓節過来無。"]', '诗', 'shi', '', NULL, '即席十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6536e3da-09c7-42c0-814f-2552d0ea55ea', '追詠棠梨花十韻', '追詠棠梨花十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["蜀地從來勝，棠梨第一花。","更應無軟弱，別自有妍華。","不貴綃爲霧，難降綺作霞。","移須歸紫府，駐合餌丹砂。","密映彈琴宅，深藏賣酒家。","夜宜紅蠟照，春稱錦筵遮。","連廟魂棲望，飄江字繞巴。","未饒酥點薄，兼妬雪飛斜。","舊賞三年斷，新期萬里賒。","長安如種得，誰定牡丹誇。"]', '["蜀地從来勝，棠梨第一花。","更應無軟弱，別自有妍华。","不貴綃爲霧，难降綺作霞。","移須归紫府，駐合餌丹砂。","密映彈琴宅，深藏賣酒家。","夜宜紅蠟照，春稱錦筵遮。","連廟魂棲望，飄江字繞巴。","未饒酥点薄，兼妬雪飞斜。","旧賞三年斷，新期万里賒。","长安如種得，誰定牡丹誇。"]', '诗', 'shi', '', NULL, '追詠棠梨花十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfd20637-e286-4bf7-a284-ab7539fec822', '緜竹山四十韻', '緜竹山四十韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["緜竹東西隅，千峰勢相屬。","崚嶒壓東巴，連延羅古蜀。","方者露圭角，尖者鑽箭簇。","引者蛾眉彎，斂者鳶肩縮。","尾蟉青蛇盤，頸低玄兔伏。","橫來突若奔，直上森如束。","歲在作噩年，銅梁搖蠆毒。","相國京兆公，九命來作牧。","戎提虎僕毛，專奉狼頭纛。","行府寄精廬，開窗對林麓。","是時重陽後，天氣曠清肅。","茲山昏曉開，一一在人目。","霜空正泬寥，濃翠霏撲撲。","披海出珊瑚，貼天堆碧玉。","俄然陰霾作，城郭纔霢霂。","絕頂已凝雪，晃朗開紅旭。","初疑崑崙下，夭矯龍銜燭。","亦似蓬萊巔，金銀臺疊蹙。","紫霞或旁映，綺段鋪繁褥。","晚照忽斜籠，赤城差斷續。","又如煮吳鹽，萬萬盆初熟。","又如濯楚練，千千匹未軸。","又如水晶宮，蛟螭結川瀆。","又如鐘乳洞，電雷開巖谷。","丹青畫不成，造化供難足。","合有羽衣人，飄颻曳煙躅。","合有五色禽，叫嘯含仙曲。","根雖限劒門，穴必通林屋。","方諸滄海隔，欲去憂淪覆。","羣玉縹緲間，未可量往復。","何如當此境，終朝曠遐矚。","往往草檄餘，吟哦思幽獨。","早晚埽欃槍，笳鼓迎暢轂。","休飛霹靂車，罷繫蝦蟆木。","勒銘燕然山，萬代垂芬郁。","然後恣逍遙，獨往羣麋鹿。","不管安與危，不問榮與辱。","但樂濠梁魚，豈怨鍾山鵠。","紉蘭以圍腰，採芝將實腹。","石牀須臥平，一任閑雲觸。"]', '["緜竹东西隅，千峰勢相屬。","崚嶒壓东巴，連延羅古蜀。","方者露圭角，尖者鑽箭簇。","引者蛾眉彎，斂者鳶肩縮。","尾蟉青蛇盤，頸低玄兔伏。","橫来突若奔，直上森如束。","歲在作噩年，銅梁搖蠆毒。","相国京兆公，九命来作牧。","戎提虎僕毛，專奉狼头纛。","行府寄精廬，开窗对林麓。","是时重陽後，天氣曠清肅。","茲山昏晓开，一一在人目。","霜空正泬寥，濃翠霏撲撲。","披海出珊瑚，貼天堆碧玉。","俄然陰霾作，城郭纔霢霂。","絕頂已凝雪，晃朗开紅旭。","初疑崑崙下，夭矯龙銜燭。","亦似蓬萊巔，金銀台叠蹙。","紫霞或旁映，綺段鋪繁褥。","晚照忽斜籠，赤城差斷續。","又如煮吳鹽，万万盆初熟。","又如濯楚練，千千匹未軸。","又如水晶宮，蛟螭結川瀆。","又如鐘乳洞，電雷开巖谷。","丹青畫不成，造化供难足。","合有羽衣人，飄颻曳煙躅。","合有五色禽，叫嘯含仙曲。","根雖限劒门，穴必通林屋。","方諸滄海隔，欲去憂淪覆。","羣玉縹緲间，未可量往复。","何如當此境，終朝曠遐矚。","往往草檄餘，吟哦思幽独。","早晚埽欃槍，笳鼓迎暢轂。","休飞霹靂车，罷繫蝦蟆木。","勒銘燕然山，万代垂芬郁。","然後恣逍遙，独往羣麋鹿。","不管安與危，不问榮與辱。","但乐濠梁鱼，豈怨鍾山鵠。","紉蘭以圍腰，採芝將實腹。","石牀須臥平，一任闲云觸。"]', '诗', 'shi', '', NULL, '緜竹山四十韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1317c2c5-2a60-4fd7-a82e-6dd6f012392c', '祝風三十二韻', '祝风三十二韻', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["我有二頃田，長洲東百里。","環塗爲之區，積葑相連纚。","松江流其旁，春夏多苦水。","隄防苟不時，汎濫即無已。","粤余病眠久，而復家無峙。","田峻不勝荒，農功皆廢弛。","他稼已如雲，我田方欲蒔。","四際上通波，兼之葭與葦。","是時立秋後，煙露浩淒矣。","雖然遣畢功，萎約都無幾。","如何海上風，連日從空起。","似欲驅滄溟，來沃具區裏。","噫嘻爾風師，吳中多豪士。","囷倉過九年，一粒惜如死。","糴賤兼糶貴，凶年翻大喜。","只是疲羸苦，纔飢須易子。","余仍轗軻者，進趨年二紀。","秋不安一食，春不閑一晷。","腸迴爲多別，骨瘦因積毀。","咳唾莫逢人，揶揄空覩鬼。","中又值干戈，遑遑常轉徙。","故隱茅山西，今來笠澤涘。","荒者不復尋，葺者還有以。","將正陶令巾，又蓋姜肱被。","不敢務有餘，有餘必驕鄙。","所期免假匄，假匄多慚恥。","驕鄙既不生，慚恥更能弭。","自可致逍遙，無妨閱經史。","吁余將四十，滿望秪如此。","干澤尚多難，學稼茲復爾。","窮達雖繫命，禍福生所履。","天不飢死余，飄風當自止。"]', '["我有二頃田，长洲东百里。","环塗爲之區，積葑相連纚。","松江流其旁，春夏多苦水。","隄防苟不时，汎濫即無已。","粤余病眠久，而复家無峙。","田峻不勝荒，農功皆廢弛。","他稼已如云，我田方欲蒔。","四際上通波，兼之葭與葦。","是时立秋後，煙露浩淒矣。","雖然遣畢功，萎約都無幾。","如何海上风，連日從空起。","似欲驱滄溟，来沃具區裏。","噫嘻爾风師，吳中多豪士。","囷倉過九年，一粒惜如死。","糴賤兼糶貴，凶年翻大喜。","只是疲羸苦，纔飢須易子。","余仍轗軻者，進趨年二紀。","秋不安一食，春不闲一晷。","腸迴爲多別，骨瘦因積毀。","咳唾莫逢人，揶揄空覩鬼。","中又值干戈，遑遑常轉徙。","故隐茅山西，今来笠澤涘。","荒者不复尋，葺者還有以。","將正陶令巾，又蓋姜肱被。","不敢務有餘，有餘必驕鄙。","所期免假匄，假匄多慚恥。","驕鄙既不生，慚恥更能弭。","自可致逍遙，無妨閱經史。","吁余將四十，满望秪如此。","干澤尚多难，学稼茲复爾。","窮達雖繫命，禍福生所履。","天不飢死余，飄风當自止。"]', '诗', 'shi', '', NULL, '祝風三十二韻 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f93e4cf1-2aa8-48b1-9400-1d8bd8615c45', '金陵懷古', '金陵懷古', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["玉樹聲沉戰艦收，萬家冠蓋入中州。","秪應江令偏惆悵，頭白歸來是客遊。"]', '["玉樹声沉戰艦收，万家冠蓋入中州。","秪應江令偏惆悵，头白归来是客游。"]', '诗', 'shi', '', NULL, '金陵懷古 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4199478c-c61d-415d-910f-d1de38fb3ed9', '涼思', '涼思', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["松間小檻接波平，月澹煙沉暑氣清。","半夜水禽棲不定，綠荷風動露珠傾。"]', '["松间小檻接波平，月澹煙沉暑氣清。","半夜水禽棲不定，綠荷风动露珠傾。"]', '诗', 'shi', '', NULL, '涼思 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6665a9-dd07-4fd8-a1d6-12dde74e5a87', '鮫綃', '鮫綃', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雲供片段月供光，貧女寒機枉自忙。","莫道不蠶能致此，海邊何事有扶桑。"]', '["云供片段月供光，貧女寒機枉自忙。","莫道不蠶能致此，海邊何事有扶桑。"]', '诗', 'shi', '', NULL, '鮫綃 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad519c9b-65bb-4e76-96cb-7dba9f353e56', '潮', '潮', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["暮去朝來無定期，桑田長被此聲移。","蓬萊若探人間事，一日還應兩度知。"]', '["暮去朝来無定期，桑田长被此声移。","蓬萊若探人间事，一日還應兩度知。"]', '诗', 'shi', '', NULL, '潮 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db650c96-dbd9-4ad8-aba3-f0255bafa6bb', '忘憂花', '忘憂花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["繁紅落盡始淒涼，直道忘憂也未忘。","數朵殷紅似春在，春愁特此繫人腸。"]', '["繁紅落尽始淒涼，直道忘憂也未忘。","數朵殷紅似春在，春愁特此繫人腸。"]', '诗', 'shi', '', NULL, '忘憂花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25e2ba6-5ef3-4792-a40b-bcabe8b5fad3', '憶街西所居', '憶街西所居', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["衡門一別夢難稀，人欲歸時不得歸。","長憶去年寒食夜，杏花零落雨霏霏。"]', '["衡门一別梦难稀，人欲归时不得归。","长憶去年寒食夜，杏花零落雨霏霏。"]', '诗', 'shi', '', NULL, '憶街西所居 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e78d95db-88c4-4cce-ae43-502a9cf411b9', '雲', '云', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["南北東西似客身，遠峰高鳥自爲鄰。","清歌一曲猶能住，莫道無心勝得人。"]', '["南北东西似客身，远峰高鸟自爲鄰。","清歌一曲猶能住，莫道無心勝得人。"]', '诗', 'shi', '', NULL, '雲 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5c91611-3e11-4c02-9b86-4c718d7daa26', '華清宮四首 一', '华清宮四首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["中原無鹿海無波，鳳輦鸞旗出幸多。","今日故宮歸寂寞，太平功業在山河。"]', '["中原無鹿海無波，鳳輦鸾旗出幸多。","今日故宮归寂寞，太平功業在山河。"]', '诗', 'shi', '', NULL, '華清宮四首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16290bfa-6b38-45eb-9f07-3f3fb4138bcc', '華清宮四首 二', '华清宮四首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["漁陽烽火照函關，玉輦怱怱下此山。","一曲羽衣聽不盡，至今遺恨水潺潺。"]', '["漁陽烽火照函关，玉輦怱怱下此山。","一曲羽衣听不尽，至今遺恨水潺潺。"]', '诗', 'shi', '', NULL, '華清宮四首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f74d2ec-e789-4d9d-b287-10b5c62bef3f', '華清宮四首 三', '华清宮四首 三', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["上皇鑾輅重巡遊，雨淚無言獨倚樓。","惆悵眼前多少事，落花明月滿宮秋。"]', '["上皇鑾輅重巡游，雨泪無言独倚楼。","惆悵眼前多少事，落花明月满宮秋。"]', '诗', 'shi', '', NULL, '華清宮四首 三 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b406617-b0e3-4520-81d3-1491d9e52265', '華清宮四首 四', '华清宮四首 四', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["別殿和雲鏁翠微，太真遺像夢依依。","玉皇揜淚頻惆悵，應歎僧繇彩筆飛。"]', '["別殿和云鏁翠微，太真遺像梦依依。","玉皇揜泪頻惆悵，應歎僧繇彩笔飞。"]', '诗', 'shi', '', NULL, '華清宮四首 四 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3ca1487-3b1b-4758-9244-dc908801e780', '陳琳墓', '陳琳墓', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["冀州飛檄傲英雄，却把文辭事鄴宮。","縱道筆端由我得，九泉何面見袁公。"]', '["冀州飞檄傲英雄，却把文辞事鄴宮。","縱道笔端由我得，九泉何面见袁公。"]', '诗', 'shi', '', NULL, '陳琳墓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6d44c76-2b29-42d5-9bbb-2f59cd4b1b5b', '湖州朝陽樓', '湖州朝陽楼', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["十二亭亭占曉光，隋家浪說有迷藏。","仲宣題盡平生恨，別處應難看屋梁。"]', '["十二亭亭占晓光，隋家浪说有迷藏。","仲宣題尽平生恨，別处應难看屋梁。"]', '诗', 'shi', '', NULL, '湖州朝陽樓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bad5a2d-9790-415f-b9e9-38b2765d43b7', '賣花翁', '賣花翁', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["和煙和露一叢花，擔入宮城許史家。","惆悵東風無處說，不教閑地著春華。"]', '["和煙和露一叢花，擔入宮城許史家。","惆悵东风無处说，不教闲地著春华。"]', '诗', 'shi', '', NULL, '賣花翁 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb999ea-940f-4788-a12d-05fea10aac19', '自諷', '自諷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["世路升沉合自安，故人何必苦相干。","塗窮始解東歸去，莫過嚴光七里灘。"]', '["世路升沉合自安，故人何必苦相干。","塗窮始解东归去，莫過嚴光七里灘。"]', '诗', 'shi', '', NULL, '自諷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b54bb539-eacf-4d78-b004-ad4575ec6e68', '送杜鵑花', '送杜鵑花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["春紅始謝又秋紅，息國亡來入楚宮。","應是蜀冤啼不盡，更憑顏色訴西風。"]', '["春紅始謝又秋紅，息国亡来入楚宮。","應是蜀冤啼不尽，更憑顏色訴西风。"]', '诗', 'shi', '', NULL, '送杜鵑花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22caca27-1d3c-44f6-ac3f-6caeed9237f8', '西京道中聞蛙', '西京道中闻蛙', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雨餘林外夕煙沉，忽有蛙聲伴客吟。","莫怪聞時倍惆悵，稚圭蓬蓽在山陰。"]', '["雨餘林外夕煙沉，忽有蛙声伴客吟。","莫怪闻时倍惆悵，稚圭蓬蓽在山陰。"]', '诗', 'shi', '', NULL, '西京道中聞蛙 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea914d98-f82d-4028-b5f5-3bc2c1a2ccf9', '情', '情', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["依依脈脈兩如何，細以輕絲渺似波。","月不長圓花易落，一生惆悵爲伊多。"]', '["依依脈脈兩如何，細以轻絲渺似波。","月不长圓花易落，一生惆悵爲伊多。"]', '诗', 'shi', '', NULL, '情 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b86671-8f81-43b4-b33c-6e035ae072db', '送荆南從事之岳州', '送荆南從事之岳州', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["秋拂湖光一鏡開，庾郎蘭棹好徘徊。","遙知月落酒醒處，五十弦從波上來。"]', '["秋拂湖光一镜开，庾郎蘭棹好徘徊。","遙知月落酒醒处，五十弦從波上来。"]', '诗', 'shi', '', NULL, '送荆南從事之岳州 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c4b22f-0eb0-4d8e-b90c-5cc1a00cc1c1', '渡淮作', '渡淮作', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["紅杏花時辭漢苑，黃梅雨裏上淮船。","雨迎花送長如此，辜負東風十四年。"]', '["紅杏花时辞漢苑，黄梅雨裏上淮船。","雨迎花送长如此，辜負东风十四年。"]', '诗', 'shi', '', NULL, '渡淮作 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b9501af-9e1c-4ea9-871e-52983a1e4865', '薛舍人見徵恩賜香幷二十八字同寄', '薛舍人见徵恩賜香幷二十八字同寄', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["往歲知君侍武皇，今來何用紫羅囊。","都緣有意重熏裛，更灑江毫上玉堂。"]', '["往歲知君侍武皇，今来何用紫羅囊。","都緣有意重熏裛，更灑江毫上玉堂。"]', '诗', 'shi', '', NULL, '薛舍人見徵恩賜香幷二十八字同寄 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d75c518-575c-49cb-9a00-7f3da85f0267', '王母廟', '王母廟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鸞龍一夜降崑丘，遺廟千年枕碧流。","賺得武皇心力盡，忍看煙草茂陵秋。"]', '["鸾龙一夜降崑丘，遺廟千年枕碧流。","賺得武皇心力尽，忍看煙草茂陵秋。"]', '诗', 'shi', '', NULL, '王母廟 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a57e32b-96a5-4641-873c-2370d86bb7d3', '塗中阻風', '塗中阻风', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["洛陽寒食苦多風，掃蕩春華一半空。","莫道芳蹊盡成實，野花猶有未開叢。"]', '["洛陽寒食苦多风，掃蕩春华一半空。","莫道芳蹊尽成實，野花猶有未开叢。"]', '诗', 'shi', '', NULL, '塗中阻風 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af025fce-852f-4477-bc67-e45cef5eb586', '楚事', '楚事', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["悲秋應亦抵傷春，屈宋當年並楚臣。","何事從來好時節，只將惆悵付詞人。"]', '["悲秋應亦抵傷春，屈宋當年並楚臣。","何事從来好时節，只將惆悵付词人。"]', '诗', 'shi', '', NULL, '楚事 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3edd49-5fac-449f-8060-07ae88624309', '和僧詠牡丹', '和僧詠牡丹', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["萬緣銷盡本無心，何事看花恨却深。","都是支郎足情調，墜香殘蘂亦成吟。"]', '["万緣銷尽本無心，何事看花恨却深。","都是支郎足情調，墜香殘蘂亦成吟。"]', '诗', 'shi', '', NULL, '和僧詠牡丹 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0178729a-7e9a-4238-9db4-70bea1455d61', '豫讓', '豫讓', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["韓魏同謀反覆深，晉陽三板免成沉。","趙衰當面何須恨，不把干將訪負心。"]', '["韓魏同謀反覆深，晉陽三板免成沉。","趙衰當面何須恨，不把干將訪負心。"]', '诗', 'shi', '', NULL, '豫讓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26522520-569d-4c06-aa0f-f4d25a752a7a', '和寄座主尚書', '和寄座主尚书', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["偶逢戎旅戰爭日，豈是明時放逐臣。","不用裁詩苦惆悵，風雷看起臥龍身。"]', '["偶逢戎旅戰爭日，豈是明时放逐臣。","不用裁诗苦惆悵，风雷看起臥龙身。"]', '诗', 'shi', '', NULL, '和寄座主尚書 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af3d293-ce4a-429d-8379-2817324713ea', '江行', '江行', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["霞低水遠碧翻紅，一棹無邊落照中。","說示北人應不愛，錦遮泥健馬追風。"]', '["霞低水远碧翻紅，一棹無邊落照中。","说示北人應不愛，錦遮泥健马追风。"]', '诗', 'shi', '', NULL, '江行 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fa7080-e886-4483-8b35-2ad8065c26e6', '旅館梅花', '旅館梅花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["清香無以敵寒梅，可愛他鄉獨看來。","爲憶故溪千萬樹，幾年辜負雪中開。"]', '["清香無以敵寒梅，可愛他乡独看来。","爲憶故溪千万樹，幾年辜負雪中开。"]', '诗', 'shi', '', NULL, '旅館梅花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('712fc41f-4a23-44b1-9bdc-acd586d1a95c', '水鳥', '水鸟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["煙爲行止水爲家，兩兩三三睡暖沙。","爲謝離鸞兼別鵠，如何禁得向天涯。"]', '["煙爲行止水爲家，兩兩三三睡暖沙。","爲謝離鸾兼別鵠，如何禁得向天涯。"]', '诗', 'shi', '', NULL, '水鳥 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a0672e-7a9b-4219-a260-a4f040f3ac34', '楊花', '楊花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["不鬬穠華不占紅，自飛晴野雪濛濛。","百花長恨風吹落，唯有楊花獨愛風。"]', '["不鬬穠华不占紅，自飞晴野雪濛濛。","百花长恨风吹落，唯有楊花独愛风。"]', '诗', 'shi', '', NULL, '楊花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7625ab1c-7278-4e8d-ace2-4b107a3bcb50', '水調', '水調', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["鑿河千里走黃沙，沙殿西來動日華。","可道新聲是亡國，且貪惆悵後庭花。"]', '["鑿河千里走黄沙，沙殿西来动日华。","可道新声是亡国，且貪惆悵後庭花。"]', '诗', 'shi', '', NULL, '水調 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75e70f59-9df9-4a1b-8cef-e48c32091120', '秋夕樓居', '秋夕楼居', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["月裏青山淡如畫，露中黃葉颯然秋。","危欄倚徧都無寐，秪恐星河墮入樓。"]', '["月裏青山淡如畫，露中黄葉颯然秋。","危欄倚徧都無寐，秪恐星河墮入楼。"]', '诗', 'shi', '', NULL, '秋夕樓居 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fea61996-74e7-4347-98fe-5d94a3f979dd', '經苻堅墓', '經苻堅墓', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["百里煙塵散杳冥，新平一隰草青青。","八公山石君知否，休更中原作彗星。"]', '["百里煙塵散杳冥，新平一隰草青青。","八公山石君知否，休更中原作彗星。"]', '诗', 'shi', '', NULL, '經苻堅墓 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7868d8d-1f31-44aa-9162-1eda19db27b3', '松江晚泊', '松江晚泊', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["吳臺越嶠兩分津，萬萬檣烏簇夜雲。","吟盡長江一江月，更無人似謝將軍。"]', '["吳台越嶠兩分津，万万檣烏簇夜云。","吟尽长江一江月，更無人似謝將軍。"]', '诗', 'shi', '', NULL, '松江晚泊 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1647544-0610-4b9c-9927-99a1d81c3a05', '送薛學士赴任峽州二首 一', '送薛学士赴任峽州二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["負譴雖安不敢安，疊猨聲裏獨之官。","莫將彩筆閑拋擲，更待淮王詔草看。"]', '["負譴雖安不敢安，叠猨声裏独之官。","莫將彩笔闲拋擲，更待淮王詔草看。"]', '诗', 'shi', '', NULL, '送薛學士赴任峽州二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf172f66-8f96-4283-8396-6fa0c5df5cc0', '送薛學士赴任峽州二首 二', '送薛学士赴任峽州二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["片帆飛入峽雲深，帶雨兼風動楚吟。","何似玉堂裁詔罷，月斜鳷鵲漏沈沈。"]', '["片帆飞入峽云深，带雨兼风动楚吟。","何似玉堂裁詔罷，月斜鳷鵲漏沈沈。"]', '诗', 'shi', '', NULL, '送薛學士赴任峽州二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee79ca7-bc39-4d6b-bff1-7ad138999f23', '送許校書', '送許校书', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["故人言別倍依依，病裏班荆苦憶違。","明日柳亭門外路，不知誰賦送將歸。"]', '["故人言別倍依依，病裏班荆苦憶違。","明日柳亭门外路，不知誰賦送將归。"]', '诗', 'shi', '', NULL, '送許校書 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a67038-8559-4b17-8776-0d6ca9573d1a', '蛺蝶', '蛺蝶', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["兩兩自依依，南園煙露微。","住時須並住，飛處要交飛。","草淺憂驚吹，花殘惜晚暉。","長交擷芳女，夜夢遠人歸。"]', '["兩兩自依依，南园煙露微。","住时須並住，飞处要交飞。","草淺憂驚吹，花殘惜晚暉。","长交擷芳女，夜梦远人归。"]', '诗', 'shi', '', NULL, '蛺蝶 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f961116a-31f0-40a1-a975-d2276e15dcbc', '閿鄉寓居十首 阿對泉', '閿乡寓居十首 阿对泉', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["六載抽毫侍禁闈，可堪多病決然歸。","五陵年少如相問，阿對泉頭一布衣。"]', '["六載抽毫侍禁闈，可堪多病決然归。","五陵年少如相问，阿对泉头一布衣。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 阿對泉 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd7828e-e5d9-4cff-825d-bfd9162b4e32', '閿鄉寓居十首 蛙聲', '閿乡寓居十首 蛙声', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["穉珪倫鑒未精通，只把蛙聲鼓吹同。","君聽月明人靜夜，肯饒天籟與松風。"]', '["穉珪倫鑒未精通，只把蛙声鼓吹同。","君听月明人静夜，肯饒天籟與松风。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 蛙聲 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaec0e58-c798-41e7-a86a-0b41e8be84d6', '閿鄉寓居十首 茆堂', '閿乡寓居十首 茆堂', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["結得茆簷瞰碧溪，閑雲之外不同棲。","猶嫌未遠函關道，正睡剛聞報曉雞。"]', '["結得茆簷瞰碧溪，闲云之外不同棲。","猶嫌未远函关道，正睡剛闻報晓雞。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 茆堂 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15f6872d-0eac-41d5-bcfd-2cfadc472014', '閿鄉寓居十首 清溪', '閿乡寓居十首 清溪', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["清溪見底露蒼苔，密竹垂藤鏁不開。","應是仙家在深處，愛流花片引人來。"]', '["清溪见底露蒼苔，密竹垂藤鏁不开。","應是仙家在深处，愛流花片引人来。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 清溪 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d83713-8403-49bd-b9e6-c879e0b3f413', '閿鄉寓居十首 釣竿', '閿乡寓居十首 釣竿', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["曾拋釣渚入秦關，今却持竿傍碧灘。","認得舊溪兼舊意，恰如羊祜識金環。"]', '["曾拋釣渚入秦关，今却持竿傍碧灘。","認得旧溪兼旧意，恰如羊祜識金环。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 釣竿 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('112a3c20-eaa9-4238-9d42-1460ad3d7580', '閿鄉寓居十首 山僧', '閿乡寓居十首 山僧', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["石臼山頭有一僧，朝無香積夜無燈。","近嫌俗客知蹤跡，擬向中方斷石層。"]', '["石臼山头有一僧，朝無香積夜無灯。","近嫌俗客知蹤跡，擬向中方斷石層。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 山僧 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6402ed5d-7f5a-4de2-9839-455dd8b31fef', '閿鄉寓居十首 小徑', '閿乡寓居十首 小徑', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["礙竹妨花一徑幽，攀援可到玉峰頭。","若教須作康莊好，更有高車駟馬憂。"]', '["礙竹妨花一徑幽，攀援可到玉峰头。","若教須作康莊好，更有高车駟马憂。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 小徑 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf5078d-a27c-49d6-b0eb-89f080eae811', '閿鄉寓居十首 聞提壺鳥', '閿乡寓居十首 闻提壺鸟', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["早於批鵊巧於鶯，故國春林足此聲。","今在天涯別館裏，爲君沽酒復何情。"]', '["早於批鵊巧於鶯，故国春林足此声。","今在天涯別館裏，爲君沽酒复何情。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 聞提壺鳥 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a80866c-b97f-4238-bbed-a9130ee11a61', '閿鄉寓居十首 木塔偶題', '閿乡寓居十首 木塔偶題', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["西南古剎近芳林，偶得高秋試一吟。","無限黃花襯黃葉，可須春月始傷心。"]', '["西南古剎近芳林，偶得高秋試一吟。","無限黄花襯黄葉，可須春月始傷心。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 木塔偶題 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('588013e0-8b74-48e9-8419-273de5a54206', '閿鄉寓居十首 山禽', '閿乡寓居十首 山禽', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["碧嶂爲家烟外棲，銜紅啄翠入芳蹊。","可能知我心無定，頻褭花枝拂面啼。"]', '["碧嶂爲家烟外棲，銜紅啄翠入芳蹊。","可能知我心無定，頻褭花枝拂面啼。"]', '诗', 'shi', '', NULL, '閿鄉寓居十首 山禽 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ed0a49-6ef7-4ece-a11d-560ea512386a', '聞歌', '闻歌', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["貫珠一夜奏纍纍，盡是荀家舊教詞。","落盡梁塵腸不斷，九原誰報小憐知。"]', '["貫珠一夜奏纍纍，尽是荀家旧教词。","落尽梁塵腸不斷，九原誰報小怜知。"]', '诗', 'shi', '', NULL, '聞歌 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7274b0-1de4-4dfc-ad69-dbec82fd0c6b', '即席', '即席', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["竹引絲隨褭翠樓，滿筵驚動玉關秋。","何人借與丹青筆，畫取當時八字愁。"]', '["竹引絲隨褭翠楼，满筵驚动玉关秋。","何人借與丹青笔，畫取當时八字愁。"]', '诗', 'shi', '', NULL, '即席 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcac5e8e-ceb0-4fa9-b3d4-79f5577b7cdb', '便殿候對', '便殿候对', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["宣呼晝入蘂珠宮，玉女窗扉薄霧籠。","待得華胥春夢覺，半竿斜日下廂風。"]', '["宣呼晝入蘂珠宮，玉女窗扉薄霧籠。","待得华胥春梦覺，半竿斜日下廂风。"]', '诗', 'shi', '', NULL, '便殿候對 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d07a99b-2cbe-4c96-87ca-9093fab87f30', '南遷途中作七首 登七盤嶺二首 一', '南遷途中作七首 登七盤嶺二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["才非賈傅亦遷官，五月驅羸上七盤。","從此自知身計定，不能迴首望長安。"]', '["才非賈傅亦遷官，五月驱羸上七盤。","從此自知身計定，不能迴首望长安。"]', '诗', 'shi', '', NULL, '南遷途中作七首 登七盤嶺二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec143f8-86e9-41cf-b5cd-edcc80327aca', '南遷途中作七首 登七盤嶺二首 二', '南遷途中作七首 登七盤嶺二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["七盤嶺上一長號，將謂青天鑒鬱陶。","近日青天都不鑒，七盤應是未高高。"]', '["七盤嶺上一长號，將謂青天鑒鬱陶。","近日青天都不鑒，七盤應是未高高。"]', '诗', 'shi', '', NULL, '南遷途中作七首 登七盤嶺二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314ceb38-f168-4cd2-a9f8-2bcdc46264fc', '南遷途中作七首 渡漢江初嘗鯿魚有作', '南遷途中作七首 渡漢江初嘗鯿鱼有作', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["嘯父知機先憶魚，季[鷹]無事已思鱸。","自慙初識查頭味，正是栖栖哭阮塗。"]', '["嘯父知機先憶鱼，季[鷹]無事已思鱸。","自慙初識查头味，正是栖栖哭阮塗。"]', '诗', 'shi', '', NULL, '南遷途中作七首 渡漢江初嘗鯿魚有作 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f471509-68c5-4172-b73e-a0833b2cc54e', '南遷途中作七首 溪翁', '南遷途中作七首 溪翁', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["飯稻羹菰曉復昏，碧灘聲裏長諸孫。","應嗟獨上涔陽客，排比椒漿奠楚魂。"]', '["飯稻羹菰晓复昏，碧灘声裏长諸孫。","應嗟独上涔陽客，排比椒漿奠楚魂。"]', '诗', 'shi', '', NULL, '南遷途中作七首 溪翁 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42883b33-1a01-45bb-8db6-03ee619a59ec', '南遷途中作七首 寄友人', '南遷途中作七首 寄友人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["驚魂往往坐疑飄，便好爲文慰寂寥。","若待清湘葬魚了，縱然招得不堪招。"]', '["驚魂往往坐疑飄，便好爲文慰寂寥。","若待清湘葬鱼了，縱然招得不堪招。"]', '诗', 'shi', '', NULL, '南遷途中作七首 寄友人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3aea9ab-a805-4883-82a0-a6fb3f580114', '南遷途中作七首 塗中偶懷', '南遷途中作七首 塗中偶懷', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["無路能酬國士恩，短亭寂寂到黃昏。","迴腸一寸危如綫，賴得商山未有猨。"]', '["無路能酬国士恩，短亭寂寂到黄昏。","迴腸一寸危如綫，賴得商山未有猨。"]', '诗', 'shi', '', NULL, '南遷途中作七首 塗中偶懷 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2332fa43-4551-4c0a-bf54-c49c5a71a435', '南遷途中作七首 訪貫休上人', '南遷途中作七首 訪貫休上人', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["休公爲我設蘭湯，方便教人學洗腸。","自覺塵纓頓瀟灑，南行不復問滄浪。"]', '["休公爲我設蘭湯，方便教人学洗腸。","自覺塵纓頓瀟灑，南行不复问滄浪。"]', '诗', 'shi', '', NULL, '南遷途中作七首 訪貫休上人 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68388f75-23bc-4c5b-9551-fac0b6451097', '鴛鴦', '鴛鴦', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["翠翹紅頸覆金衣，灘上雙雙去又歸。","長短死生無兩處，可憐黃鵠愛分飛。"]', '["翠翹紅頸覆金衣，灘上雙雙去又归。","长短死生無兩处，可怜黄鵠愛分飞。"]', '诗', 'shi', '', NULL, '鴛鴦 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f1cfdd7-b74a-4c9c-a7e9-18cc604e0d71', '野步', '野步', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["一曲兩曲澗邊草，千枝萬枝村落花。","攜筇深去不知處，幾歎山阿隔酒家。"]', '["一曲兩曲澗邊草，千枝万枝村落花。","携筇深去不知处，幾歎山阿隔酒家。"]', '诗', 'shi', '', NULL, '野步 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ae077cb-f978-4c2b-ad70-07b41857abe5', '詶僧', '詶僧', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["玉堂全不限常朝，臥待重城宿霧銷。","翻憶故山深雪裏，滿爐枯柏帶煙燒。"]', '["玉堂全不限常朝，臥待重城宿霧銷。","翻憶故山深雪裏，满爐枯柏带煙燒。"]', '诗', 'shi', '', NULL, '詶僧 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400f3d94-c63c-4d36-b72a-06cea3a00ce7', '買帶花櫻桃', '買带花櫻桃', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["粉紅輕淺靚妝新，和露和煙別近隣。","萬一有情應有恨，一年榮落兩家春。"]', '["粉紅轻淺靚妝新，和露和煙別近隣。","万一有情應有恨，一年榮落兩家春。"]', '诗', 'shi', '', NULL, '買帶花櫻桃 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68e4f1f4-8924-4109-9547-3c041c8fceaf', '海棠二首 一', '海棠二首 一', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["太尉園林兩樹春，年年奔走探花人。","今來獨倚荆山看，迴首長安落戰塵。"]', '["太尉园林兩樹春，年年奔走探花人。","今来独倚荆山看，迴首长安落戰塵。"]', '诗', 'shi', '', NULL, '海棠二首 一 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcfda263-7795-460b-920f-d09ab6340ea4', '海棠二首 二', '海棠二首 二', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["雲綻霞鋪錦水頭，占春顏色最風流。","若教更近天街種，馬上多逢醉五侯。"]', '["云綻霞鋪錦水头，占春顏色最风流。","若教更近天街種，马上多逢醉五侯。"]', '诗', 'shi', '', NULL, '海棠二首 二 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('544b44ae-7815-40c5-a167-e6c5496c78eb', '送僧上峽歸東蜀', '送僧上峽归东蜀', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["巴字江流一棹迴，紫袈裟是禁中裁。","如從十二峰前過，莫賦佳人殊未來。"]', '["巴字江流一棹迴，紫袈裟是禁中裁。","如從十二峰前過，莫賦佳人殊未来。"]', '诗', 'shi', '', NULL, '送僧上峽歸東蜀 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975c1ce5-9354-4aee-b626-b3ab70eb00c5', '杏花', '杏花', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["春物競相妬，杏花應最嬌。","紅輕欲愁殺，粉薄似啼銷。","願作南華蝶，翩翩繞此條。"]', '["春物競相妬，杏花應最嬌。","紅轻欲愁殺，粉薄似啼銷。","願作南华蝶，翩翩繞此條。"]', '诗', 'shi', '', NULL, '杏花 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35814ca2-e6f2-46fe-a6f8-1c9f58da10b7', '草', '草', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["染亦不可成，畫亦不可得。","萇弘未死時，應無此顏色。"]', '["染亦不可成，畫亦不可得。","萇弘未死时，應無此顏色。"]', '诗', 'shi', '', NULL, '草 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d665aee6-1b82-4352-ac73-ff5f923cf875', '和楊侍郎', '和楊侍郎', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["目極家山遠，身拘禁苑深。","煙霄慙暮齒，麋鹿媿初心。"]', '["目極家山远，身拘禁苑深。","煙霄慙暮齒，麋鹿媿初心。"]', '诗', 'shi', '', NULL, '和楊侍郎 吳融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc59696-dfed-4718-80c2-1330d1688fe0', '山居喜友人相訪', '山居喜友人相訪', '30e67692-6b75-48ce-a0b0-d868b91b2849', '唐', '["秋雨空山夜，非君不此來。","高於剡溪雪，一棹到門回。"]', '["秋雨空山夜，非君不此来。","高於剡溪雪，一棹到门回。"]', '诗', 'shi', '', NULL, '山居喜友人相訪 吳融 shi');
